(window.ST=window.ST||{}).stories=[{"id":"atlab_aang","name":"Aang","chapters":[{"id":"atlab_aang_farewell","i":0,"title":null,"req":null,"reward":null,"side":false,"lines":[{"a":"atlab_aang","t":"Comerciante, Appa ya ha descansado."},{"a":"atlab_aang","t":"Supongo que es hora de despedirnos..."},{"a":"atlab_sokka","t":"No te pongas triste, ¡volveremos a visitaros!"},{"a":"atlab_aang","t":"¡Es verdad! ¿Te acuerdas del camino, Sokka?"},{"a":"atlab_sokka","t":"Uf, pues... no me fijé..."},{"a":"atlab_sokka","t":"Ay... En fin, ¡tenemos cosas muy importantes que hacer con toda esta historia del Avatar!"},{"a":"atlab_sokka","t":"Venga, Momo. ¡Nos vamos!"},{"a":"atlab_aang","t":"¡Momo! ¿Momo?"},{"a":"atlab_aang","t":"Te gusta este lugar, ¿eh? Está bien..."},{"a":"atlab_aang","t":"Comerciante, ¿te importaría cuidar de Momo un tiempo?"},{"a":"atlab_aang","t":"Te prometo que volveré a por ti, Momo."},{"a":"atlab_aang","t":"Vamos, Sokka. Gracias por todo, comerciante."},{"a":"atlab_sokka","t":"¡Hasta pronto!"},{"a":"atlab_aang","t":"¡Vamos, Appa! ¡Uuh, uuh!"}]},{"id":"atlab_aang_01","i":1,"title":"Giro erróneo del destino","req":"atlab_aang:1","reward":{"k":"tokens","id":"tokens","q":5,"n":"Fichas de la fortuna"},"side":false,"lines":[{"a":"inn","t":"Perdona, chaval. No me he enterado de todo. ¿Puedes repetirme la historia desde el principio?"},{"a":"atlab_aang","t":"¡Sí, disculpa!"},{"a":"atlab_aang","t":"Me llamo Aang, y soy el Avatar."},{"a":"atlab_aang","t":"Mis amigos y yo viajamos a lomos de mi bisonte volador..."},{"a":"atlab_aang","t":"De repente, nos desviamos y terminamos aquí."},{"a":"inn","t":"¿Me estás diciendo que ese buey enorme puede volar?"},{"a":"atlab_aang","t":"¡Sí! Se llama Appa y es muy simpático."},{"a":"inn","t":"Parece que está reventado. Os persigue alguien, ¿verdad?"},{"a":"atlab_aang","t":"Ah, pues..."},{"a":"inn","t":"No te preocupes. Quien viva bajo mi techo estará a salvo. Palabra de Óscar."},{"a":"inn","t":"Te propongo algo: ¿os gustaría quedaros aquí gratis?"},{"a":"atlab_aang","t":"¿Gratis? ¡¿Lo dices de verdad?!"},{"a":"inn","t":"Para empezar, ese dinero tan extraño no tiene ningún valor aquí."},{"a":"inn","t":"Y no voy a permitir que unos niños duerman en la calle."},{"a":"atlab_aang","t":"¡Muchísimas gracias, señor Óscar!"},{"a":"inn","t":"Pareces un crío muy hábil. ¿Por qué no ayudas al comerciante a cambio del alojamiento?"},{"a":"atlab_aang","t":"Claro que sí, ¡muchas gracias!"}]},{"id":"atlab_aang_02","i":2,"title":"¿Dominar el fuego?","req":"atlab_aang:2","reward":{"k":"tokens","id":"tokens","q":5,"n":"Fichas de la fortuna"},"side":false,"lines":[{"a":"inn","t":"Acércate, Lilu. Quiero presentarte a mi nuevo amigo."},{"a":"lilu","t":"¡Hola! Nunca había visto unos tatuajes así..."},{"a":"atlab_aang","t":"Me llamo Aang. ¡Yo tampoco había visto un sombrero como ese!"},{"a":"inn","t":"Venga, Aang. Enséñale el truco ese."},{"a":"atlab_aang","t":"Te refieres a... ¿esto?"},{"a":"lilu","t":"¿Cómo lo has hecho? ¡No he sentido ninguna magia!"},{"a":"atlab_aang","t":"Domino el aire, y también la tierra y el agua."},{"a":"lilu","t":"¡Es increíble! Espera, voy a tomar notas..."},{"a":"lilu","t":"¿Será el chi? Nunca había visto a nadie hacer algo así..."},{"a":"atlab_aang","t":"¡Exacto! Lo cierto es que no todo el mundo puede hacerlo; tienes que nacer con ese don y aprender a dominarlo."},{"a":"lilu","t":"Has dicho que dominas el aire, la tierra y el agua... Faltaría el fuego, ¿no?"},{"a":"atlab_aang","t":"Uy, es que... todavía no domino el fuego..."},{"a":"atlab_aang","t":"Me está costando encontrar un Maestro del Fuego que me enseñe."},{"a":"lilu","t":"¿En serio? Pues yo sé un poco de magia ígnea."},{"a":"lilu","t":"No es lo mismo, pero quizá quieras ver en qué consiste."},{"a":"atlab_aang","t":"Sí, claro... Gracias, Lilu."}]},{"id":"atlab_aang_03","i":3,"title":"La leyenda de Aang","req":"atlab_aang:3","reward":{"k":"tokens","id":"tokens","q":5,"n":"Fichas de la fortuna"},"side":false,"lines":[{"a":"elderowen","t":"¿Te gusta la vida en la ciudad, Aang?"},{"a":"atlab_aang","t":"¡Hola, Owen! Sí, me encanta. Muchas gracias por vuestra hospitalidad."},{"a":"elderowen","t":"De nada. Pero, dime una cosa: ¿dónde están tus padres?"},{"a":"atlab_aang","t":"Ah... No... No tengo padres."},{"a":"atlab_aang","t":"La Nación del Fuego asesinó a todos los Nómadas del Aire, mi familia."},{"a":"atlab_aang","t":"Soy el único superviviente..."},{"a":"elderowen","t":"Cielo santo. Lo siento muchísimo..."},{"a":"elderowen","t":"Si no tienes un lugar al que volver, ¿por qué no te quedas aquí con tus amigos?"},{"a":"elderowen","t":"Estoy seguro de que a la gente le encantaría la idea. ¡Os habéis vuelto muy populares!"},{"a":"atlab_aang","t":"Es una oferta muy generosa, pero no puedo aceptarla..."},{"a":"atlab_aang","t":"En este mismo instante, el Señor del Fuego Ozai está planeando su próximo movimiento."},{"a":"atlab_aang","t":"Cuando el Cometa de Sozin vuelva a iluminar el cielo, la Nación del Fuego conquistará mi mundo..."},{"a":"atlab_aang","t":"El Reino de la Tierra, las Tribus del Agua... Todos sufrirán el mismo destino que los Nómadas del Aire."},{"a":"atlab_aang","t":"Soy el Avatar, y el único que puede detenerlo..., pero todavía no estoy listo."},{"a":"elderowen","t":"Es una carga muy pesada para un niño..."},{"a":"elderowen","t":"Hagas lo que hagas, quiero que sepas que cuentas con el apoyo de la toda la ciudad."},{"a":"atlab_aang","t":"Gracias, Owen. Ya habéis hecho muchísimo por nosotros."},{"a":"atlab_aang","t":"Cuando todo esto termine, volveremos a visitaros."}]},{"id":"atlab_aang_04","i":4,"title":"Augurio de Sozin","req":"atlab_aang:4","reward":{"k":"tokens","id":"tokens","q":5,"n":"Fichas de la fortuna"},"side":false,"lines":[{"a":"mana","t":"Por fin nos encontramos, Avatar."},{"a":"atlab_aang","t":"¿Quién eres y cómo sabes quién soy?"},{"a":"mana","t":"La presencia del Avatar brilla como un faro para el tercer ojo."},{"a":"atlab_aang","t":"Aaah, eso de adivinar el futuro no va conmigo."},{"a":"mana","t":"Tú, que eres muchos, sigues incompleto..."},{"a":"mana","t":"Te espera una temible batalla con el Señor del Fuego."},{"a":"atlab_aang","t":"¿Conoces a Ozai?"},{"a":"mana","t":"Bajo la atenta mirada del cometa, la tierra se resquebrajará y los campos quedarán reducidos a cenizas."},{"a":"atlab_aang","t":"¡Eso ya lo sé! Dime qué puedo hacer."},{"a":"mana","t":"Nadie puede destruir el flujo del destino."},{"a":"atlab_aang","t":"..."},{"a":"mana","t":"Pero alguien valiente puede tirar de todas las cuerdas y guiarlo."},{"a":"mana","t":"Un aliado poco probable y una alianza frágil podrían ser la clave."},{"a":"atlab_aang","t":"Gracias, adivina... Meditaré tus palabras."},{"a":"mana","t":"..."},{"a":"mana","t":"Ten valor, Avatar. Sé fiel a ti mismo, y superarás todos tus obstáculos."}]}]},{"id":"malady","name":"Afección","chapters":[{"id":"malady_01","i":1,"title":"Escrito en piedra","req":"malady:1","reward":{"k":"gems","id":"gems","q":10,"n":"Joyas"},"side":false,"lines":[{"a":"argon","t":"¡Misión completada! Niños perdidos encontrados y rescatados."},{"a":"argon","t":"De verdad que las ruinas de Cronos no es un lugar seguro para jugar."},{"a":"argon","t":"¡Será mejor que yo también me marche!"},{"a":"malady","t":"Espero que los malvados trascos me dejen hoy en paz."},{"a":"argon","t":"¡Hola, señorita! ¿Usted también se ha perdido?"},{"a":"malady","t":"No... ¡No te acerques más!"},{"a":"argon","t":"¿Eh?"},{"a":"argon_stone","t":"..."},{"a":"malady","t":"Si me miras a los ojos, te convertirás en piedra para siempre. Es la maldición de Medusa."},{"a":"malady","t":"Pero... pareces simpático."},{"a":"malady","t":"Lo siento."}]},{"id":"malady_02","i":2,"title":"Él es mármol","req":"malady:2","reward":{"k":"gems","id":"gems","q":10,"n":"Joyas"},"side":false,"lines":[{"a":"lilu","t":"Mmm... Anciano... Owen..."},{"a":"elderowen","t":"¡Lilu! ¿¡Qué haces arrastrando una estatua!?"},{"a":"elderowen","t":"Una estatua de... ¿¡Argon!?"},{"a":"lilu","t":"Uf, uf... ¡Esa estatua es Argon!"},{"a":"elderowen","t":"Madre mía. ¿Lo han petrificado?"},{"a":"lilu","t":"Eso creo. Me lo encontré así en las ruinas de Cronos."},{"a":"lilu","t":"¡Menos mal que Rudo me ayudó a traerlo la mitad del camino!"},{"a":"elderowen","t":"Menudo lío. ¿Puedes curarlo?"},{"a":"lilu","t":"¡Puede ser! Pero los ingredientes son poco comunes, así que no será fácil."},{"a":"lilu","t":"Reuniré a los ciudadanos, y también al comerciante. ¡Te dejo a cargo de Argon!"},{"a":"elderowen","t":"Por supuesto. Espero que no te importe pasar un tiempo como adorno de jardín, muchacho."},{"a":"argon_stone","t":"..."},{"a":"elderowen","t":"¡Oh, malditas palomas! ¡Largo!"}]},{"id":"malady_03","i":3,"title":"Ojo por ojo","req":"malady:3","reward":{"k":"gems","id":"gems","q":10,"n":"Joyas"},"side":false,"lines":[{"a":"lilu","t":"Esta enredadera frondosa es suficientemente vieja, así que valdrá. No quedan muchas de estas..."},{"a":"lilu","t":"Luego toca... sangre de Medusa. Eso no será fácil."},{"a":"malady","t":"Mm..."},{"a":"lilu","t":"¡Ay! ¡Monstruo!"},{"a":"malady","t":"¿El humano de antes es amigo tuyo?"},{"a":"lilu","t":"¿Argon? Un momento, ¿tú le has hecho eso?"},{"a":"lilu","t":"Bueno, eso me facilita mucho las cosas. Resulta que también necesito un poco de sangre de Medusa..."},{"a":"malady","t":"¡No, por favor! No quiero hacerle daño a nadie."},{"a":"lilu","t":"¡Venga ya! ¡Lo has convertido en piedra!"},{"a":"malady","t":"Lo siento. Tenía miedo, y nuestras miradas se encontraron."},{"a":"malady","t":"No supe reaccionar... Nadie había sido amable conmigo antes."},{"a":"lilu","t":"Vaya, lo has pasado mal."},{"a":"malady","t":"Si necesitas sangre, te la daré."},{"a":"malady","t":"Pero, a cambio, por favor, llévame contigo. Me gustaría disculparme con él."},{"a":"lilu","t":"Está bien. No me hace gracia, pero si me convierto en piedra, no creo que Donovan nos salve."},{"a":"lilu","t":"No te quitaré la vista de encima. ¡Pero tú no me mires a mí!"},{"a":"malady","t":"Sí. Gracias."}]},{"id":"malady_04","i":4,"title":"Regreso de la carne y hueso","req":"malady:4","reward":{"k":"gems","id":"gems","q":10,"n":"Joyas"},"side":false,"lines":[{"a":"lilu","t":"¡Todo listo! Esta poción debería funcionar. ¡Toma!"},{"a":"argon","t":"¡Aaaah! ¡Qué gusto da estirarse!"},{"a":"argon","t":"Espera, ¿qué ha pasado?"},{"a":"lilu","t":"Malady te convirtió en piedra por accidente y quería disculparse."},{"a":"malady","t":"Hola. Lo siento mucho. No era mi intención..."},{"a":"argon","t":"¡Bueno, no pasa nada! ¡Me siento genial!... Aunque un poquito rígido."},{"a":"argon","t":"¿Eres Malady? Yo soy Argon, ¡encantado de conocerte!"},{"a":"argon","t":"Oh, se te ha caído el pañuelo. ¡Espera, que te lo coloco!"},{"a":"lilu","t":"¡Argon! ¡No!"},{"a":"argon_stone","t":"..."},{"a":"lilu","t":"Argon... Voy a tener que darle una charla sobre Medusas..."},{"a":"malady","t":"¡Oh, no! ¡Lo siento!"},{"a":"lilu","t":"No lo sientas. Esta vez ha sido culpa suya."},{"a":"malady","t":"Estoy lista para otra extracción de sangre..."},{"a":"lilu","t":"No conozco mucho la fisiología de las Medusas, pero deberías esperar algunos días entre una extracción y otra."},{"a":"lilu","t":"Mientras tanto, quédate aquí. No es seguro que andes por ahí estando debilitada."},{"a":"lilu","t":"Aunque, teniendo en cuenta tus... poderes, tal vez sea mejor preguntarle primero al Anciano Owen."},{"a":"malady","t":"Sí..."}]},{"id":"malady_05","i":5,"title":"Bienvenida a casa","req":"malady:5","reward":{"k":"gems","id":"gems","q":10,"n":"Joyas"},"side":false,"lines":[{"a":"lilu","t":"¡Anciano Owen, hemos vuelto!"},{"a":"elderowen","t":"¿Argon está curado? ¡Qué buena noticia!"},{"a":"lilu","t":"No... todavía. Pero..."},{"a":"malady","t":"..."},{"a":"elderowen","t":"¡Por la Diosa! ¿¡Una Medusa, aquí!?"},{"a":"lilu","t":"Es Malady. ¡Me ha ayudado a curar a Argon!"},{"a":"lilu","t":"Tendrá que quedarse unos días para poder curarlo... otra vez."},{"a":"elderowen","t":"Entiendo. No transmites ninguna maldad. Disculpa mi reacción, Malady."},{"a":"malady","t":"Por culpa de mi maldición, todos me odian, incluso otros monstruos. Estoy acostumbrada."},{"a":"elderowen","t":"Las puertas de la ciudad siempre están abiertas para quienes desean trabajar por el bien común."},{"a":"malady","t":"¿De verdad?"},{"a":"elderowen","t":"Mientras tengas los ojos tapados, no hay ningún inconveniente."},{"a":"elderowen","t":"Malady, espero que tengas más suerte aquí que entre tus congéneres."},{"a":"malady","t":"Gracias. Nunca me habían acogido en ningún lugar..."},{"a":"elderowen","t":"Deberías ir a ver al comerciante pronto. Siempre tiene trabajo para gente joven como tú."},{"a":"lilu","t":"¡Bien! Podrías venir a hacer misiones con nosotros."},{"a":"malady","t":"Lo haré. Muchas gracias, Lilu y Owen."}]}]},{"id":"argon","name":"Argon","chapters":[{"id":"argon_01","i":1,"title":"La sombra del rey","req":"argon:1","reward":{"k":"gems","id":"gems","q":10,"n":"Joyas"},"side":false,"lines":[{"a":"argon","t":"... y entonces acuchillé al trasco con mi espada. ¡Pum!"},{"a":"elderowen","t":"¡Jo, no! ¡Menuda historia, Argon!"},{"a":"elderowen","t":"Ay, el fuego de la juventud..."},{"a":"elderowen","t":"Debo decir que es todo un detalle que acompañes a este anciano en su paseo matutino."},{"a":"argon","t":"¡No es nada! Si pretendo convertirme en caballero, debo ayudar a los necesitados."},{"a":"elderowen","t":"Igual que tu padre, ¿eh? Seguro que serás un buen caballero, muchacho."},{"a":"elderowen","t":"¡A lo mejor hasta puedes trabajar en la guardia real!"},{"a":"elderowen","t":"Precisamente el rey está ahí, en el mercado. ¿Por qué no le preguntas?"},{"a":"argon","t":"¡Majestad! Vengo a ofreceros mis servicios como caballero."},{"a":"king","t":"¡¿Pero qué significa esto?! ¡Sia, ocúpate de este plebeyo!"},{"a":"sia","t":"Por supuesto, mi rey."},{"a":"sia","t":"A ver, jovencito, ¿qué quieres?"},{"a":"argon","t":"¡Uy! Pues, eh..."},{"a":"argon","t":"¡Soy caballero! ¡Y quiero convertirme en Argon!"},{"a":"argon","t":"No, así no era..."},{"a":"sia","t":"¡Desde luego tienes coraje!"},{"a":"sia","t":"Si tan decidido estás, ven a verme la semana que viene al patio del castillo."},{"a":"sia","t":"¡Entrena duro hasta entonces! No admito holgazanes entre los caballeros del rey..."}]},{"id":"argon_02","i":2,"title":"Montaje de entrenamiento","req":"argon:2","reward":{"k":"gems","id":"gems","q":10,"n":"Joyas"},"side":false,"lines":[{"a":"lilu","t":"Argon, ¿qué estás haciendo aquí?"},{"a":"argon","t":"¡Entrenar duro! Por fin llegó mi oportunidad de convertirme en caballero del rey."},{"a":"lilu","t":"¿Del rey? ¿O de su misteriosa asesora Sia...?"},{"a":"argon","t":"¿Así se llama? ¡Qué nombre más bonito!"},{"a":"lilu","t":"..."},{"a":"argon","t":"Eh... ¡No! ¡El único que importa es el rey!"},{"a":"argon","t":"¡Debo convertirme en caballero! Es lo único que importa."},{"a":"lilu","t":"Ya... A ver, que te cure las heridas."},{"a":"argon","t":"Gracias... ¡Ay! ¡Cómo escuece ese conjuro!"}]},{"id":"argon_03","i":3,"title":"Las dos caras de la moneda","req":"argon:3","reward":{"k":"gems","id":"gems","q":10,"n":"Joyas"},"side":false,"lines":[{"a":"argon","t":"¡Muy bien! Sia aparecerá de un momento a otro."},{"a":"argon","t":"Mi entrenamiento ha dado sus frutos, ¡estoy listo!"},{"a":"argon","t":"... Aunque sigo demasiado nervioso..."},{"a":"argon","t":"¡Oh! ¡Hola! ¡Tú, el de los arbustos!"},{"a":"yami","t":"¡...!"},{"a":"argon","t":"¿También vienes para convertirte en caballero?"},{"a":"argon","t":"Sia vendrá en breve. No hay por qué esconderse, ¡es muy agradable!"},{"a":"yami","t":"¡Sia...!"},{"a":"yami","t":"Tengo que irme. Adiós."},{"a":"argon","t":"¡U-un momento!"},{"a":"argon","t":"¡Hala! ¡¿Una bomba de humo?!"},{"a":"argon","t":"Qué chica tan rara..."},{"a":"sia","t":"Joven, ¿con quién hablas?"},{"a":"argon","t":"¡Ah, Sia! No era más que un tímido transeúnte, no tiene importancia."},{"a":"sia","t":"Ya veo. Entonces parece que mantienes tu determinación."},{"a":"sia","t":"¿Estás dispuesto a arriesgar tu vida como caballero del Rey?"},{"a":"argon","t":"¡Toma, pues claro! Quiero decir... ¡por supuesto! Haré que mi padre se sienta orgulloso."},{"a":"sia","t":"Bien. Tengo un evento importante entre manos para tu primera misión..."}]},{"id":"argon_04","i":4,"title":"Con las manos vacías","req":"yami:4","reward":{"k":"gems","id":"gems","q":10,"n":"Joyas"},"side":false,"lines":[{"a":"argon","t":"..."},{"a":"sia","t":"¡Tienes que estar de broma!"},{"a":"sia","t":"Has arrinconado a la asesina... y no has conseguido detenerla."},{"a":"sia","t":"Por si fuera poco, ¿dices que la has dejado marchar porque te ha parecido una buena persona?"},{"a":"argon","t":"..."},{"a":"sia","t":"¿Qué es este disparate?"},{"a":"sia","t":"Te das cuenta de que esta asesina intentó matar a nuestro Rey, el mismo hombre al que juraste proteger, ¿verdad?"},{"a":"sia","t":"Un incidente así pone en peligro mucho más de lo que puedas imaginar con esa cabeza de alcornoque."},{"a":"sia","t":"Uf... Imagino que el Rey es el que tiene la última palabra antes de cesar a uno de sus caballeros..."},{"a":"sia","t":"... pero no esperes que hable bien de ti. Puedes retirarte."},{"a":"argon","t":"..."},{"a":"argon","t":"Vaya tela..."},{"a":"argon","t":"Lo siento, papá."}]},{"id":"argon_a","i":4,"title":"La torre de los titanes","req":"argon:4","reward":{"k":"tokens","id":"tokens","q":3,"n":"Fichas de la fortuna"},"side":true,"lines":[{"a":"elderowen","t":"La torre de los titanes, ¿eh?"},{"a":"lilu","t":"¡Cuéntanoslo todo!"},{"a":"argon","t":"He oído algunos rumores, pero nadie la ha visto..."},{"a":"elderowen","t":"En efecto, la torre de los titanes es un lugar mítico. Nadie sabe si existe de verdad."},{"a":"elderowen","t":"Cuentan las historias que aparece de la nada y desafía a los héroes más valientes a recorrer sus plantas..."},{"a":"elderowen","t":"... Antes de desaparecer súbitamente y borrar los recuerdos de quienes la hayan visto."},{"a":"argon","t":"¡¿Eh?! ¿Borra los recuerdos?"},{"a":"lilu","t":"Qué raro... Entonces, ¿cuál es el origen de esta leyenda?"},{"a":"argon","t":"¡Claro, alguien tendrá que acordarse!"},{"a":"elderowen","t":"Dicen que la torre considera dignos a quienes superan el desafío del titán."},{"a":"elderowen","t":"Estos héroes vuelven afectados por la experiencia, pero no pierden sus recuerdos."},{"a":"elderowen","t":"Para ser precisos, una parte de ellos se queda en la torre, y una parte de la torre se va con ellos."},{"a":"elderowen","t":"Bueno, ya está bien de historias por hoy. Gracias por escuchar los cuentos de este anciano."},{"a":"lilu","t":"Qué fuerte... Me pregunto si existirá de verdad esa torre."},{"a":"argon","t":"¡Ya ves! ¡Me encantaría explorar una mazmorra así!"},{"a":"lilu","t":"Pero algo que no me encaja... ¿Por qué conoce esta historia Owen?"},{"a":"argon","t":"¡...!"}]},{"id":"argon_05","i":5,"title":"Caballero andante","req":"argon:5","reward":{"k":"gems","id":"gems","q":10,"n":"Joyas"},"side":false,"lines":[{"a":"argon","t":"Ay..."},{"a":"steel","t":"¡Pero si es Argon! ¿Qué tal va todo?"},{"a":"argon","t":"Oh. Hola, Brohm... ¿Hay algún trabajo para mí?"},{"a":"steel","t":"Hoy no hay nada, caballero. ¿Qué te pasa que andas tan cabizbajo?"},{"a":"argon","t":"Ahora solo soy Argon. He perdido mi título..."},{"a":"steel","t":"Vaya, eso duele..."},{"a":"steel","t":"«¡Pase lo que pase, hay que ser positivo! ¡Saldrás adelante!»."},{"a":"steel","t":"¡Seguro que pronto cambiará tu suerte!"},{"a":"argon","t":"Sí... Gracias, Brohm."},{"a":"argon","t":"Me quedaré... en la plaza, mientras tanto."},{"a":"argon","t":"Ay..."}]},{"id":"argon_b","i":5,"title":"¿Nosotros somos los titanes?","req":"argon:5","reward":{"k":"tokens","id":"tokens","q":3,"n":"Fichas de la fortuna"},"side":true,"lines":[{"a":"lilu","t":"Buenos días, Argon..."},{"a":"argon","t":"Uuuff... Buenos días."},{"a":"lilu","t":"Tú también lo notas, ¿eh?"},{"a":"argon","t":"¡Estoy reventado! ¡Es como si me hubiera pasado toda la noche con una misión!"},{"a":"lilu","t":"Mira, si tienes el escudo destrozado."},{"a":"argon","t":"¡Es verdad! Juraría que ayer mismo estaba reluciente..."},{"a":"lilu","t":"Argon... ¿Crees que...?"},{"a":"polonia","t":"¡Arrr! ¿A algún marinerito de agua dulce del mercado le interesan unas <c1>grebas de coloso</c1>?"},{"a":"lilu","t":"No, ¡y menos 20! ¿Dónde has conseguido tantas?"},{"a":"polonia","t":"Si te digo la verdad, no tengo ni idea."},{"a":"polonia","t":"Creo que me dedico a saquear cuando estoy sopa. Será mi esencia de pirata."},{"a":"lilu","t":"A esa pirata también le está pasando..."},{"a":"lilu","t":"¿Será que hemos retado a la torre y nos han borrado los recuerdos?"},{"a":"argon","t":"O sea, que no superamos el desafío..."},{"a":"argon","t":"¡Pues pienso entrenar superduro la próxima vez! ¡Ya lo veréis!"}]},{"id":"argon_06","i":6,"title":"Bajo otra luz","req":"argon:6","reward":{"k":"gems","id":"gems","q":10,"n":"Joyas"},"side":false,"lines":[{"a":"sia","t":"Así que ese «caballero» tuvo a tu asesina a su merced."},{"a":"sia","t":"Y aun así la dejó marchar, porque le pareció que era buena persona."},{"a":"king","t":"¡Fascinante! Ese nuevo caballero promete."},{"a":"sia","t":"Con todo el respeto, mi rey..."},{"a":"sia","t":"Este hombre no detuvo a la asesina porque se dejó llevar por una simple intuición."},{"a":"king","t":"Un rasgo distintivo de un <c1>paladín</c1>, ¿no crees?"},{"a":"sia","t":"¿Qué?"},{"a":"king","t":"Tener a tu archienemigo a tu merced y, aun así, ser capaz de ver más allá del conflicto..."},{"a":"king","t":"Y dejarle ir con la certeza de su redención, aun a riesgo de perder su título."},{"a":"king","t":"¡Todo un acto de valentía y bondad!"},{"a":"sia","t":"Debo admitir que no se me había ocurrido verlo de ese modo, mi rey."},{"a":"sia","t":"Pero hace varias décadas que no hay un aspirante a paladín en el reino..."},{"a":"sia","t":"¿Debería convocar al consejo de caballeros para discutir el asunto?"},{"a":"king","t":"¡Tonterías! Yo mismo me encargaré de ello."},{"a":"sia","t":"Como desees, mi rey. Prepararé su escolta inmediatamente."},{"a":"king","t":"No hace falta, seré tan discreto como un ratoncillo."}]},{"id":"argon_07","i":7,"title":"El rey discreto","req":"argon:7","reward":{"k":"gems","id":"gems","q":10,"n":"Joyas"},"side":false,"lines":[{"a":"king","t":"¡Haceos a un lado, plebeyos! Un trabajador del montón camina ente vosotros."},{"a":"tavern","t":"¡Rey Reinhold, cuánto tiempo! La ocasión se merece brindar con ambrosía, ¿no?"},{"a":"king","t":"¡Chis! Estoy de incógnito, ignórame."},{"a":"tavern","t":"Claro, qué torpeza la mía."},{"a":"king","t":"¡Oye, tú! El que se esconde tras el mostrador."},{"a":"argon","t":"Oh, eh... Lo siento, Su Majestad, me quitaré de en medio."},{"a":"king","t":"¡Pamplinas! Un futuro paladín es digno de sentarse junto a mi deslumbrante persona."},{"a":"argon","t":"Sentarse junto a... ¿¡un paladín!?"},{"a":"king","t":"¡Exacto! Mi infinita sabiduría me ha permitido detectar tu potencial."},{"a":"king","t":"A pesar de tus métodos... inusuales, tu corazón es sincero y tu sentido de la justicia, admirable."},{"a":"king","t":"Por lo tanto, el reino te considera apto para que te sometas a las pruebas de paladín."},{"a":"argon","t":"¡Las pruebas de paladín! ¡Qué pasada!"},{"a":"argon","t":"Lo sé todo sobre ellas. Cada una es única y el propio paladín las selecciona..."},{"a":"argon","t":"Ha de ser una tarea arriesgada, como matar a un dragón o destruir algún tipo de artefacto peligroso..."},{"a":"king","t":"¡Por supuesto! Cualquier hazaña valiente y altruista hecha en nombre del reino valdrá."},{"a":"argon","t":"Ya veo. Gracias, Su Majestad. ¡No te arrepentirás!"},{"a":"king","t":"Claro que no, yo nunca me equivoco."},{"a":"king","t":"Bueno, pues ya que estoy de incógnito..."},{"a":"king","t":"¡Oye, tú, el viejo! Enséñame a jugar a las cartas."},{"a":"master","t":"¿A las cartas? El viejo Theodore solo juega con una buena apuesta..."}]},{"id":"argon_08","i":8,"title":"Reavivado","req":"argon:8","reward":{"k":"gems","id":"gems","q":10,"n":"Joyas"},"side":false,"lines":[{"a":"lilu","t":"¿A qué viene tanta prisa, Argon?"},{"a":"argon","t":"Lilu, ¡voy a ser paladín!"},{"a":"lilu","t":"¿Un paladín? Eso es fantástico. ¿Pero cómo...?"},{"a":"argon","t":"El rey me ha dicho que debo superar una prueba. Es la única forma de ser merecedor del título de paladín."},{"a":"lilu","t":"¿Eh? ¿Qué clase de prueba?"},{"a":"argon","t":"..."},{"a":"argon","t":"Ay, madre... ¡No tengo ni idea!"},{"a":"argon","t":"Seguramente sea algo épico y glorioso..."},{"a":"lilu","t":"Argon, tú ya eres glorioso. ¡Has derrotado a miles y miles de monstruos!"},{"a":"argon","t":"Sí, pero tiene que haber algo más..."},{"a":"argon","t":"Por lo visto, hay demonios con plumas en el Chapitel Lóbrego. A lo mejor con eso serviría..."},{"a":"lilu","t":"Bueno, sea lo que sea, seguro que lo lograrás."},{"a":"argon","t":"Gracias, Lilu... Aunque ya no soy caballero, sigues creyendo en mí..."},{"a":"lilu","t":"Ay, pero eso no es nada."},{"a":"lilu","t":"¡Ejem! Vas a necesitar ayuda en tu misión, así que te prepararé unos pergaminos curativos."},{"a":"argon","t":"¡Fantástico! ¡Manos a la obra!"}]},{"id":"argon_09","i":9,"title":"Enfrentamiento en Chapitel Lóbrego (Argon)","req":"argon:9","reward":{"k":"gems","id":"gems","q":10,"n":"Joyas"},"side":false,"lines":[{"a":"argon","t":"¡Odio este lugar!"},{"a":"argon","t":"Llevo un montón de rato escalando, y no he visto ninguna arpía... Para colmo, ¡los asesinos me han tendido una emboscada!"},{"a":"argon","t":"Se parecían un poco a esa ninja, ¿no?"},{"a":"argon","t":"Menos mal que Lilu me dio estos pergaminos curativos."},{"a":"argon","t":"Voy a descansar aquí."},{"a":"argon","t":"¿Eh?"},{"a":"yami","t":"Otra vez tú."},{"a":"argon","t":"¡Ah! ¡La asesina del rey!"},{"a":"argon","t":"Esto debe ser cosa del destino. ¡Mucho mejor que una arpía!"},{"a":"yami","t":"Adelante. Acabaré contigo aquí y ahora."}]},{"id":"argon_10a","i":10,"title":"Regreso triunfal","req":"yami:9","reward":{"k":"gems","id":"gems","q":10,"n":"Joyas"},"side":false,"lines":[{"a":"argon","t":"Rey Reinhold, ¡misión cumplida!"},{"a":"king","t":"¡Fantástico! ¿A qué espantosa bestia has dado muerte?"},{"a":"argon","t":"Bueno, esto..."},{"a":"yami","t":"Hola."},{"a":"king","t":"¡¿Pero qué significa esto?!"},{"a":"sia","t":"¡Guardias, arrestadlos!"},{"a":"argon","t":"¡Esperad, esperad! ¡Ya no es la de antes, ha cambiado!"},{"a":"king","t":"¿En serio?"},{"a":"yami","t":"Vengo a... disculparme..."},{"a":"sia","t":"Majestad, no os creeréis que..."},{"a":"argon","t":"Yo respondo por ella. ¡Palabra de caballero!"},{"a":"king","t":"Muy bien. Habla, te escucho."},{"a":"sia","t":"Buf... Me temía que fuera a pasar esto."},{"a":"sia","t":"Guardias, traed refuerzos y no la perdáis de vista ni un segundo."},{"a":"sia","t":"Argon, espera fuera mientras hablamos con la intrusa."},{"a":"argon","t":"¡Ya!"},{"a":"argon","t":"(¿Habré metido la gamba?)."}]},{"id":"argon_10b","i":11,"title":"Redentor","req":"yami:10","reward":{"k":"gems","id":"gems","q":10,"n":"Joyas"},"side":false,"lines":[{"a":"sia","t":"Agh... Hoy no necesitaba este dolor de cabeza."},{"a":"argon","t":"¿Cómo ha ido, señorita Sia?"},{"a":"sia","t":"Contra todo pronóstico, el rey Reinhold está dispuesto a perdonar a quien intentó matarlo."},{"a":"sia","t":"Aunque no termino de confiar en ella, admito que ha compartido información muy valiosa sobre la orden azumana."},{"a":"argon","t":"¿Significa eso que...?"},{"a":"sia","t":"Sí, aceptaremos su rendición y disculpa."},{"a":"sia","t":"Nuestros médicos la están tratando por la desnutrición que sufre, pero se recuperará."},{"a":"sia","t":"En cuanto a ti, paladín Argon..."},{"a":"argon","t":"¡¿Paladín?!"},{"a":"sia","t":"Sí. Ya es meritorio acabar con una amenaza, pero hacer que una acérrima enemiga del reino se ponga de nuestro lado es toda una hazaña."},{"a":"sia","t":"Parece ser que el rey Reinhold no se equivocaba contigo."},{"a":"sia","t":"Ahora, ve a celebrarlo, paladín. Pronto estarás muy atareado."},{"a":"argon","t":"¡Eso haré, muchas gracias!"},{"a":"argon","t":"Papá..., espero que estés orgulloso."}]},{"id":"argon_epilogue","i":12,"title":"Epílogo","req":"argon:10","reward":{"k":"gems","id":"gems","q":10,"n":"Joyas"},"side":false,"lines":[{"a":"lilu","t":"¡¿Paladín!? ¡Lo has logrado, Argon!"},{"a":"argon","t":"Pensaba que iba a fastidiarlo todo..."},{"a":"argon","t":"Pero papá tenía razón; solo tenía que seguir a mi corazón."},{"a":"lilu","t":"Un momento... Entonces, ¿te marcharás a luchar en campañas en lugares lejanos?"},{"a":"argon","t":"Todavía no. Sia quiere que enseñe a otros héroes a convertirse en paladines."},{"a":"lilu","t":"Qué alivio... Aunque no te imagino haciendo de profesor."},{"a":"lilu","t":"¿No estarás ocupado con misiones de paladín superimportantes?"},{"a":"argon","t":"¡Haré todo lo que esté en mi mano! ¡El reino cuenta conmigo!"},{"a":"tavern","t":"Saludos, noble paladín."},{"a":"tavern","t":"Brohm me ha dicho que estaba buscando más guantes de fundición."},{"a":"argon","t":"¡Sí, ahora mismo!"},{"a":"lilu","t":"Hay cosas que nunca cambian, ¿verdad?"},{"a":"tavern","t":"Nuestro Argon no, eso desde luego."}]},{"id":"argon_c","i":13,"title":"Escrito en piedra","req":"malady:3","reward":{"k":"tokens","id":"tokens","q":3,"n":"Fichas de la fortuna"},"side":true,"lines":[{"a":"argon_stone","t":"..."},{"a":"lilu","t":"La poción no ha funcionado, ¿verdad?"},{"a":"lilu","t":"Ais... Mira que nos habíamos esforzado..."},{"a":"lilu","t":"Lo siento, Argon. No he sido suficientemente buena para ti... Espero que no estés muy incómodo ahí."},{"a":"elderowen","t":"Mmm... Son malas noticias."},{"a":"lilu","t":"Aún no hemos agotado todas nuestras opciones, pero..."},{"a":"lilu","t":"Es difícil no tenerlo con nosotros."},{"a":"elderowen","t":"La ciudad está vacía sin él, ¿verdad?"},{"a":"lilu","t":"Como una fiesta de cumpleaños sin amigos."},{"a":"lilu","t":"Deprimirnos no ayudará a traerlo de vuelta antes. Seguiré trabajando."},{"a":"lilu","t":"Quizá podamos pedirle ayuda a Donovan."},{"a":"lilu","t":"¡Nos costará, pero podemos juntar nuestro dinero!"},{"a":"lilu","t":"Sé que no irás a ninguna parte, ¡pero tienes que aguantar! ¡Te salvaremos!"},{"a":"argon_stone","t":"..."}]}]},{"id":"ashley","name":"Ashley","chapters":[{"id":"ashley_01","i":1,"title":"Samurái peculiar","req":"ashley:1","reward":{"k":"gems","id":"gems","q":10,"n":"Joyas"},"side":false,"lines":[{"a":"argon","t":"Una samurái de verdad, ¡qué guay!"},{"a":"argon","t":"Señora samurái, me llamo Argon y soy un caballero en..."},{"a":"ashley","t":"Eh. Soy Ashley. ¿Qué tal?"},{"a":"argon","t":"¿Solo me dices «Eh»?"},{"a":"tavern","t":"¡Quita los pies de la mesa!"},{"a":"ashley","t":"Pff... Vale."},{"a":"ashley","t":"¿Y bien? ¿Qué quieres?"},{"a":"argon","t":"¿No se supone que los samuráis son más... honorables y eso?"},{"a":"ashley","t":"¿Eh? Ah, sí, en mi país se ponían bastante pesaditos con ese tema."},{"a":"ashley","t":"Menos mal que me he librado y ahora solo soy una rōnin. Una samurái sin señor."},{"a":"argon","t":"Entiendo... ¡Ah, por cierto!"},{"a":"argon","t":"Tenía una misión para ir con Lilu al castillo encantado, pero..."},{"a":"argon","t":"Ha habido un problemilla en la sala de entrenamiento. ¿Podrías ir en mi lugar?"},{"a":"ashley","t":"Claro, pero me debes una, caballerete."}]},{"id":"ashley_02","i":2,"title":"Armada y preparada","req":"ashley:2","reward":{"k":"gems","id":"gems","q":10,"n":"Joyas"},"side":false,"lines":[{"a":"ashley","t":"Eres Lilu, ¿no?"},{"a":"lilu","t":"Sí, ¡encantada de conocerte!"},{"a":"ashley","t":"Muy bien, pues... en marcha."},{"a":"lilu","t":"¡E-espera un momento!"},{"a":"lilu","t":"Aún no hemos preparado el viaje. Hacen falta pociones, raciones y..."},{"a":"ashley","t":"Anda ya, eso no es necesario."},{"a":"ashley","t":"Sobrevivimos a la misión o morimos. No hay punto medio."},{"a":"lilu","t":"¡¿Qué dices?! ¡Eso es muy arriesgado!"},{"a":"ashley","t":"Bueno, yo voy para allá. Es por aquí, ¿no?"},{"a":"lilu","t":"¡No, no! Por ahí se va al Bosque de los Aullidos."},{"a":"argon","t":"Esto... ¿Buena suerte?"}]},{"id":"ashley_03","i":3,"title":"Viviendo al límite","req":"ashley:3","reward":{"k":"gems","id":"gems","q":10,"n":"Joyas"},"side":false,"lines":[{"a":"ashley","t":"¿Eso es lo único que saben hacer los monstruos de este lugar? ¡Echadle más ganas!"},{"a":"lilu","t":"Ashley, más despacio. ¡No me da tiempo a curarnos!"},{"a":"ashley","t":"¡Venga ya! ¡Esto no es nada!"},{"a":"ashley","t":"Uf... Ha estado bien, ¿eh?"},{"a":"lilu","t":"¿Estás de broma? ¡Casi te matan!"},{"a":"lilu","t":"Si te comportas así normalmente, no me extraña que hayas perdido un brazo."},{"a":"ashley","t":"Eh, esto fue por otra cosa."},{"a":"ashley","t":"Jamás volveré a cometer un error así."},{"a":"lilu","t":"¡No pienso usar ninguna anestesia para curarte!"},{"a":"lilu","t":"Tú te lo has buscado, así que arréglatelas sola."},{"a":"ashley","t":"¡Ja, ja! Pues... claro que puedo soportar el dolor..."},{"a":"ashley","t":"¡Ay! ¡Joe, cómo duele!"}]},{"id":"ashley_a","i":4,"title":"Un sentimiento familiar","req":"ashley:3","reward":{"k":"tokens","id":"tokens","q":3,"n":"Fichas de la fortuna"},"side":true,"lines":[{"a":"ashley","t":"Eh, ¿por qué hay tantos monstruos chiquitajos por aquí?"},{"a":"elven","t":"Bienvenida. Te presento a mis adorados familiares."},{"a":"elven","t":"Solo los campeones dignos de ellos pueden adoptarlos y quedárselos como mascotas."},{"a":"ashley","t":"Ah, una mascota... Ya entiendo."},{"a":"ashley","t":"Ajá. Tú, el bicho verde. Te voy a llamar «<c1>Pillín</c1>». Venga, vámonos."},{"a":"ashley","t":"Qué monada es <c1>Bola de nieve</c1>. Me quedo con este."},{"a":"elven","t":"Ah, me temo que..."},{"a":"ashley","t":"¡Ostras, qué pajarraco más feo!"},{"a":"ashley","t":"Te voy a llamar «<c1>Gorriona</c1>». Tú también te puedes venir."},{"a":"elven","t":"Bueno, pues... pasadlo bien todos."}]},{"id":"ashley_04","i":5,"title":"Misión Fallida Exitosamente","req":"ashley:4","reward":{"k":"gems","id":"gems","q":10,"n":"Joyas"},"side":false,"lines":[{"a":"argon","t":"¿Qué tal te fue en la misión de ayer? Lilu parecía bastante disgustada..."},{"a":"ashley","t":"Volví de una pieza. Por desgracia."},{"a":"argon","t":"¿¡Eh!? ¿Pero no es eso bueno?"},{"a":"king","t":"¡Saludos, plebeyos! ¡No dudéis en contemplar mi esplendor!"},{"a":"ashley","t":"¡Ah, Su Majestad, señor! Ashley se presenta al servicio."},{"a":"king","t":"Esta sí que es una soldado como es debido. ¡Sigue así!"},{"a":"ashley","t":"¡Sí, señor! ¡Gracias, señor!"},{"a":"tavern","t":"Lo siento, Reinhold, tu cosecha todavía no ha llegado."},{"a":"king","t":"Muy bien. ¡Con tu permiso, regresaré mañana!"},{"a":"argon","t":"¿Y esa forma de hablar?"},{"a":"ashley","t":"Oh, eh. Antes servía a un señor. Es la costumbre."},{"a":"argon","t":"¡Cómo mola! Cuéntame."},{"a":"ashley","t":"No."}]},{"id":"ashley_05","i":6,"title":"Giro del Cuento","req":"ashley:5","reward":{"k":"gems","id":"gems","q":10,"n":"Joyas"},"side":false,"lines":[{"a":"ashley","t":"... Y entonces, le dije al tipo..."},{"a":"ashley","t":"\"¿Armada y lista? ¡Bueno, podrías decir que estoy lista!\"."},{"a":"argon","t":"¡Ja, ja, ja!"},{"a":"argon","t":"... Pero Ashley, sobre ese señor del que hablabas antes..."},{"a":"ashley","t":"Aaaaah... tú no sueltas presa, ¿eh? Está bien."},{"a":"ashley","t":"Los samuráis tienen un señor, un daimyō. Lo servimos y protegemos con nuestras vidas."},{"a":"argon","t":"¡Muy honorable!"},{"a":"ashley","t":"Un día cualquiera, estaba almorzando como de costumbre..."},{"a":"ashley","t":"Y de repente, ¡bum! Ninjas. Por toda la habitación. Todos... todos a por la cabeza de mi señor."},{"a":"ashley","t":"Luchamos duro. No era la primera vez. Pero..."},{"a":"ashley","t":"Recibí un ataque fuerte. Perdí el brazo."},{"a":"ashley","t":"Y luego... salí corriendo. Lo dejé ahí, a que muriera."},{"a":"argon","t":"Ashley..."},{"a":"ashley","t":"¡¡¡RAAAAAAAH!!! ¡Debería haber muerto yo también!"},{"a":"ashley","t":"Naya, sírveme otra."},{"a":"tavern","t":"Ya has bebido más que suficiente por hoy, Ashley."},{"a":"ashley","t":"Vale. No pasa nada. Ya he tenido lo mío."},{"a":"ashley","t":"Muy bien. Argon, ve a decirle a Lilu que Ashley está a punto de irse de misión, una muy peligrosa."},{"a":"argon","t":"¿Eh? ¿¡Ahora mismo!?"},{"a":"ashley","t":"Por supuesto. Me dirijo a... las Cuevas de la Aurora, por ejemplo. ¡Y date prisa!"}]},{"id":"ashley_06","i":7,"title":"Un ojo por un yo","req":"ashley:6","reward":{"k":"gems","id":"gems","q":10,"n":"Joyas"},"side":false,"lines":[{"a":"ashley","t":"Chica ninja. ¿Estabas escuchando a escondidas?"},{"a":"yami","t":"Un poco. ¿Lo resolvemos fuera?"},{"a":"ashley","t":"¡Bah! No estoy de humor para peleas."},{"a":"yami","t":"Mi clan fue el que le hizo eso al Señor Kusunoki. Soy una paria, pero quizá mis disculpas..."},{"a":"ashley","t":"Gracias, pero no hace falta. No te odio a ti. Me odio a mí."},{"a":"yami","t":"Lo entiendo... Quizá más de lo que te imaginas."},{"a":"yami","t":"Pero incluso con tu honor por los suelos, aún tienes mucho por lo que vivir."},{"a":"yami","t":"Aquí tienes amigos. Una ciudad como una familia. Mascotas a las que aprecias."},{"a":"yami","t":"Pero, si eso no basta, puedo proponerte un duelo honorable a muerte."},{"a":"ashley","t":"¿Un asesinato gratis cortesía de una ninja? Eres demasiado amable."},{"a":"ashley","t":"Gracias, pero paso. Aunque lo tendré en cuenta."},{"a":"yami","t":"Como quieras."}]},{"id":"ashley_07","i":8,"title":"Una Última Lucha","req":"ashley:7","reward":{"k":"gems","id":"gems","q":10,"n":"Joyas"},"side":false,"lines":[{"a":"lilu","t":"Uff... Uff... Ashley no está aquí..."},{"a":"lilu","t":"¿Se habrá perdido otra vez...?"},{"a":"lilu","t":"No... espera. ¿Me han engañado?"},{"a":"ashley","t":"Creía que iba hacia el Volcán Lago de Ceniza..."},{"a":"ashley","t":"Qué más da, me vale."},{"a":"ashley","t":"¡Vaaaaaaale! ¡Despertad, cretinos! ¡Ashley ha llegado!"},{"a":"monster_Grotto_Mob","t":"La humana está... ¿borracha?"},{"a":"ashley","t":"Hoy no hay ningún médico metomentodo, ¡solo yo y mis ganas de morir! ¡No pararé hasta que esté muerta!"},{"a":"ashley","t":"¡Pase lo que pase, gano yo! Conque, ¿quién va primero?"},{"a":"monster_Ruins_Mob","t":"¡Grah! ¡Adelante!"},{"a":"ashley","t":"¡Así me gusta!"}]},{"id":"ashley_08","i":9,"title":"Deus Ex Asthea","req":"ashley:8","reward":{"k":"gems","id":"gems","q":10,"n":"Joyas"},"side":false,"lines":[{"a":"priest","t":"Oh, Diosa... ¿es este el lugar?"},{"a":"priest","t":"Madre mía, menuda carnicería."},{"a":"monster_Grotto_Mob","t":"Ji, ji, ji."},{"a":"priest","t":"Con permiso, monstruos. Por favor, dejad que recoja a mi compañera."},{"a":"monster_Grotto_Mob","t":"¡Ni hablar! ¡Ni hablar! Nos ha dado una paliza. ¡Esa samurái está más muerta que una piedra!"},{"a":"priest","t":"Todavía respira. Nuestra Ashley es mucho más dura que todo esto."},{"a":"monster_Ruins_Mob","t":"¿Eh? ¡Pues espera, que termino el trabajo!"},{"a":"priest","t":"Ya puedes ir olvidándote."},{"a":"monster_Grotto_Mob","t":"¡Ji, ji, ja! ¿Y qué vas a HACER? ¿Curarnos?"},{"a":"priest","t":"No me dejáis otra opción. Que la Diosa Asthea os perdone..."},{"a":"priest","t":"Porque yo no lo haré."}]},{"id":"ashley_09","i":10,"title":"Reposo Forzoso","req":"ashley:9","reward":{"k":"gems","id":"gems","q":10,"n":"Joyas"},"side":false,"lines":[{"a":"ashley","t":"Ah..."},{"a":"priest","t":"Por fin has vuelto en ti."},{"a":"ashley","t":"¿Eh? Mierda... Tú también no. ¿Cómo... me has encontrado?"},{"a":"priest","t":"Parece ser que la Diosa se preocupa por ti. Me envió en su lugar."},{"a":"ashley","t":"Rayos... Vamos, doc, déjame morir."},{"a":"priest","t":"Si de verdad lo deseas..."},{"a":"ashley","t":"Vaya... por fin..."},{"a":"ashley","t":"..."},{"a":"ashley","t":"¿Pero por qué sigues CURÁNDOME?"},{"a":"priest","t":"A pesar de tus palabras, parece que todavía deseas vivir."},{"a":"priest","t":"Lo único que hace la magia curativa es acelerar tu fuerza vital. Si de verdad quisieras morir, no podría hacer nada por salvarte."},{"a":"ashley","t":"¿En serio...?"},{"a":"priest","t":"Descansa por ahora. Tienes mucho en lo que pensar."}]},{"id":"ashley_10","i":11,"title":"Un tiempo para pensar","req":"ashley:10","reward":{"k":"gems","id":"gems","q":10,"n":"Joyas"},"side":false,"lines":[{"a":"argon","t":"¡Has vuelto! ¡Lilu te ha estado buscando por todas partes!"},{"a":"argon","t":"...Tú también te ves un poco hecho un desastre."},{"a":"ashley","t":"No te preocupes, me curaron. También me echaron una buena bronca."},{"a":"argon","t":"¿De Freyja? Eso es difícil de imaginar."},{"a":"ashley","t":"Sí. Me dijo que empezara a pensar. Así que estoy pensando."},{"a":"tavern","t":"¿Pensando? ¡Eso es nuevo!"},{"a":"ashley","t":"Basta ya."},{"a":"ashley","t":"...es lo que me gustaría decir, pero tienes razón."},{"a":"ashley","t":"He estado anclado en el pasado tanto tiempo, que olvidé por completo pensar."},{"a":"argon","t":"¿Pensar en qué?"},{"a":"ashley","t":"Mmm. Muchas cosas."},{"a":"ashley","t":"Sin darme cuenta, parece que he acumulado muchas cosas que me importaban."},{"a":"ashley","t":"La ciudad. La gente. El tendero. También tú, joven caballero."},{"a":"ashley","t":"Solo hicieron falta varios roces con la muerte para darme cuenta. Supongo que soy lento de reflejos, je."},{"a":"argon","t":"Me siento honrado, señorita Samurái!"},{"a":"ashley","t":"Sigo siendo un Ronin aquí. No esperes que eso cambie pronto."},{"a":"yami","t":"..."},{"a":"yami","t":"..."}]},{"id":"ashley_epilogue","i":12,"title":"Epílogo","req":"ashley:11","reward":{"k":"gems","id":"gems","q":10,"n":"Joyas"},"side":false,"lines":[{"a":"ashley","t":"Eh, Lilu. Tengo otra misión. ¿Te vienes?"},{"a":"lilu","t":"¡Pff! ¿Para que me mandes otra vez al lugar equivocado?"},{"a":"lilu","t":"¿O para que te lances a lo loco contra los monstruos y tenga que recomponerte pedazo a pedazo?"},{"a":"ashley","t":"Qué va, ahora soy una mujer nueva. Iré con calma, con toda la tranquilidad del mundo."},{"a":"lilu","t":"Mmm... Lo que tú digas."},{"a":"lilu","t":"Espera un momento..."},{"a":"ashley","t":"¡Ja, ja! Era bromaaaa."},{"a":"ashley","t":"Si tú me cubres, yo te cubro."},{"a":"lilu","t":"¡Me parece bien! Pero esta vez, prométeme algo."},{"a":"lilu","t":"Si la cosa se pone fea... nos retiramos. TÚ incluida."},{"a":"ashley","t":"Te lo prometo. Honor de rōnin, por si te sirve."},{"a":"ashley","t":"Al fin y al cabo, tenemos un hogar al que volver."}]}]},{"id":"bjorn","name":"Bjorn","chapters":[{"id":"bjorn_01","i":1,"title":"La casa de papá","req":"bjorn:1","reward":{"k":"gems","id":"gems","q":10,"n":"Joyas"},"side":false,"lines":[{"a":"bjorn","t":"¡Hola, chicos! ¡Papá está en casa!"},{"a":"steel","t":"¡Papá!"},{"a":"wood","t":"Papá..."},{"a":"bjorn","t":"¿Y esa cara, Gorza?"},{"a":"wood","t":"¡Llevas meses fuera!"},{"a":"bjorn","t":"¡Así es la vida del guardabosques! Pasamos mucho tiempo en la inmensa naturaleza, lejos de casa."},{"a":"wood","t":"Pfft... También podrías pasarte más a menudo."},{"a":"bjorn","t":"Ojalá pudiera, pero el Volcán Lago de Ceniza suele tenerme liadísimo."},{"a":"wood","t":"¿El volcán? ¿No habías dicho que estabas investigando Chapitel Lóbrego?"},{"a":"bjorn","t":"¿Eso dije?"},{"a":"bjorn","t":"¡Me habré confundido con los nombres! ¡Jo, jo!"},{"a":"bjorn","t":"En fin, os he traído unos recuerditos. ¡A ver qué os parecen!"},{"a":"steel","t":"¡Ah! ¡Ojalá haya un peluche blandito!"}]},{"id":"bjorn_a","i":1,"title":"Bamham, un amigo para toda la vida","req":"bjorn:1","reward":{"k":"tokens","id":"tokens","q":3,"n":"Fichas de la fortuna"},"side":true,"lines":[{"a":"bjorn","t":"Chicos, ¿os importa cuidar un ratito de Bamham?"},{"a":"wood","t":"¿Ese jabalí asqueroso? Ni de coña. Llévatelo."},{"a":"steel","t":"No te ofendas, papá, pero está... ¿como una cabra?"},{"a":"bjorn","t":"¡Ah, no digas eso! ¡Si es superadorable!"},{"a":"wood","t":"Papá, cada vez que lo dejas en alguna parte, se vuelve loco."},{"a":"bjorn","t":"Lo de aquella vez fue un accidente. Es que estaba muy entusiasmado."},{"a":"wood","t":"¿Y las demás veces?"},{"a":"bjorn","t":"Eso también fueron accidentes... ¡Mi pequeño Bamham no le haría daño ni a una mosca!"},{"a":"wood","t":"Sí que lo haría, y lo disfrutaría."},{"a":"wood","t":"Papá, es mejor que lleves contigo esa cosa mientras estés por la ciudad."},{"a":"steel","t":"Por la seguridad de todos..."},{"a":"bjorn","t":"Vale, vale. Lo entiendo. No te preocupes, Bamham. Yo te quiero mucho."},{"a":"bjorn","t":"¡Hala, hala! ¡Calma, Bamham!"}]},{"id":"bjorn_02","i":2,"title":"Los recados de Bjorn","req":"bjorn:2","reward":{"k":"gems","id":"gems","q":10,"n":"Joyas"},"side":false,"lines":[{"a":"bjorn","t":"¡Gracias a todo el mundo por la cálida acogida! ¡Me alegra mucho estar de vuelta!"},{"a":"elderowen","t":"Nos alivia ver que has vuelto sano y salvo. Después de estar fuera tantos meses, nos temíamos lo peor."},{"a":"bjorn","t":"¡Perdón, perdón! Es que la vida de un guardabosques es muy ajetreada. ¡Jo, jo, jo!"},{"a":"oils","t":"Conociéndote, seguro que ya estás pensando en tu próxima expedición."},{"a":"bjorn","t":"¡Jo, jo! ¡Me has pillado! De hecho, nos marchamos mañana al amanecer."},{"a":"oils","t":"No cambies nunca, Bjorn. Me aseguraré de cuidar de Brohm y Gorza mientras no estés."},{"a":"oils","t":"Si te pilla bien, ¿podrías recogerme unos pocos chambrillones?"},{"a":"bjorn","t":"¡Claro que sí! ¡No es ninguna molestia!"},{"a":"elderowen","t":"Uf, últimamente me duele mucho la espalda. ¿Me traerías unas perlas gélidas?"},{"a":"bjorn","t":"Solo me tengo que desviar un poquito. Estaré pendiente, venerable."},{"a":"engineer","t":"¡Ah, Bjorn! Necesito unas escamas del dragón metalívoro para mi próximo experimento. ¿Podrías traérmelas?"},{"a":"bjorn","t":"Claro, claro. ¡Me lo apunto!"},{"a":"bjorn","t":"¡Buf! Será mejor que llevemos más sacos, Bamham."}]},{"id":"bjorn_03","i":3,"title":"Oro a raudales","req":"bjorn:3","reward":{"k":"gems","id":"gems","q":10,"n":"Joyas"},"side":false,"lines":[{"a":"bjorn","t":"Mmm... ¿Hueles lo mismo que yo, Bamham?"},{"a":"bjorn","t":"En efecto, es metal. Seguramente esté por ahí tirado. ¡Hay que buscarlo y recogerlo!"},{"a":"bjorn","t":"Buen chico. A ver qué hay aquí..."},{"a":"bjorn","t":"Anda, qué artefacto tan extraño. No creo que lo hayan dejado aquí por accidente..."},{"a":"bjorn","t":"Seguro que si tiro un poco de esa palanca..."},{"a":"bjorn","t":"Mmm... Sí, justo como sospechaba."},{"a":"bjorn","t":"Se rompe... Supongo que no hemos descubierto gran cosa, ¿eh? ¡Jo, jo!"},{"a":"bjorn","t":"Aun así, creo que tenemos nuestra pista. Llevamos meses explorando la zona, y esta cosa no estaba aquí la última vez."},{"a":"bjorn","t":"Será mejor volver y preguntarle a un profesional. ¡Ya sabes que la tecnología no es lo mismo!"}]},{"id":"bjorn_04","i":4,"title":"Baliza desconocida","req":"bjorn:4","reward":{"k":"gems","id":"gems","q":10,"n":"Joyas"},"side":false,"lines":[{"a":"engineer","t":"¡Qué cosa tan curiosa! Nunca había visto algo igual."},{"a":"engineer","t":"Parece combinar magia y ciencia para actuar como una especie de... ¿baliza? ¿Radar?"},{"a":"engineer","t":"¿Dices que estaba roto cuando lo encontraste?"},{"a":"bjorn","t":"Sí. Qué mala suerte, ¿no? ¡Jo, jo!"},{"a":"engineer","t":"Qué lástima. Solo te puedo decir que esto transmite algún tipo de información."},{"a":"engineer","t":"¿Sabes qué? Si me das un minuto, puedo fabricarte un dispositivo para ayudarte a encontrar más... «balizas mágicas»."},{"a":"bjorn","t":"¡Genial! ¿Todo listo para regresar, Bamham?"},{"a":"bjorn","t":"No sabemos qué clase de cosas son estas..., pero no pueden ser buenas."},{"a":"bjorn","t":"¡Nuestro trabajo es averiguar quién está detrás de todo esto!"},{"a":"engineer","t":"¡Buena suerte! Ah, y mucho cuidado con esta tecnología misteriosa."}]}]},{"id":"donovan","name":"Donovan","chapters":[{"id":"donovan_01","i":1,"title":"Receta original","req":"donovan:1","reward":{"k":"gems","id":"gems","q":10,"n":"Joyas"},"side":false,"lines":[{"a":"herbalist","t":"Te doy la bienvenida al Centro medicinal Maribel. ¿Cómo puedo ayudarte?"},{"a":"donovan","t":"Señorita Maribel, ¿verdad? Me gustaría felicitarte personalmente por tu última creación."},{"a":"donovan","t":"Como inventor de la poción de renovación, puedo decirte que tu plano modificado es impresionante."},{"a":"donovan","t":"Añadir una pizca de flor de los picos es una mejora increíble."},{"a":"herbalist","t":"Un momento..., ¿eres el famoso Donovan? ¡No me lo puedo creer!"},{"a":"herbalist","t":"El plano de la poción de renovación se inventó hace unos 700 años..."},{"a":"herbalist","t":"Aun siendo un elfo, no aparentas más de 150."},{"a":"donovan","t":"Qué amable, señorita Maribel."},{"a":"donovan","t":"Digamos que no todos mis planos están a la venta..."},{"a":"donovan","t":"Pero seguro que un maestro alquimista como tú podría aprenderlos fácilmente."},{"a":"donovan","t":"Muy bien, ¿puedo echarle un vistazo a esa flor de los picos?"}]},{"id":"donovan_02","i":2,"title":"Tierra de la abundancia","req":"donovan:2","reward":{"k":"gems","id":"gems","q":10,"n":"Joyas"},"side":false,"lines":[{"a":"donovan","t":"Es fascinante... Incluso las manzanas de este lugar son de excelente calidad."},{"a":"donovan","t":"¿Cómo puede ser?"},{"a":"lilu","t":"Si alguien conoce la razón, ¡esa es Juniper!"},{"a":"lilu","t":"¡Anda, lo siento! No quería interrumpir tu conversación con ese... árbol."},{"a":"donovan","t":"Ah, una jovencita con un sombrero de ala ancha y su leal búho..."},{"a":"donovan","t":"Tú debes de ser Lilu, sin duda."},{"a":"lilu","t":"¡Así es! Y tú, señor Donovan, no necesitas presentación."},{"a":"donovan","t":"He oído hablar de la talentosa y joven aprendiz de la ciudad. El placer es todo mío."},{"a":"donovan","t":"Bien, Lilu, ¿decías que...?"},{"a":"lilu","t":"¡Ah, sí! Juniper siempre afirma que la tierra está llena de vida alrededor de la ciudad."},{"a":"lilu","t":"Dice que por eso le gusta tanto cultivar plantas aquí."},{"a":"lilu","t":"En fin, me has pillado de camino a las Cuevas de la Aurora. Encantada de conocerte, señor Donovan."},{"a":"donovan","t":"Ojalá volvamos a vernos pronto."},{"a":"donovan","t":"Mmm, puede que esta jovencita sepa algo..."},{"a":"donovan","t":"La tierra de Kern... ¿se ha vuelto infértil? En este reino, todo parece más lleno de vida."},{"a":"donovan","t":"Debería hacerle una visita a la horticultora. Si aquí los ingredientes son más potentes..."},{"a":"donovan","t":"Habrá que aprovecharlo."}]},{"id":"donovan_03","i":3,"title":"Bajo la máscara","req":"donovan:3","reward":{"k":"gems","id":"gems","q":10,"n":"Joyas"},"side":false,"lines":[{"a":"lilu","t":"¿Me has llamado, señorita Sia?"},{"a":"sia","t":"Ah, Lilu. Gracias por venir con tan poca antelación."},{"a":"sia","t":"Creo que ya conoces a Donovan, ¿verdad?"},{"a":"lilu","t":"¡Sí, es toda una leyenda entre los alquimistas! Es un placer."},{"a":"sia","t":"Ten cuidado con él."},{"a":"lilu","t":"¡¿Cómo?! Pero si es todo un caballero, y también muy culto..."},{"a":"sia","t":"Las apariencias engañan. Tras ese semblante agradable se esconde un genio astuto con miles de años a sus espaldas..."},{"a":"lilu","t":"¿Miles? Eso es inaudito, incluso para los elfos. ¿Crees que...?"},{"a":"sia","t":"Sí, se dice que puede haber descubierto una especie de elixir de la inmortalidad."},{"a":"lilu","t":"¡Hala! Pues me encantaría incorporar esa fórmula a mi grimorio."},{"a":"sia","t":"Igual que muchos monarcas. Sospecho que tiene al emperador Kern comiendo de su mano."},{"a":"lilu","t":"... La política siempre es un asunto complejo."},{"a":"lilu","t":"Pero gracias, tendré cuidado con él."},{"a":"sia","t":"Sabía que lo entenderías."},{"a":"sia","t":"Por mi parte, me aseguraré de que no se acerque a nuestro rey. Es un poco... impresionable."},{"a":"lilu","t":"Sí, probablemente sea lo mejor."}]},{"id":"donovan_a","i":3,"title":"Diez monedas de oro, un chollo","req":"donovan:3","reward":{"k":"tokens","id":"tokens","q":3,"n":"Fichas de la fortuna"},"side":true,"lines":[{"a":"leather","t":"Tú, el de las pociones. ¿Tienes un minuto?"},{"a":"donovan","t":"Agh..., vagabundos."},{"a":"donovan","t":"¿Con quién tengo el... placer de hablar?"},{"a":"leather","t":"Soy Tamas, el curtidor de pieles."},{"a":"leather","t":"Me han dicho que preparas un elixir de inmortalidad tremendo. ¿Me das una botella?"},{"a":"donovan","t":"No sé dónde te sacas semejante rumor."},{"a":"donovan","t":"Aunque fuera cierto, te garantizo que no iría repartiendo por ahí algo tan preciado."},{"a":"leather","t":"Te daré diez monedas de oro."},{"a":"donovan","t":"Ni hablar. ¡Se han librado auténticas guerras por la fórmula, y emperadores de todo el mundo se postran para poder probar una gota!"},{"a":"leather","t":"Sí que eres duro de pelar, tío. Venga, quince monedas. Es mi última oferta."},{"a":"donovan","t":"¿El olor del cuero te ha afectado al cerebro, chalado? ¡No me desprenderé de esta fórmula ni por todo el oro del mundo!"},{"a":"donovan","t":"Debo irme. No vuelvas a dirigirme la palabra, te lo ruego."},{"a":"leather","t":"Jope, lo tenía a punto..."},{"a":"leather","t":"En fin, tendré que darles otra cosa a las ovejas."}]}]},{"id":"hemma","name":"Hemma","chapters":[{"id":"hemma_01","i":1,"title":"Sombra acechante","req":"hemma:1","reward":{"k":"gems","id":"gems","q":10,"n":"Joyas"},"side":false,"lines":[{"a":"hemma","t":"Y así el trasco cayó, pero primero asestó golpes certeros a mis compañeros."},{"a":"hemma","t":"Te suplico que los cures."},{"a":"priest","t":"Por supuesto que sí, sanaré sus heridas ahora mismo."},{"a":"lilu","t":"¡Hola! Me he enterado de que había una encantadora nueva en la ciudad."},{"a":"lilu","t":"Soy Lilu, ¡encantada de conocerte!"},{"a":"hemma","t":"En efecto, joven Lilu. Nos llamamos Hemma. "},{"a":"lilu","t":"¿«Nos»?"},{"a":"hemma","t":"Sí, la nigromancia suele pasarle factura a quienes la practican..."},{"a":"hemma","t":"Una parte se queda en el velo, y otros elementos cruzan el umbral..."},{"a":"hemma","t":"Estos poderes nos han cambiado... Para bien, obviamente."},{"a":"lilu","t":"¡¿Nigromancia?! Oye, eso no es... ¿peligroso?"},{"a":"hemma","t":"Enormemente peligroso, pero los trucos más sencillos ya no resultaban satisfactorios."},{"a":"hemma","t":"Discúlpanos, pero tenemos cosas que hacer. ¡Hasta la próxima!"},{"a":"lilu","t":"Una nigromante... Practican magia muy oscura, Pólux. ¡Es la primera vez que veo uno cara a cara!"},{"a":"lilu","t":"No parecía mala gente, ¿verdad?"}]},{"id":"hemma_02","i":2,"title":"A cualquier precio","req":"hemma:2","reward":{"k":"gems","id":"gems","q":10,"n":"Joyas"},"side":false,"lines":[{"a":"elderowen","t":"¿Una nigromante?"},{"a":"elderowen","t":"No sé qué pensar..."},{"a":"hemma","t":"Es lógico que te preocupes. La nigromancia es una práctica muy peligrosa que consume a seres inferiores..."},{"a":"hemma","t":"Pero no somos inferiores."},{"a":"elderowen","t":"¿Y qué me dices de los aventureros que te acompañan? ¿No absorbes su energía para potenciar tus hechizos?"},{"a":"hemma","t":"Solo si nos dan su permiso, y los efectos no son permanentes."},{"a":"hemma","t":"Además, les pagamos generosamente por esos servicios."},{"a":"elderowen","t":"Parece que sí haces cosas buenas..."},{"a":"elderowen","t":"En fin, supongo que te permitiremos ser campeona en nuestra ciudad."},{"a":"hemma","t":"No necesitábamos ningún permiso, pero gracias."},{"a":"elderowen","t":"¿Por qué has venido a nuestra ciudad?"},{"a":"hemma","t":"..."},{"a":"hemma","t":"Vinimos en busca de conocimientos y poder, eso es todo. "},{"a":"hemma","t":"Debemos... cumplir con una tarea."},{"a":"elderowen","t":"Eso no es muy concreto que digamos."},{"a":"hemma","t":"Y así se quedará. Hasta la vista."},{"a":"elderowen","t":"..."},{"a":"elderowen","t":"Veo mucha tristeza en esos ojos..."}]},{"id":"hemma_03","i":3,"title":"El enemigo del interior","req":"hemma:3","reward":{"k":"gems","id":"gems","q":10,"n":"Joyas"},"side":false,"lines":[{"a":"herbalist","t":"Raíces vivas no maduras y un ectoplasma espeluznante XXL. ¿Alguna cosa más?"},{"a":"hemma","t":"Eso es todo. Iremos a ver al comerciante para las demás cosas."},{"a":"herbalist","t":"¡Gracias, hasta la próxima!"},{"a":"hemma","t":"<c4>... Faltan las garras grimosas.</c4>"},{"a":"hemma","t":"Ah, sí. Y un par de garras grimosas, por favor."},{"a":"herbalist","t":"¿Qué ha sido eso?"},{"a":"hemma","t":"Ignóralo. Un simple pasajero..."},{"a":"hemma","t":"<c4>Quiero salir, quiero salir, quiero salir, quiero salir...</c4>"},{"a":"hemma","t":"Uf, cálmate un poquito, anda."},{"a":"hemma","t":"Quédate con el cambio. Hasta la próxima."},{"a":"herbalist","t":"Gracias por la propina... y las pesadillas..."}]},{"id":"hemma_a","i":3,"title":"Entre inmortales","req":"hemma:3","reward":{"k":"tokens","id":"tokens","q":3,"n":"Fichas de la fortuna"},"side":true,"lines":[{"a":"donovan","t":"¿Raíces vivas sin madurar? Interesante elección."},{"a":"hemma","t":"¿Por qué?"},{"a":"donovan","t":"Las raíces vivas son unos catalizadores muy potentes en la magia relacionada con la juventud, y también para alargar la vida."},{"a":"donovan","t":"¿Eres una alquimista? ¿Acaso buscas alargar tu vida?"},{"a":"hemma","t":"¿Vas a preguntarle su edad a una dama? Qué inapropiado..."},{"a":"hemma","t":"No somos alquimistas. Los sacrificios de sangre son mucho más eficaces."},{"a":"donovan","t":"Ah, nigromancia... Un campo respetable, aunque también incomprendido."},{"a":"hemma","t":"En cuanto a nuestra edad..., hace tiempo que dejamos de contar años."},{"a":"donovan","t":"Igual que yo. Después de los primeros siglos, las décadas pasan en un abrir y cerrar de ojos."},{"a":"donovan","t":"Se siente mucha soledad entre estas criaturas efímeras, ¿verdad?"},{"a":"hemma","t":"Pues no. Un consejo: no te entrometas en los asuntos de un nigromante."},{"a":"donovan","t":"No tengo ninguna intención de hacerlo. ¡Hasta la vista!"},{"a":"donovan","t":"Qué nigromante tan peculiar... ¿Nos conocemos de antes?"},{"a":"donovan","t":"¿Fairlyn?"}]},{"id":"hemma_04","i":4,"title":"Exorcismo","req":"hemma:4","reward":{"k":"gems","id":"gems","q":10,"n":"Joyas"},"side":false,"lines":[{"a":"lilu","t":"No te preocupes, Hemma. Ya estoy aquí, ¡y vengo con Freyja!"},{"a":"priest","t":"Te llamabas Hemma, ¿verdad? Tranquila, déjate llevar por el exorcismo..."},{"a":"hemma","t":"No recordamos haberte pedido ayuda."},{"a":"hemma","t":"<c4>Dejadme en paz, que no me voy a ninguna parte.</c4>"},{"a":"lilu","t":"¡Aaah! ¡Nos está ganando terreno! ¡Date prisa, Freyja!"},{"a":"priest","t":"¡No puedo! Hay algo que bloquea las oraciones..."},{"a":"hemma","t":"Somos nosotros. Déjalo ya."},{"a":"priest","t":"¿Quieres tener dentro a ese espíritu malvado?"},{"a":"hemma","t":"Admito que cada vez se porta peor."},{"a":"hemma","t":"<c4>¡La víctima soy yo! ¡Dejadme salir!</c4>"},{"a":"hemma","t":"Uf... Te garantizo que es más grosero que malvado."},{"a":"hemma","t":"Este asunto no te incumbe, Freyja. No te entrometas, por favor."},{"a":"priest","t":"Dichosos nigromantes..., siempre jugando con poderes que no alcanzan a entender."},{"a":"lilu","t":"No te preocupes, Freyja. Seguro que sabe lo que se hace."},{"a":"lilu","t":"¿No?"}]},{"id":"hemma_05","i":5,"title":"Psique doble","req":"hemma:5","reward":{"k":"gems","id":"gems","q":10,"n":"Joyas"},"side":false,"lines":[{"a":"hemma","t":"<c4>Parece que nos han vuelto a pillar. ¿Todo listo para irnos de la ciudad?</c4>"},{"a":"hemma","t":"Todo esto es culpa tuya. Si hubieras cerrado el pico, las cosas serían mucho más fáciles."},{"a":"hemma","t":"Además, todavía no nos marchamos. Esta ciudad tiene mucho potencial."},{"a":"hemma","t":"<c4>Vale. ¿Y si me dejas salir, para variar un poco?</c4>"},{"a":"hemma","t":"Ah, no. Ni hablar. Bastante me cuesta tenerte bajo control."},{"a":"hemma","t":"<c4>Quiero salir, quiero salir, quiero salir, quiero salir...</c4>"},{"a":"hemma","t":"Lo hago por tu bien, Claud."},{"a":"hemma","t":"... No lo olvides."}]},{"id":"hemma_06","i":6,"title":"Legado de mentiras","req":"hemma:6","reward":{"k":"gems","id":"gems","q":10,"n":"Joyas"},"side":false,"lines":[{"a":"lilu","t":"¡Fairlyn!"},{"a":"hemma","t":"¿Sí?"},{"a":"lilu","t":"¡Lo sabía! Hemma no es más que un seudónimo. ¡Tú eres el monstruo, Fairlyn!"},{"a":"hemma","t":"Caramba, menuda tramposilla tenemos aquí..."},{"a":"hemma","t":"Es cierto. Parece que has hecho los deberes."},{"a":"hemma","t":"¿Has oído hablar de Ariel la Desquiciada? ¿O de Astrid la Caída?"},{"a":"lilu","t":"Bueno..., he leído acerca de ellas..., ¡pero hace años que desaparecieron! Es imposible..."},{"a":"hemma","t":"Somos nosotros, naturalmente. Por desgracia, nos hemos enfrentado a muchos años de persecución, y ha sido necesario cambiar de nombre..."},{"a":"lilu","t":"¡Eres un monstruo! ¡Debemos detenerte!"},{"a":"hemma","t":"¿Y cómo vas a hacerlo? «Hemma» es inocente. ¿Quién se creería una historia tan peregrina?"},{"a":"hemma","t":"A no ser que intentes detenerme tú misma..."},{"a":"lilu","t":"¡Grrr!"}]},{"id":"hemma_07","i":7,"title":"Unión de almas","req":"hemma:7","reward":{"k":"gems","id":"gems","q":10,"n":"Joyas"},"side":false,"lines":[{"a":"hemma","t":"¿Sigues por aquí?"},{"a":"lilu","t":"No te pienso quitar el ojo de encima. A ti y a tus sospechosos monólogos..."},{"a":"hemma","t":"Ah, sí. Te presento a Claud, mi esposo. Antes estaba mejor."},{"a":"hemma","t":"<c4>¡Déjame salir!</c4>"},{"a":"lilu","t":"¿Qué le ha pasado?"},{"a":"hemma","t":"Un accidente nigromántico terrible. Un error insensato le colocó al borde de la muerte."},{"a":"hemma","t":"Teniendo en cuenta los pecados que cometemos en este mundo, el más allá resulta una idea aterradora para los nigromantes..."},{"a":"hemma","t":"Como no pudimos salvar su cuerpo, decidimos centrarnos en salvar su alma."},{"a":"lilu","t":"¿Una unión de almas? Este hechizo necesita años de investigación para buscar un recipiente adecuado..."},{"a":"hemma","t":"Así es. Las circunstancias nos obligaron a improvisar."},{"a":"lilu","t":"¿A improvisar? No me digas que... ¡¿has vinculado el alma de Claud a la tuya?!"},{"a":"lilu","t":"¡Un cuerpo no puede albergar dos almas! Eso provocaría..."},{"a":"hemma","t":"Un dolor insoportable, la locura... Es peor de lo que te imaginas."},{"a":"lilu","t":"Hemma... ¿Por qué? ¿Cómo...?"},{"a":"hemma","t":"Fácil, pequeña Lilu. El fracaso nunca es una opción."}]},{"id":"hemma_08","i":8,"title":"El tesoro de un siglo","req":"hemma:8","reward":{"k":"gems","id":"gems","q":10,"n":"Joyas"},"side":false,"lines":[{"a":"lilu","t":"Es demasiado poderoso como para realizar un exorcismo... Tal vez se podría vincular el alma a otra cosa..."},{"a":"hemma","t":"Te vemos muy dispuesta a cooperar. ¿Acaso te interesa la nigromancia?"},{"a":"lilu","t":"¡No! ¡Te odio! ¡A ti, y a todas las maldades que has cometido!"},{"a":"lilu","t":"Me parece que, si se libera a Claud, causará muchísimos problemas a todas las personas que aquí viven."},{"a":"lilu","t":"¡Te ayudaré a solucionar este problema, nada más!"},{"a":"hemma","t":"Un sentimiento muy noble. Pero ¿cómo puede ayudarnos una simple niña?"},{"a":"lilu","t":"Preparar un recipiente adecuado necesitaría décadas de investigación y materiales..."},{"a":"hemma","t":"Por eso no te preocupes. Observa."},{"a":"lilu","t":"¡...! ¿De dónde has sacado todo esto? ¡Hasta hay diamantes negros!"},{"a":"hemma","t":"No hemos malgastado estas últimas décadas. Apenas nos queda tiempo."},{"a":"hemma","t":"Lo que nos falta es una ubicación adecuada para llevar a cabo el ritual. Tememos que no exista un lugar así."},{"a":"lilu","t":"Sí, el alma necesita un vínculo espiritual con la zona, o no se podrá realizar el hechizo."},{"a":"hemma","t":"<c4>¡O podrías liberar al bueno de Claud Favius! ¡Es muy sociable!</c4>"},{"a":"lilu","t":"Un momento..., ¿has dicho «Favius»?"}]},{"id":"hemma_09","i":9,"title":"El castillo encantado","req":"hemma:9","reward":{"k":"gems","id":"gems","q":10,"n":"Joyas"},"side":false,"lines":[{"a":"hemma","t":"Qué lugar tan maravillosamente aterrador."},{"a":"lilu","t":"Es un lugar espantoso. Ninguna persona con dos dedos de frente vendría aquí."},{"a":"lilu","t":"Pero, lo más importante, y según mis investigaciones..."},{"a":"lilu","t":"... Un rey loco de la familia Favius gobernó en este lugar hace siglos."},{"a":"lilu","t":"A lo mejor Claud es un pariente lejano... Espero que no tenga nada que ver con la desgracia que cayó sobre aquel reino..."},{"a":"hemma","t":"Podemos sentirlo... Estamos conectados con este lugar. Es aquí."},{"a":"hemma","t":"Estamos en deuda contigo, Lilu. Sin embargo, ahora debes marcharte."},{"a":"lilu","t":"Hemma... Buena suerte."}]},{"id":"hemma_10","i":10,"title":"Hasta que la muerte nos separe","req":"hemma:10","reward":{"k":"gems","id":"gems","q":10,"n":"Joyas"},"side":false,"lines":[{"a":"hemma","t":"Un lugar tenebroso y apartado, rebosante de energía nigromántica..."},{"a":"hemma","t":"¿Cuánto tiempo hemos buscado un lugar como este?"},{"a":"hemma","t":"Ahora, hay que buscar un recipiente adecuado..."},{"a":"hemma","t":"No hace falta hablar. Sabemos exactamente qué deseas."},{"a":"Castle_Boss","t":"..."},{"a":"hemma","t":"La armadura del mismísimo rey loco, unida eternamente a este lugar."},{"a":"hemma","t":"<c1>¡La unión de almas!</c1>"},{"a":"Castle_Boss","t":"..."},{"a":"hemma","t":"Agh... Nos sentimos... ¿O... me siento?"},{"a":"hemma","t":"Había olvidado esta sensación de soledad..."},{"a":"hemma","t":"He sufrido una eternidad para salvarte, mi amor. Sé que tú habrías hecho lo mismo por mí."},{"a":"hemma","t":"No me cabe duda de que llegarán aventureros valientes. Enfréntate a ellos y cura tu tortuosa existencia con la matanza."},{"a":"Castle_Boss","t":"..."},{"a":"hemma","t":"Adiós, cariño. Solo nos despediremos de verdad cuando llegue la muerte."}]},{"id":"hemma_epilogue","i":11,"title":"Epílogo","req":"hemma:11","reward":{"k":"gems","id":"gems","q":10,"n":"Joyas"},"side":false,"lines":[{"a":"Castle_Boss","t":"<c4>¡IDIOTAS! ¿CÓMO OSÁIS ADENTRAROS EN MIS TIERRAS?</c4>"},{"a":"sia","t":"¡Qué enemigo tan fastidioso!"},{"a":"Castle_Boss","t":"<c4>¡MUAJAJAJÁ! ¡MORTALES ENCLENQUES!</c4>"},{"a":"argon","t":"¡Señorita Sia! ¡Rudo! ¡Debemos retirarnos!"},{"a":"rudo","t":"¡Jamás! ¡No pienso ceder ni un centímetro ante él!"},{"a":"yami","t":"He encontrado una salida. ¡Deprisa!"},{"a":"rudo","t":"¡Bah! ¡Volveré, lata de sardinas! ¿Me has oído?"},{"a":"Castle_Boss","t":"<c4>¡VUELVE CUANDO PUEDAS LUCHAR DE VERDAD!</c4>"},{"a":"Castle_Boss","t":"<c4>¡DILES A TUS MEJORES HÉROES QUE EL REY TIRANO LES ESTÁ ESPERANDO!</c4>"}]}]},{"id":"lilu","name":"Lilu","chapters":[{"id":"lilu_01","i":1,"title":"Una aprendiz precoz","req":"lilu:1","reward":{"k":"gems","id":"gems","q":10,"n":"Joyas"},"side":false,"lines":[{"a":"lilu","t":"Bueno, Pólux, ¿qué te parece este nuevo conjuro? Es perfecto, ¿a que sí?"},{"a":"lilu","t":"Sí, ¡esta vez seguro que arrasamos!"},{"a":"herbalist","t":"Buenos días, Lilu. ¿Vienes a por el envío semanal de raíces vivas?"},{"a":"lilu","t":"Sí, ¡gracias, Maribel!"},{"a":"herbalist","t":"¡Esta semana has pedido un montón! ¿Qué va a hacer tu maestro con tantas?"},{"a":"lilu","t":"En realidad, la mitad son para mí. ¡Estoy estudiando en serio!"},{"a":"herbalist","t":"Ah, ¿sí? ¿Qué estudias?"},{"a":"lilu","t":"¡Conjuros de curación! Llevo toda la semana curando cortes y moratones en la sala de entrenamiento."},{"a":"herbalist","t":"Pues seguro que los héroes están encantados de tenerte."},{"a":"herbalist","t":"¡Y Argon también!"},{"a":"lilu","t":"¡...!"},{"a":"lilu","t":"T-tengo que irme, ¡gracias!"}]},{"id":"lilu_02","i":2,"title":"Noticias grimosas","req":"lilu:2","reward":{"k":"gems","id":"gems","q":10,"n":"Joyas"},"side":false,"lines":[{"a":"lilu","t":"Aquí tiene, maestro Grimar: las raíces vivas de esta semana."},{"a":"wizard","t":"Gracias, Lola. Aquí tienes los deberes de hoy."},{"a":"lilu","t":"¡Anda, un tomo mágico! ¡¿Es sobre curación?!"},{"a":"lilu","t":"¿«El Manual sobre Maleficios del Malhechor»...?"},{"a":"lilu","t":"¡Este libro es demasiado avanzado! ¡Hasta tiene toda una sección sobre maldiciones!"},{"a":"wizard","t":"¿Maldiciones...?"},{"a":"wizard","t":"Mmm... ¿Maldiciones...?"},{"a":"lilu","t":"¿Maestro?"},{"a":"wizard","t":"Hace 35 años, este mismo día, yo..."},{"a":"lilu","t":"¡¿Maestro Grimar?!"},{"a":"wizard","t":"... Se me ha olvidado. ¿Y tú quién eres?"},{"a":"lilu","t":"Soy Lilu, su aprendiz. A veces soy Lola..."},{"a":"lilu","t":"Bueno, da igual. Voy a estudiarme el libro. Gracias, Grimar."}]},{"id":"lilu_03","i":3,"title":"Mente aturdida","req":"lilu:3","reward":{"k":"gems","id":"gems","q":10,"n":"Joyas"},"side":false,"lines":[{"a":"lilu","t":"Se añade una pizca de polvo de plata y... ¡listo!"},{"a":"lilu","t":"¡Mira cómo brilla! No está mal, ¿verdad, Pólux?"},{"a":"lilu","t":"Si lo que pone en el Manual sobre Maleficios del Malhechor es cierto, la poción debería..."},{"a":"wizard","t":"Lola, ¿qué es este alboroto? ¡Estoy intentando dormir!"},{"a":"lilu","t":"¡Maestro Grimar! He preparado una elaborada poción gracias a su libro. Debería..."},{"a":"wizard","t":"¿Que has hecho qué?"},{"a":"wizard","t":"Bueno, dámela entonces. ¡Veamos a qué sabe!"},{"a":"wizard","t":"..."},{"a":"lilu","t":"¿Maestro Grimar?"},{"a":"wizard","t":"¡Lilu! ¡Li-li-libérame! Déjame salir de esta men-mente estúpida y a-to-tolondrada."},{"a":"lilu","t":"¡Maestro Grimar! ¿Se encuentra bien?"},{"a":"wizard","t":"..."},{"a":"wizard","t":"(Eructando). ¡Sabe a fruta!"},{"a":"wizard","t":"No está mal, Lola. Ahora vuelve a tus tareas."},{"a":"lilu","t":"Lo que ha pasado no es normal."}]},{"id":"lilu_a","i":3,"title":"Acumula, que algo queda","req":"lilu:3","reward":{"k":"tokens","id":"tokens","q":3,"n":"Fichas de la fortuna"},"side":true,"lines":[{"a":"lilu","t":"Grimar, no sabía que tenías otro <c1>libro de colecciones</c1>."},{"a":"wizard","t":"¿Un <c1>libro de colecciones</c1>? Me quiere sonar de algo..."},{"a":"lilu","t":"¡Anda, pues hay un montón de cosas! <c1>Damocles</c1>... <c1>ciudadela ámbar</c1>..."},{"a":"lilu","t":"¿Has mencionado la <c1>varita magnífica de Grimar</c1>?"},{"a":"lilu","t":"¡Cuántas páginas! ¡Menudo coleccionista estás hecho!"},{"a":"sundragon","t":"Sin duda lo era."},{"a":"wizard","t":"¿Eres tú, Sondra, viejo amigo?"},{"a":"lilu","t":"¡Hala! ¿Os conocéis?"},{"a":"sundragon","t":"Por supuesto. El joven Grimar estaba fascinado con su libro de colecciones."},{"a":"sundragon","t":"Creo que incluso obtuvo un título muy prestigioso entre los humanos... Creo que era «empollón»."},{"a":"lilu","t":"Ay, madre..."},{"a":"sundragon","t":"Nos conocimos durante su misión en busca de objetos especiales, y juntos creamos el <c1>caldero de fusiones</c1>."},{"a":"sundragon","t":"Se pasaba el día fusionando cientos de objetos, ¡y eran muchos más si había luna llena!"},{"a":"lilu","t":"Lo cierto es que se esforzó muchísimo, pero su colección sigue incompleta."},{"a":"lilu","t":"Le prometo que encontraré una cura para usted, maestro Grimar. ¡Tiene que finalizar el trabajo de toda una vida!"},{"a":"sundragon","t":"El tiempo es cruel con la humanidad... Te deseo mucha suerte en tu misión, joven."}]},{"id":"lilu_04","i":4,"title":"Fin del linaje","req":"sia:3","reward":{"k":"gems","id":"gems","q":10,"n":"Joyas"},"side":false,"lines":[{"a":"lilu","t":"Algo le pasa al Maestro Grimar..."},{"a":"lilu","t":"Su voz... ¡Es como si alguien hablara desde su interior!"},{"a":"lilu","t":"¿A lo mejor se trata de un complejo hechizo de transmutación?"},{"a":"lilu","t":"O incluso..."},{"a":"leather","t":"¡Lilu, tía! Algo salió mal en el banquete del Rey."},{"a":"lilu","t":"¿Tamas? ¿Qué pasa?"},{"a":"leather","t":"Había un invasor en el castillo o algo así, colega. ¡Qué mal rollo!"},{"a":"lilu","t":"¡¿Un invasor?! Oh, no... Es el primer día de Argon como caballero."},{"a":"lilu","t":"Gracias, Tamas. Tengo que irme."},{"a":"lilu","t":"Oh, no... ¿Qué está pasando aquí?"},{"a":"lilu","t":"Argon, ¿dónde estás?"},{"a":"king","t":"Aaarg..."},{"a":"lilu","t":"¿Rey Reinhold? ¿Se encuentra bien?"},{"a":"king","t":"Aaah... mi valiosa vida... esfumándose..."},{"a":"lilu","t":"¡Algo va mal!"},{"a":"lilu","t":"¡Céntrate, Lilu! Acuérdate de la formación de sabia."},{"a":"lilu","t":"¡Rey Reinhold! ¡No se mueva! ¡<c1>Curación</c1>!"},{"a":"king","t":"Es inútil... Por favor, preservad mi hermoso cuerpo."},{"a":"lilu","t":"No ha funcionado."},{"a":"lilu","t":"Oh, no. ¿Será veneno?"},{"a":"lilu","t":"Igual que mis padres... ¡Esta vez no fallaré! ¡No puedo fallar!"},{"a":"lilu","t":"<c1>¡Gran purga de veneno!</c1>"},{"a":"king","t":"Aaah... ¿Eh?"},{"a":"lilu","t":"¡Rey Reinhold! ¿Qué tal se encuentra?"},{"a":"lilu","t":"Un momento... ¡La taza le protegió de la shuriken! ¡No estaba herido!"},{"a":"king","t":"¡Oh! ¿En serio? Entonces puede que haya exagerado un poquito."},{"a":"king","t":"Después de todo, la muerte de un monarca es un asunto dramático."},{"a":"lilu","t":"¡Arg! ¡Reinhold!"}]},{"id":"lilu_05","i":5,"title":"De algo hay que morir","req":"lilu:5","reward":{"k":"gems","id":"gems","q":10,"n":"Joyas"},"side":false,"lines":[{"a":"lilu","t":"Uf... Por los pelos..., más o menos."},{"a":"lilu","t":"Si hubieran envenenado a Reinhold, creo que no hubiera podido salvarle."},{"a":"lilu","t":"Tendré que cambiar de estrategia. No quiero que le pase lo mismo que a mí a nadie más..."},{"a":"lilu","t":"¡Señorita Sia!"},{"a":"sia","t":"¡Oh, la estrella del momento! Han enviado a un caballero a encargarse de la intrusa. No tienes nada de lo que preocuparte."},{"a":"lilu","t":"(¿Un caballero? ¡Suerte, Argon!)."},{"a":"sia","t":"Gracias por salvar al rey, pese a las circunstancias."},{"a":"lilu","t":"¡Oh, no ha sido nada! Pero si vuelve a pasar, no estoy segura de poder ayudar..."},{"a":"lilu","t":"Señorita Sia, ¿sabes algo sobre venenos?"},{"a":"sia","t":"Claro. El acónitos es un veneno muy eficiente y letal."},{"a":"sia","t":"Pero mi preferido es la ricina: silenciosa, mortal y fácil de conseguir."},{"a":"lilu","t":"Mmm... ¿Y qué sabes sobre antídotos?"},{"a":"sia","t":"Oh, la verdad es que nunca me he parado a pensar en eso."},{"a":"lilu","t":"Olvídalo."}]},{"id":"lilu_06","i":6,"title":"Maestro y estudiante","req":"lilu:6","reward":{"k":"gems","id":"gems","q":10,"n":"Joyas"},"side":false,"lines":[{"a":"lilu","t":"¡He vuelto, maestro Grimar!"},{"a":"wizard","t":"Oh, bienvenida de nuevo, Lola."},{"a":"lilu","t":"¿Puedes creerlo? ¡Casi asesinan al rey!"},{"a":"wizard","t":"¿En serio...?"},{"a":"lilu","t":"Una asesina apareció de la nada y lo atacó con una shuriken."},{"a":"lilu","t":"Entonces acudí de inmediato a ayudarlo mientras yacía en el suelo..."},{"a":"wizard","t":"Eh... ¿Quién dices que eres?"},{"a":"lilu","t":"Huy, es verdad, tengo que ocuparme de tu problemilla."},{"a":"lilu","t":"A lo mejor también es un veneno..."},{"a":"lilu","t":"Veamos, Grimar es viejísimo..."},{"a":"lilu","t":"¿Tú qué dices, Pollux?"},{"a":"lilu","t":"Sí, deberíamos preguntar por la ciudad."},{"a":"lilu","t":"Puede que alguno de los habitantes más longevos recuerde cómo se comportaba Grimar de joven..."}]},{"id":"lilu_07","i":7,"title":"Conocimiento ancestral","req":"lilu:7","reward":{"k":"gems","id":"gems","q":10,"n":"Joyas"},"side":false,"lines":[{"a":"lilu","t":"¡Maestro Theodore!"},{"a":"master","t":"¡Pero si es Lilu! ¿Cómo puedo ayudarte?"},{"a":"lilu","t":"Quería saber si podrías contarme cosas sobre Grimar, de cuando era joven..."},{"a":"lilu","t":"Como eres viejo y eso..."},{"a":"master","t":"¡Jo, jo, jo! Claro, claro."},{"a":"master","t":"El viejo Grimar siempre ha sido un poco... excéntrico."},{"a":"master","t":"Pero cuando yo no era más que un chaval, recuerdo que él era más avispado, incluso un digno contrincante para jugar al ajedrez."},{"a":"master","t":"Desde aquel viaje a las ruinas de Cronos... empezó a comportarse de una manera extraña, ahora que lo pienso."},{"a":"lilu","t":"¡Las ruinas de Cronos! Es un lugar muy peligroso."},{"a":"lilu","t":"Una civilización entera quedó reducida a ruinas mientras investigaba la magia temporal."},{"a":"lilu","t":"Es un lugar lleno de anomalías mágicas. ¿Qué buscaba Grimar en él?"},{"a":"lilu","t":"Tienes razón, Pólux, es nuestra única pista. ¡Habrá que investigar!"},{"a":"lilu","t":"Pero necesitamos que alguien nos escolte... ¿Se lo pedimos a Argon?"},{"a":"lilu","t":"¡No! ¿Y si un vórtice temporal lo transformara de repente en un viejo? O en alguien como Grimar..."},{"a":"lilu","t":"Solo se me ocurre otra persona que podría ayudarnos..."},{"a":"lilu","t":"No va a ser fácil, Pólux, pero tenemos que intentarlo."},{"a":"lilu","t":"¡Gracias, Theodore! Eres de gran ayuda."},{"a":"master","t":"¡De nada, Lilu! ¡Nos vemos pronto!"},{"a":"master","t":"..."},{"a":"master","t":"Anda que no es listo ese búho..."}]},{"id":"lilu_08","i":8,"title":"Causa común","req":"lilu:8","reward":{"k":"gems","id":"gems","q":10,"n":"Joyas"},"side":false,"lines":[{"a":"lilu","t":"Señor Rudo, no se marche, por favor... ¡Tengo que hablar con usted!"},{"a":"rudo","t":"Corta el rollo, niña. No me interesa."},{"a":"rudo","t":"¿Por qué no te vas a jugar con tu búho a otra parte?"},{"a":"lilu","t":"Sé que no te gustan los encantadores, pero necesito tu ayuda."},{"a":"lilu","t":"Tengo que adentrarme en las ruinas de Cronos y no puedo ir sola. "},{"a":"rudo","t":"¿Por qué no le pides ayuda a Argon, tu caballero de brillante armadura?"},{"a":"lilu","t":"Bueno, es que anda liado..."},{"a":"lilu","t":"Supongo que no tenía que haber dicho nada..."},{"a":"rudo","t":"Exactamente, niña."},{"a":"tavern","t":"Qué lástima, cielo..."},{"a":"tavern","t":"Había oído que nadie ha podido derrotar en un solo combate al cíclope de las ruinas de Cronos."},{"a":"tavern","t":"Haría falta un guerrero excepcional que pudiera escoltar a Lilu por esas peligrosas ruinas..."},{"a":"rudo","t":"¿Nadie ha podido derrotarlo?"},{"a":"rudo","t":"Vale, acepto. ¿Cuántos porrazos podré dar?"},{"a":"lilu","t":"¡Seguro que un montón!"},{"a":"lilu","t":"Verás, tengo que encontrar el origen del flujo temporal proveniente de varios cristales y aislar..."},{"a":"rudo","t":"Al grano, niña."},{"a":"lilu","t":"... Sí, hay monstruos y cristales mágicos que podrás aplastar."},{"a":"rudo","t":"Vale, me has convencido. Pero me debes una."},{"a":"lilu","t":"¡Maravilloso! Muchísimas gracias, señor Rudo."},{"a":"rudo","t":"Los agradecimientos para cuando volvamos del viaje, no va a ser un paseo por el parque."},{"a":"lilu","t":"Si los monstruos te dan de lo lindo, estaré ahí para curarte las heridas."},{"a":"rudo","t":"Mmm. Lo dudo..."},{"a":"lilu","t":"¡Gracias a ti también, Naya!"},{"a":"tavern","t":"De nada, cielo."}]},{"id":"lilu_09","i":9,"title":"Mundo Espejo","req":"lilu:9","reward":{"k":"gems","id":"gems","q":10,"n":"Joyas"},"side":false,"lines":[{"a":"rudo","t":"Yo distraeré al cíclope. ¡No te detengas!"},{"a":"rudo","t":"Ven aquí, gordinflón. Tengo un poco de avena para ti."},{"a":"lilu","t":"¡Vale, buena suerte!"},{"a":"lilu","t":"Esta es la Sala del Tiempo... Según mis investigaciones..."},{"a":"lilu","t":"Esta pila está conectada a una línea temporal fragmentada."},{"a":"lilu","t":"Un universo paralelo donde la ciudad de Cronos sigue en pie..."},{"a":"lilu","t":"¡Mira, Pólux! Si observas el agua detenidamente, vas a ver algo muy interesante."},{"a":"lilu","t":"Parece que la gente de Cronos vive de forma normal..."},{"a":"lilu","t":"Oye, ¿no parece que ese tipo nos está saludando?"},{"a":"lilu","t":"Ese no es... ¡¿Grimar?!"}]},{"id":"lilu_10a","i":10,"title":"La maldición de todos los tiempos","req":"lilu:10","reward":{"k":"gems","id":"gems","q":10,"n":"Joyas"},"side":false,"lines":[{"a":"lilu","t":"¡Bébete esto, Grimar!"},{"a":"wizard","t":"¿Eh? Esto me resulta... familiar."},{"a":"lilu","t":"Es una bebida especial elaborada con Agua de Cronos..."},{"a":"wizard","t":"¿Estabilizada y doblemente depurada con los hilos del destino?"},{"a":"lilu","t":"Materializada con ectoplasma destilado..."},{"a":"wizard","t":"Y con un toque de coral intenso para que tenga mejor sabor."},{"a":"wizard","t":"Te felicito, Lilu. Eres el orgullo de cualquier maestro."},{"a":"lilu","t":"Grimar..., ¡ha funcionado! ¡Has vuelto a la normalidad!"},{"a":"wizard","t":"Qué experiencia tan peculiar... Es como si una niebla hubiera disipado mi mente..."},{"a":"lilu","t":"Entiendo más o menos cómo funciona la poción, aunque hay algo que no me encaja."},{"a":"lilu","t":"Te hemos visto en la pila, en la línea temporal fragmentada."},{"a":"wizard","t":"¡Jo, jo! ¿Ah, sí? Tengo una teoría al respecto..."},{"a":"wizard","t":"Pólux, ¿serías tan amable de traer al bueno de Owen? Creo que hay muchas cosas que explicar..."}]},{"id":"lilu_10b","i":11,"title":"Teorema de fisura temporal","req":"lilu:10","reward":{"k":"gems","id":"gems","q":10,"n":"Joyas"},"side":false,"lines":[{"a":"elderowen","t":"Caray, amigo mío. ¡Menuda historieta!"},{"a":"lilu","t":"Sí, a mí también me cuesta creerla... ¿Grimar, un superviviente de Cronos?"},{"a":"wizard","t":"Cuando desapareció el conjuro temporal, la ciudad terminó en una especie de dimensión alternativa."},{"a":"elderowen","t":"Recuerdo aquel día como si fuera ayer. La ciudad entera se esfumó en un abrir y cerrar de ojos."},{"a":"elderowen","t":"Lo único que encontramos entre las ruinas fue a un niño solo y perdido..."},{"a":"lilu","t":"Grimar, ¿verdad? Me pregunto cómo erais de niños..."},{"a":"elderowen","t":"¡Jo, jo! Pues enseguida congeniamos, ¿verdad?"},{"a":"wizard","t":"En efecto. Yo estudié para convertirme en mago e investigar este extraño suceso."},{"a":"wizard","t":"Si lo que vio Lilu es correcto, significa que hay otro Grimar."},{"a":"lilu","t":"Entonces, el otro Grimar que vimos... ¿existe en la otra línea temporal?"},{"a":"wizard","t":"Eso parece. Al principio, parecía que no habría consecuencias, pero..."},{"a":"wizard","t":"Conforme los dos Grimar crecían, nuestras experiencias y personalidades se distanciaron."},{"a":"lilu","t":"Y la paradoja mágica empezó a sobrecargar tu mente..."},{"a":"lilu","t":"¡Ahora lo entiendo! Beber una poción de las ruinas de Cronos te conectará de vuelta a esa línea temporal."},{"a":"wizard","t":"Esa es mi teoría. Seguro que el otro Grimar lo agradecerá."},{"a":"lilu","t":"Uf, cuánta información... Creo que necesito consultarlo con la almohada... ¿Vienes, Pólux?"},{"a":"elderowen","t":"Y nosotros tenemos que ponernos al día, viejo Grim."},{"a":"wizard","t":"Habla por ti, carcamal. ¡Nunca me había sentido tan joven!"}]},{"id":"lilu_epilogue","i":12,"title":"Epílogo","req":"lilu:11","reward":{"k":"gems","id":"gems","q":10,"n":"Joyas"},"side":false,"lines":[{"a":"lilu","t":"¡Hola, Grimar! Aquí tienes una nueva fórmula. Debería durar un poco más."},{"a":"wizard","t":"Una mejora considerable. Tus padres estarían orgullosos de ti."},{"a":"lilu","t":"Ojalá hubiera estudiado alquimia antes..."},{"a":"wizard","t":"Sé cómo te sientes. Si hubiera estado en plenas facultades, a lo mejor..."},{"a":"lilu","t":"No te preocupes. He decidido centrarme en el futuro. Quiero ser mejor y salvar a otras personas de semejante destino."},{"a":"lilu","t":"Seguro que mis padres lo querrían así."},{"a":"wizard","t":"Cuánto has crecido... Ya no te pareces a la niña que eras antes."},{"a":"wizard","t":"A todo esto..., ¿tú quién eres?"},{"a":"lilu","t":"Ay, no. El efecto empieza a disiparse. Será mejor que..."},{"a":"wizard","t":"¡Jo, jo, jo! ¡Estaba de broma! Tengo un buen presentimiento."},{"a":"wizard","t":"Aprovechemos que sigo lúcido... ¿Aprendemos un poco de magia?"},{"a":"wizard","t":"¡Este maestro aún se guarda unos trucos bajo la manga!"},{"a":"lilu","t":"¿Podemos seguir con Polimorfo? ¡Tengo muchas ganas de aprender ese hechizo!"}]}]},{"id":"polonia","name":"Polonia","chapters":[{"id":"polonia_01","i":1,"title":"Marinero de agua dulce excepcional","req":"polonia:1","reward":{"k":"gems","id":"gems","q":10,"n":"Joyas"},"side":false,"lines":[{"a":"polonia","t":"¡Arr, jo, jo, jo! ¡Marineros de agua dulce!"},{"a":"polonia","t":"¿Alguna vez has soñado con navegar por los siete mares en busca de aventuras dignas del mejor de los piratas?"},{"a":"polonia","t":"Yo, la capitana Polonia Del Monte, voy a reclutar una tripulación para mi barco."},{"a":"polonia","t":"Como digna hija del legendario pirata Baross Del Monte, os puedo asegurar que os aguardan grandes botines y aventuras."},{"a":"argon","t":"Capitana Polonia, ¿verdad?"},{"a":"polonia","t":"La misma. ¿Te interesa? Un buen macho como tú siempre es bienvenido."},{"a":"argon","t":"¿Macho?"},{"a":"argon","t":"Esto... ¡no sé si diría tanto! Soy Argon, caballero en prácticas."},{"a":"argon","t":"La piratería es ilegal así que... ríndete y entrégate pacíficamente."},{"a":"polonia","t":"¡Que me parta un rayo! Un condenado caballero..."},{"a":"polonia","t":"Mira, soy una pirata legal, como ese tal... Robin Hood, mequetrefe."},{"a":"polonia","t":"Robo a los ricos para dárselo a los pobres."},{"a":"argon","t":"¡Vaya! Qué noble de tu parte. Está bien, sigue con lo tuyo."},{"a":"polonia","t":"Fiu..."},{"a":"tavern","t":"¿Hoy tampoco ha habido suerte?"},{"a":"polonia","t":"Arr, la vida en alta mar es dura."}]},{"id":"polonia_02","i":2,"title":"La historia de Del Monte","req":"polonia:2","reward":{"k":"gems","id":"gems","q":10,"n":"Joyas"},"side":false,"lines":[{"a":"tavern","t":"¿No contratas a nadie más hoy, Polonia?"},{"a":"polonia","t":"No merece la pena. Soy un percebe como capitana pirata, y mejor ni hablar de honrar el apellido Del Monte..."},{"a":"tavern","t":"Ese tal Baross Del Monte era tu abuelo, ¿no?"},{"a":"polonia","t":"Así es, una leyenda entre las leyendas. Estos tiempos modernos no son fáciles para los piratas..."},{"a":"polonia","t":"Hoy en día todos los barcos mercantes están equipados con esas herramientas de detección mágicas con las que evitar a los lobos de mar como nosotros."},{"a":"polonia","t":"¡Pero a Baross no lo detectaban! Con magia o sin ella, era capaz de aparecer de entre la niebla sin que nadie lo detectara."},{"a":"polonia","t":"Desvalijaba los barcos en un abrir y cerrar de ojos, dejando atrás el eco de su carcajada como única tarjeta de visita..."},{"a":"polonia","t":"Incluso después de que los demás piratas se retiraran, su nombre continuó siendo el terror de los mares durante décadas."},{"a":"tavern","t":"¡No es fácil estar a la altura de semejante legado!"},{"a":"polonia","t":"¡Arr! Y después de cada viaje, siempre sacaba tiempo para visitar a su nieta y regalarle historias de aventuras..."},{"a":"polonia","t":"«¡Izad la bandera pirata! ¡Disparad los cañones! Toda la tripulación a estribo, ¡lista para saquear!»."},{"a":"tavern","t":"¿Estribo? ¿No se dice estribor?"},{"a":"polonia","t":"¡Que me aspen! ¡Qué importa! No soy más que una marinera de agua dulce con un traje bonito, y que se esfuerza demasiado por hablar como un pirata."},{"a":"polonia","t":"A fin de cuentas... ¡¿Qué es un pirata sin un barco?!"},{"a":"tavern","t":"Sin barco, ¿eh? Deberías haber empezado por ahí."},{"a":"polonia","t":"¿Eh?"},{"a":"tavern","t":"Un capitán sin barco no puede reunir a una tripulación."},{"a":"tavern","t":"Pero si lo que necesitas es un barco, creo que conozco a la persona indicada."},{"a":"polonia","t":"¿En serio?"},{"a":"polonia","t":"Quiero decir... ¡Por la barbas de Neptuno, gracias! La capitana Polonia te debe una."},{"a":"tavern","t":"Créeme, querida, cuento con ello."}]},{"id":"polonia_03","i":3,"title":"Carpintería de navíos a toda vela","req":"polonia:3","reward":{"k":"gems","id":"gems","q":10,"n":"Joyas"},"side":false,"lines":[{"a":"carpenter","t":"¿Quieres que construya un barco entero?"},{"a":"polonia","t":"¡Arr! ¿Puedes hacerlo?"},{"a":"carpenter","t":"¡Pues claro! Será mi obra maestra. Déjame ver los planos."},{"a":"carpenter","t":"Vaya... son bastante complejos. ¿Qué son estos garabatos?"},{"a":"polonia","t":"Mi letra. No sé leer."},{"a":"carpenter","t":"Ah, eso aclara unas cuantas cosas. De todas formas, son más que suficientes."},{"a":"polonia","t":"¡Jo, jo, jo! Será el barco más temible de los siete mares después de Baross y el Bonaventura."},{"a":"carpenter","t":"Pero hay que hablar de la financiación. ¿Estás segura de que puedes permitírtelo?"},{"a":"polonia","t":"¡Arr! Los doblones no serán un problema. Construye el barco, que ya te traeré tu botín."}]},{"id":"polonia_a","i":3,"title":"Un paso adelante","req":"polonia:3","reward":{"k":"tokens","id":"tokens","q":3,"n":"Fichas de la fortuna"},"side":true,"lines":[{"a":"polonia","t":"Ah del barco, hermosa dama. ¿Eres curandera, verdad?"},{"a":"priest","t":"¡Ah, sí! Soy Freyja, la sacerdotisa de este tem..."},{"a":"polonia","t":"Córtame una pierna."},{"a":"priest","t":"¿Qué?"},{"a":"polonia","t":"¡Te digo que me cortes una pierna!"},{"a":"priest","t":"¡Madre del amor hermoso, no! ¿Por qué razón pediría alguien algo semejante?"},{"a":"polonia","t":"¡Para ser una pirata, caray! ¿Qué clase de capitana pirata andaría por ahí sin una pata de palo?"},{"a":"polonia","t":"Córtame la pierna y me la coses con esa magia tuya."},{"a":"priest","t":"Ni lo sueñes. Juré a la Diosa que nunca haría daño a un ser humano."},{"a":"polonia","t":"¡Que me aspen! Estos marineros de agua dulce no sirven para nada... ¡No esperes ni uno solo de mis doblones!"},{"a":"priest","t":"Qué chica tan rara..."}]},{"id":"polonia_04","i":4,"title":"La parte de la capitana","req":"polonia:4","reward":{"k":"gems","id":"gems","q":10,"n":"Joyas"},"side":false,"lines":[{"a":"polonia","t":"¡Caray! Estos yetis están cargados de botines. Así me pagaré el barco enseguida."},{"a":"leather","t":"Vale, colega. Aquí estoy. ¿Qué tengo que hacer?"},{"a":"polonia","t":"¡La capitana Polonia para ti, filibustero!"},{"a":"leather","t":"Claro, capitana colega. ¿Qué quieres que haga?"},{"a":"polonia","t":"Trae tu carreta. Llevarás el botín mientras desvalijo a estos yetis."},{"a":"leather","t":"Hala, capitana colega, ¿robas a estas bonitas criaturas peludas?"},{"a":"polonia","t":"Arr. Por alguna razón llevan montones de objetos valiosos, como martillos de guerra y arcos compuestos."},{"a":"leather","t":"¿Y las pieles, capitana colega? ¿Me las puedo quedar?"},{"a":"polonia","t":"¡Has de saber cuál es tu lugar, marinero! Los piratas saquean, pero no matan."},{"a":"leather","t":"Vaya, qué desperdicio."},{"a":"polonia","t":"¡Ojo al parche! Si dejas vivas a tus víctimas, reunirán más botín que podrás saquear más tarde. Es economía básica."},{"a":"polonia","t":"Tendrás que estar a la altura si quieres tu parte, mi valiente."},{"a":"leather","t":"Arr, arr, capitana colega."}]},{"id":"polonia_05","i":5,"title":"El viaje de la doncella","req":"polonia:5","reward":{"k":"gems","id":"gems","q":10,"n":"Joyas"},"side":false,"lines":[{"a":"carpenter","t":"¡He aquí mi obra maestra, el mejor trabajo de mi vida!"},{"a":"polonia","t":"Es... es bonito. Se me cae una lagrimita, grumete."},{"a":"carpenter","t":"¿A que sí? He tenido que quitar algunas cosas, más concretamente, los cañones de encima de la cofa..."},{"a":"carpenter","t":"Pero creo que ha quedado requetebién, ¿no te parece?"},{"a":"polonia","t":"Sin duda, grumete. Aquí está tu doblón, te lo has ganado."},{"a":"carpenter","t":"De eso no cabe duda. Una cosa más. Soy un experto carpintero, pero los tejidos y las telas no son lo mío."},{"a":"carpenter","t":"Y, sin una vela, no creo que tu barco pueda zarpar."},{"a":"polonia","t":"No te preocupes; tu capitana está más que orgullosa, grumete. Además, tengo una aquí mismo."},{"a":"carpenter","t":"¡Hala! Es una auténtica obra de arte. ¡Y mágica! ¿De dónde la has sacado?"},{"a":"polonia","t":"Lo heredé de mi abuelito Baross. La misma vela que ondeaba en el barco suyo: el Bonaventura."},{"a":"carpenter","t":"¡Vaya! Es el remate perfecto para esta nave."},{"a":"carpenter","t":"Entonces, capitana Polonia, el Apuesto Allan es todo tuyo."},{"a":"polonia","t":"¿Lo has llamado Apuesto Allan? Espera..."},{"a":"polonia","t":"El mascarón de proa... ¿¡eres tú!? ¡Y con el culo al aire!"},{"a":"carpenter","t":"¡Ja, ja! No se me ocurre un mascarón mejor para un barco tan perfecto."}]},{"id":"polonia_b","i":5,"title":"Salir por patas","req":"polonia:5","reward":{"k":"tokens","id":"tokens","q":3,"n":"Fichas de la fortuna"},"side":true,"lines":[{"a":"polonia","t":"¡Arr! Buenas."},{"a":"wood","t":"¿Sí?"},{"a":"polonia","t":"Córtame una pierna."},{"a":"wood","t":"Claro."},{"a":"polonia","t":"He dicho que... Espera, ¿estás de acuerdo?"},{"a":"wood","t":"Sí, no te preocupes. Sujeta la pierna así. Esta vieja hacha debería servir."},{"a":"polonia","t":"Eh... ¡Espera!"},{"a":"wood","t":"No va a ser agradable, pero eres una chica valiente, ¿verdad?"},{"a":"wood","t":"Pero ponte un buen torniquete. No te me vayas a desangrar ahora."},{"a":"polonia","t":"¡Alto, grumete! ¡No tan rápido!"},{"a":"polonia","t":"El barco mío zarpa pronto. Tengo... tengo que alcanzarlo. ¡Nos vemos, camarada!"},{"a":"wood","t":"¡Ja! Humanos. Nunca se aburre uno con ellos."}]},{"id":"polonia_06","i":6,"title":"Patrimonio en el mar","req":"polonia:6","reward":{"k":"gems","id":"gems","q":10,"n":"Joyas"},"side":false,"lines":[{"a":"sia","t":"Mi rey, traigo malas noticias."},{"a":"king","t":"¡Oh, no! No me digas que la Ciudad de Oro perdida se ha quedado sin oro..."},{"a":"sia","t":"No tan malas, afortunadamente."},{"a":"sia","t":"Sin embargo, me temo que una pirata entrometida se ha dedicado a saquear tu flota comercial."},{"a":"sia","t":"Se calcula que el valor del robo supera los 100 billones de oro."},{"a":"king","t":"¡Válgame la Diosa! ¿Qué ha pasado entonces con mi detector mágico de piratas de última generación?"},{"a":"sia","t":"Parece que es completamente ineficaz. Este barco, al igual que Baross, parece eludir hasta la mejor de nuestras magias..."},{"a":"sia","t":"... y saquea el oro antes de esfumarse en el mar."},{"a":"king","t":"¡Qué barbarie! ¿Y la tripulación?"},{"a":"sia","t":"Les perdonan la vida, mi rey, siempre que no opongan resistencia."},{"a":"king","t":"Entonces, el oro no es más que un pequeño precio a pagar. Comeré como los plebeyos hasta que recupere mi fortuna."},{"a":"king","t":"¿Cuánto tiempo llevará?..."},{"a":"sia","t":"Unos dos días, mi rey."},{"a":"king","t":"Definitivamente, son tiempos duros..."}]},{"id":"polonia_07","i":7,"title":"Permiso para bajar a tierra","req":"polonia:7","reward":{"k":"gems","id":"gems","q":10,"n":"Joyas"},"side":false,"lines":[{"a":"polonia","t":"¡Jo, jo, jo! La capitana Polonia pisa tierra. ¡Las rondas corren de mi cuenta!"},{"a":"tavern","t":"¡Polonia! ¿O debería decir... capitana Polonia? Parece que te va muy bien el «negocio»."},{"a":"polonia","t":"¡Que no te quepa duda, marinerito de agua dulce! Los mares están cargados de fortunas."},{"a":"polonia","t":"Allá donde vaya, las velas de mi abuelo captan el viento como no había visto nunca."},{"a":"tavern","t":"Seguro que Baross estaría orgulloso. ¿Y cómo piensas gastarte estas... riquezas ilícitas?"},{"a":"polonia","t":"Como lo haría cualquier pirata que se precie: escondiéndolas por aquí y por allá."},{"a":"tavern","t":"¡Ooh! ¡Mapas del tesoro! ¡Qué emocionante!"},{"a":"polonia","t":"Arrr, así somos los piratas. Hay que guardar algo para el invierno, como hacen las ardillas."},{"a":"tavern","t":"¿Y el resto?"},{"a":"polonia","t":"Se lo di a la hermosa dama del templo."},{"a":"tavern","t":"¿Una donación para el orfanato? No sabía que fueras tan solidaria."},{"a":"polonia","t":"Orfa... ¿Que qué?"},{"a":"tavern","t":"Olvídalo. ¿Qué te pongo, capitana?"},{"a":"polonia","t":"Mi favorita, ¡la birra de los lobos de mar! Y lo mismo para los grumetes que puedan con ella..."},{"a":"polonia","t":"¡La próxima ronda corre de mi cuenta! La familia Baross vuelve a dominar los mares, ¡jo, jo, jo, jo!"}]},{"id":"polonia_08","i":8,"title":"Susurros del pasado","req":"polonia:8","reward":{"k":"gems","id":"gems","q":10,"n":"Joyas"},"side":false,"lines":[{"a":"polonia","t":"¿Listo para la siguiente inmesión, tritón?"},{"a":"baker","t":"¡Cuando quieras, capitana! Aunque debo decir que..."},{"a":"baker","t":"Aunque me encanta ayudarte con la exploración submarina, no acepté dedicarme a la piratería."},{"a":"polonia","t":"No le des muchas vueltas, grumete. Nuestra misión es de cartografía. Tu capitana está ampliando su territorio."},{"a":"polonia","t":"Hoy, nada de actos de piratería. Pero, si hay suerte, ¡podríamos encontrar un barco hundido para saquear! ¡Jo, jo, jo!"},{"a":"baker","t":"Eh, ¿capitana? ¿Qué es ese barco que asoma en el horizonte?"},{"a":"polonia","t":"Arr. Relaja las aletas, tritón. Es el Bonaventura, el barco de mi abuelo."},{"a":"baker","t":"¿Estás segura? Parece bastante destrozado..."},{"a":"polonia","t":"¡Por las barbas de Neptuno! ¡El maldito Bonaventura! ¡Pe-pero es imposible! ¡Hace mucho que murió mi abuelo!"},{"a":"polonia","t":"¡Marineros, cambio de planes! ¡VAMOS A SEGUIR A ESE BARCO!"}]},{"id":"polonia_09","i":9,"title":"Una leyenda a la deriva","req":"polonia:9","reward":{"k":"gems","id":"gems","q":10,"n":"Joyas"},"side":false,"lines":[{"a":"baker","t":"... Nunca pensé que abordaría un barco abandonado."},{"a":"polonia","t":"Cuidado dónde pisas, tritón. El barco no está en buenas condiciones."},{"a":"baker","t":"A decir verdad, preferiría darme un baño. ¿Qué estamos haciendo en este navío?"},{"a":"polonia","t":"¿Qué quieres decir con eso? ¡Este es el Bonaventura de Baross!"},{"a":"polonia","t":"Tengo que descubrir qué pasó aquí... Este barco abandonado no debería estar navegando."},{"a":"baker","t":"... Es más bien un barco fantasma."},{"a":"polonia","t":"¡Aj, no me asustes! Los fantasmas no existen."},{"a":"baker","t":"¿Y qué hay de Zo...?"},{"a":"polonia","t":"Cierra esa bocaza, grumete. Estoy buscando pistas."},{"a":"baker","t":"Ese diario de ahí parece un poco siniestro..."},{"a":"polonia","t":"¡Arr, la bitácora del capitán!"},{"a":"baker","t":"Da la impresión de que te mira..., ¿verdad?"},{"a":"polonia","t":"Tú te vienes conmigo, bitácora. Mantén los ojos de pirata bien abiertos por si hay algo más."},{"a":"polonia","t":"... Grumete, ¿podrías dejar de toquetearme el pelo?"},{"a":"baker","t":"Capitana, estoy aquí."},{"a":"polonia","t":"¡¡¡AAAAAARGH!!! ¡Abandonad el barco!"}]},{"id":"polonia_10","i":10,"title":"Herencia pirata","req":"polonia:10","reward":{"k":"gems","id":"gems","q":10,"n":"Joyas"},"side":false,"lines":[{"a":"polonia","t":"Vuestra capitana ha vuelto al barco, tripulantes. Izad las velas, que nos vamos."},{"a":"baker","t":"¡Capitana, mira! ¡El Bonaventura se hunde!"},{"a":"polonia","t":"¡Por todos los percebes! ¿Cómo es posible? ¿¡Después de tanto tiempo!? ¿Sería la bitácora lo que lo mantenía a flote?"},{"a":"baker","t":"... Tal vez haya cumplido su propósito."},{"a":"polonia","t":"Baross, lobo marino... ¿cómo supiste que...?"},{"a":"baker","t":"Polonia, ¿qué hay de la bitácora?"},{"a":"polonia","t":"Es verdad, vamos a ver..."},{"a":"polonia","t":"..............."},{"a":"polonia","t":"Tengo que pedirte otro favor, tritón."},{"a":"baker","t":"Ah, sí; te lo leo."},{"a":"baker","t":"Mmm... Parecen instrucciones para encontrar un lugar submarino."},{"a":"polonia","t":"¿Un templo hundido? Eso no sería ninguna novedad."},{"a":"baker","t":"No, parece que está muy lejos de aquí... Dice algo de la Ciudad de Oro perdida."},{"a":"baker","t":"Pero la Ciudad de Oro perdida no está bajo el agua..."},{"a":"polonia","t":"¿Di-dices que no era una leyenda? ¿Ese sitio existe?"},{"a":"polonia","t":"Tritón, tú puedes nadar. Esto es cosa del destino."},{"a":"polonia","t":"Si las historias son ciertas, no lamentarás llevarme hasta allí."}]},{"id":"polonia_11","i":11,"title":"La Ciudad de Oro hundida","req":"polonia:11","reward":{"k":"gems","id":"gems","q":10,"n":"Joyas"},"side":false,"lines":[{"a":"baker","t":"¡Bien, hemos llegado! ¿Cómo lo llevas, capitana?"},{"a":"polonia","t":"Cof, cof, aj..."},{"a":"polonia","t":"Caray... sí que tienes... piernas fuertes... para ser un tritón..."},{"a":"baker","t":"¡Y menos mal! Esta entrada está a tanta profundidad que no creo que ningún ser humano pudiera llegar."},{"a":"polonia","t":"¡Tienes razón! Casi me ahogo. No pienso volver aquí..."},{"a":"baker","t":"¡Válgame la Diosa! ¡Polonia, mira alrededor!"},{"a":"polonia","t":"Por las barbas de Neptuno... la Ciudad de Oro hundida..."},{"a":"polonia","t":"Este lugar... Nunca había visto algo igual."},{"a":"baker","t":"¡No caben más riquezas! Hay oro, perlas... ¡Comparada con esto, la Ciudad de Oro perdida es austera!"},{"a":"polonia","t":"Mi abuelo se pasó la vida buscando este lugar..."},{"a":"baker","t":"Al final, no pudo llevar nada a tierra firme, así que se lo dejó todo a su nieta preferida."},{"a":"polonia","t":"Snif... Se me saltan las lágrimas..."},{"a":"baker","t":"¿Quieres que te deje sola un momento, capitana?"},{"a":"polonia","t":"¿Me tomas el pelo? ¡Tenemos mucho que saquear! Y te acabo de ascender a contramaestre. ¿Estás listo para nadar un buen rato?"},{"a":"baker","t":"¿Tengo que llevar bolsas de botín Y a una pirata? ¡Tendré que hacer estiramientos!"}]},{"id":"polonia_epilogue","i":12,"title":"Epílogo","req":"polonia:11","reward":{"k":"gems","id":"gems","q":10,"n":"Joyas"},"side":false,"lines":[{"a":"polonia","t":"Mmm..."},{"a":"baker","t":"¿Nos estamos preparando para nadar otra vez, Polonia?"},{"a":"polonia","t":"Qué va, grumete. Tengo un problema gordo."},{"a":"polonia","t":"¡Tengo demasiado dinero! Ya casi no me quedan playas para enterrarlo todo."},{"a":"baker","t":"Debo decir que mi parte me abruma un poco."},{"a":"baker","t":"¡Oh, eso me recuerda una cosa!"},{"a":"baker","t":"Antes estuve nadando alrededor del Bonaventura hundido..."},{"a":"baker","t":"No había gran cosa, excepto este parche. ¿Lo reconoces?"},{"a":"polonia","t":"¡Contramaestre! ¡Es el parche de Baross!"},{"a":"polonia","t":"¡Jo, jo, jo! ¡Estoy tan feliz, que podría darte un beso!"},{"a":"baker","t":"El placer es todo mío, capitana. Seguro que él hubiera querido que lo tuvieras tú."},{"a":"polonia","t":"¿Sabes qué? Se acabó el asunto de los saqueos submarinos."},{"a":"polonia","t":"¡El hogar de un pirata es el mar, no una ciudad de oro! Por mucho botín que tenga."},{"a":"polonia","t":"Como nieta del gran Baross, te regalo la Ciudad de Oro hundida y el resto del botín."},{"a":"polonia","t":"Gracias por tus servicios, contramaestre. Si alguna vez cambias de opinión sobre la piratería, puedes unirte a nosotros."},{"a":"baker","t":"Gracias, capitana. ¡Nunca olvidaré nuestras aventuras juntos!"},{"a":"baker","t":"Cuando llegue a casa, tendré que volver a hablar con Tutu Mano sobre esas vacaciones..."}]}]},{"id":"king","name":"Reinhold","chapters":[{"id":"king_farewell","i":0,"title":null,"req":null,"reward":null,"side":false,"lines":[{"a":"sia","t":"Rey Reinhold"},{"a":"king","t":"Ah, parece que las obligaciones me han encontrado."},{"a":"sia","t":"Y menudo montón... En fin, los dignatarios están esperando."},{"a":"king","t":"¡Hasta la vista, comerciante! ¡Volveré!"},{"a":"sia","t":"No, creo que no."}]},{"id":"king_01","i":1,"title":"La corte del rey","req":"king:1","reward":{"k":"tokens","id":"tokens","q":5,"n":"Fichas de la fortuna"},"side":false,"lines":[{"a":"king","t":"Se ha abierto la corte del rey. ¡Que los demandantes den un paso al frente!"},{"a":"rudo","t":"Pff."},{"a":"king","t":"¿Qué puede hacer el reino de Reinhold por sus súbditos? A ver, hombre... oso gigantesco."},{"a":"rudo","t":"Creo que se debería prohibir la magia y expulsar del reino a los encantadores."},{"a":"king","t":"Ah... Pues eso... Eh..."},{"a":"king","t":"Tendremos en cuenta la propuesta. ¡Siguiente!"},{"a":"herbs","t":"¡Holii! ¡Creo que todos los días deberían ser el Día de las Piñatas!"},{"a":"king","t":"¡Qué idea tan fantástica! De hecho, creo que..."},{"a":"sia","t":"..."},{"a":"king","t":"... estamos perdiendo el tiempo debatiendo este asunto. ¡Gracias por venir!"},{"a":"king","t":"Sia, ¿cuántos demandantes quedan por hoy?"},{"a":"sia","t":"Cincuenta y cinco, mi rey."},{"a":"king","t":"Madre mía..."}]},{"id":"king_02","i":2,"title":"Bobalicón con corazón de oro","req":"king:2","reward":{"k":"tokens","id":"tokens","q":5,"n":"Fichas de la fortuna"},"side":false,"lines":[{"a":"donovan","t":"Perdona, ¿está ocupado este asiento?"},{"a":"sia","t":"¿Vienes a amargarme el día, Donovan?"},{"a":"donovan","t":"Me ofendes, Sia. Solo quiero hablar con otra ciudadana del impero."},{"a":"donovan","t":"¿Cómo le va al bobalicón de nuestro rey?"},{"a":"sia","t":"Estás perdiendo facultades como espía, Donovan. Reinhold no es en absoluto el insensato que te crees."},{"a":"sia","t":"Aunque sonría, también sacrifica mucho por su gente."},{"a":"sia","t":"Algo de que lo podría aprender el emperador... Nuestro emperador."},{"a":"sia","t":"Hasta ahora, mi cometido ha sido impedir que caiga en la ruina por su pueblo."},{"a":"donovan","t":"Ah, ¿sí? Qué interesante..."},{"a":"sia","t":"Puede que sea un bobalicón con un corazón de oro, pero no harías bien en subestimarlo."}]},{"id":"king_03","i":3,"title":"Trasnoche real","req":"king:3","reward":{"k":"tokens","id":"tokens","q":5,"n":"Fichas de la fortuna"},"side":false,"lines":[{"a":"king","t":"¡Buff! ¿Cuándo va a bajar esta montaña de informes?"},{"a":"sia","t":"Parece que tendremos que prepararnos para otra noche en vela..."},{"a":"king","t":"Gracias por ayudarme con esto, mi querida Sia."},{"a":"sia","t":"No hay nada que agradecer, mi rey. Venga, a por el siguiente informe..."},{"a":"sia","t":"Los agricultores de Surburgo no han pagado sus impuestos porque dicen que han tenido malas cosechas."},{"a":"sia","t":"Esta es la segunda vez que ocurre..."},{"a":"king","t":"Envía a unos magos de la corte para que lo investiguen. Puede que sus tierras estén malditas."},{"a":"sia","t":"Una solución muy generosa."},{"a":"king","t":"Y vuelve a perdonarles los impuestos; es lo que habría querido mi padre."},{"a":"sia","t":"De acuerdo. Yo también creo que el rey Keinan habría tomado la misma decisión."},{"a":"king","t":"La corona que he heredado es ciertamente pesada..."},{"a":"king","t":"¿Qué dice el siguiente informe?"},{"a":"sia","t":"Es sobre tensiones fronterizas con el imperio vecino..."}]},{"id":"king_04","i":4,"title":"Sombras que asustan","req":"king:4","reward":{"k":"tokens","id":"tokens","q":5,"n":"Fichas de la fortuna"},"side":false,"lines":[{"a":"king","t":"..."},{"a":"sia","t":"Mi rey..."},{"a":"king","t":"¡Ahh!"},{"a":"king","t":"¡A-anuncia tu presencia! ¡Menudo susto me has dado!"},{"a":"sia","t":"Ah, veo que el ataque de aquella ninja os ha dejado huella, ¿no?"},{"a":"king","t":"¡Por supuesto! ¡Estuve al borde de la muerte!"},{"a":"sia","t":"¿Puedo duplicar el número de guardias?"},{"a":"king","t":"No es... necesario, pero ¡no seas tan silenciosa en el futuro!"},{"a":"sia","t":"Entendido, mi rey."},{"a":"hemma","t":"Ah, me encanta volver a casa... ¿Eh?"},{"a":"king","t":"¡Aaah! ¡¿N-ninjas?!"},{"a":"hemma","t":"Disculpa, creo que nos hemos equivocado."},{"a":"hemma","t":"A veces la translocación sombría no es del todo precisa..."},{"a":"king","t":"¡O-oye, nada de teletransporte sombrío en la sala del trono!"},{"a":"sia","t":"Rey Reinhold, ¿va todo bien?"},{"a":"king","t":"¡Sí! Por favor, acompaña a la salida a... esta abominable visita."},{"a":"sia","t":"Por supuesto. Me aseguraré de que el castillo esté protegido frente a este tipo de intrusiones."},{"a":"hemma","t":"Esta parada ha sido de lo más interesante. Ya volveremos."},{"a":"king","t":"¡Pues espero que no!"}]}]},{"id":"rudo","name":"Rudo","chapters":[{"id":"rudo_01","i":1,"title":"La montaña viviente","req":"rudo:1","reward":{"k":"gems","id":"gems","q":10,"n":"Joyas"},"side":false,"lines":[{"a":"argon","t":"Brr... ¡No voy abrigado para este frío! ¿Qué estamos haciendo aquí?"},{"a":"lilu","t":"Las gemas de aquí tienen unas propiedades increíbles. Grimar me dijo..."},{"a":"argon","t":"¡Mira, Lilu! ¡Ahí hay un hombre enfrentándose a un yeti!"},{"a":"lilu","t":"¡¿Un hombre?! ¡Parece una montaña de grande!"},{"a":"lilu","t":"¡¿Y ha... derribado al yeti?!"},{"a":"rudo","t":"¡Fiu! Ya van diez."},{"a":"argon","t":"¡Menudo combate! ¡Ha estado increíble!"},{"a":"rudo","t":"¿Eh?"},{"a":"lilu","t":"Oiga, está herido, ¡deje que lo cure!"},{"a":"lilu","t":"¡<c1>Cura</c1>...!"},{"a":"rudo","t":"¡ATRÁS!"},{"a":"rudo","t":"Estoy bien; ya se me curará."},{"a":"rudo","t":"Este no es sitio para unos niños; volved a casa."},{"a":"argon","t":"Hala, ese tío odia la magia, ¿eh?"},{"a":"lilu","t":"No, lo que he visto en sus ojos... era miedo."}]},{"id":"rudo_02","i":2,"title":"Aviso de desahucio","req":"rudo:2","reward":{"k":"gems","id":"gems","q":10,"n":"Joyas"},"side":false,"lines":[{"a":"elderowen","t":"Me temo que me he perdido..."},{"a":"rudo","t":"¡Bah! Lo simplificaré un poco para que te entre en la mollera."},{"a":"rudo","t":"El mago de esta ciudad está como una cabra y debería ser expulsado por el bien de todos."},{"a":"elderowen","t":"Hala... Qué palabras tan duras..."},{"a":"rudo","t":"Ayer me dijo que vigilara a Timotheus..."},{"a":"rudo","t":"Afirmaba que «Tim» delira y que está confundido, y que debería estar bajo supervisión."},{"a":"rudo","t":"¡Timotheus es él!"},{"a":"elderowen","t":"Mmm, vaya, ya entiendo."},{"a":"elderowen","t":"A pesar de su «condición», Timotheus Grimar es un pilar fundamental de la ciudad."},{"a":"elderowen","t":"No ayuda mucho, pero tampoco es peligroso. No veo razón para preocuparse."},{"a":"lilu","t":"¿Qué es esa historia de expulsar al maestro Grimar?"},{"a":"rudo","t":"No te metas en esto, jovencita."},{"a":"lilu","t":"¡No! El maestro Grimar es un mago poderoso, pero nunca haría daño a nadie."},{"a":"rudo","t":"¡Pff! Muy bien. Si la ciudad salta por los aires, no me digáis que no os lo advertí."},{"a":"elderowen","t":"Parece que anda buscando problemas."},{"a":"lilu","t":"Será mejor que lo vigile de cerca..."}]},{"id":"rudo_03","i":3,"title":"Chispa originaria","req":"rudo:3","reward":{"k":"gems","id":"gems","q":10,"n":"Joyas"},"side":false,"lines":[{"a":"priest","t":"Disculpa, ¿por qué andas refunfuñando?"},{"a":"rudo","t":"Maldita sea... ¿Por qué hay tantos malditos encantadores en esta ciudad?"},{"a":"priest","t":"Ah, el Sr. Rudo, supongo."},{"a":"rudo","t":"No me vengas con galanterías, maga."},{"a":"priest","t":"Soy una sacerdotisa de la Diosa. Mis poderes son distintos a los de una maga."},{"a":"priest","t":"Juré dedicar mi vida a la sanación y la protección."},{"a":"rudo","t":"No me lo creo. Los que nacéis con la chispa sois todos iguales."},{"a":"priest","t":"¿Has oído hablar de la chispa...?"},{"a":"rudo","t":"Mmm, olvídalo. Me largo de aquí."},{"a":"priest","t":"¿Lo has oído, Lilu?"},{"a":"lilu","t":"Sí, todo."},{"a":"priest","t":"¿Recuerdas mis clases sobre la chispa?"},{"a":"lilu","t":"¡Claro! Solo los que nacen con la chispa pueden controlar y crear hechizos."},{"a":"lilu","t":"Pero es algo desconocido para el público en general."},{"a":"priest","t":"Así es. No esperaría menos de mi mejor estudiante."},{"a":"priest","t":"Cabe preguntarse cómo lo ha sabido él."},{"a":"lilu","t":"Mmm... ¿Crees que...?"}]},{"id":"rudo_04","i":4,"title":"Robo relámpago","req":"rudo:4","reward":{"k":"gems","id":"gems","q":10,"n":"Joyas"},"side":false,"lines":[{"a":"polonia","t":"¡Jo, jo, jo! La capitana Polonia ha llegado lejos esta vez."},{"a":"polonia","t":"¡Una tumba real enterita lista para que la saqueen!"},{"a":"rudo","t":"Cálmate, marinera. Estoy ocupado."},{"a":"polonia","t":"Si no fuera porque hay un fanático lleno de percebes... ¡¡¡destrozando todo el botín!!!"},{"a":"polonia","t":"Por las barbas de Davy Jones, ¿qué recórcholis te pasa, grumete? Ese material vale un montón de doblones."},{"a":"rudo","t":"Es antiguo."},{"a":"rudo","t":"Es mágico."},{"a":"rudo","t":"Y, probablemente, esté maldito."},{"a":"rudo","t":"Lo estoy haciendo añicos para ahorrarle la molestia a otro."},{"a":"rudo","t":"Si esta ciudad está demasiado ciega para ver el problema, ¡yo me ocuparé de él!"},{"a":"polonia","t":"Uy, grumete, todo eso tiene pinta de valer un montón. No estarás pensando..."},{"a":"rudo","t":"Pff."},{"a":"rudo","t":"Ay..."},{"a":"polonia","t":"¡Por el kraken! ¡No te pongas a partirlo con las rodillas!"},{"a":"polonia","t":"Aunque parece que el golpe te lo has llevado tú, porque el bastón no tiene ni un rasguño."},{"a":"polonia","t":"¿Qué tal la pierna, grumete?"},{"a":"rudo","t":"Bien, pero este bastón es más duro de lo que parece."},{"a":"rudo","t":"Y, por alguna razón, parece que no puedo soltarlo. Es como si se me hubiera pegado a la mano."},{"a":"polonia","t":"Mira, no soy la cirujana del barco, pero me atrevería a decir que te ha caído una buena maldición, grumete."},{"a":"polonia","t":"Va a ser mejor que te lo miren."},{"a":"rudo","t":"Claro que es una maldición mágica; ¡siempre es lo mismo!"},{"a":"rudo","t":"Pues vale, me largo de aquí. Romped el resto por mí."},{"a":"polonia","t":"¡Arr, arr, grumete!"},{"a":"polonia","t":"... Mejor me dedico a saquear, ¡como buena pirata!"}]},{"id":"rudo_a","i":4,"title":"Amor difícil","req":"rudo:3","reward":{"k":"tokens","id":"tokens","q":3,"n":"Fichas de la fortuna"},"side":true,"lines":[{"a":"herbs","t":"¡Gorza!"},{"a":"gems","t":"¡Gorza!<sprite tint=1 name=Note2>"},{"a":"wood","t":"¡Hola, Juniper! ¡Y Malee! ¿Qué tal?"},{"a":"herbs","t":"Maylee y yo estábamos hablando sobre su futuro príncipe azul..."},{"a":"gems","t":"¡Uyyy, estoy impaciente!"},{"a":"herbs","t":"Y nos preguntábamos... ¿cómo conociste tú al tuyo?"},{"a":"wood","t":"¿Ese pedazo de zoquete de Rudo? ¡Ja!"},{"a":"wood","t":"Puede que no lo aparente, pero ese hombre sabe cómo tratar a una dama."},{"a":"wood","t":"Veamos... Pues resulta que..."},{"a":"rudo","t":"Y otra para el camino."},{"a":"tavern","t":"Esto..., Rudo, ¿alguna ve has pensado en sentar la cabeza?"},{"a":"rudo","t":"Ocúpate de tus asuntos, Naya. No tengo tiempo para esas tonterías."},{"a":"tavern","t":"¡El amor aparece cuando menos te lo esperas! Nunca se sabe, la mujer de tus sueños podría entrar por esa puerta en cualquier momento..."},{"a":"rudo","t":"¡Bah! No sentaría la cabeza con una mujer incapaz de luchar conmigo en el suelo."},{"a":"wood","t":"¿Eso es un reto, grandullón?"},{"a":"rudo","t":"¡Ponme a prueba, carapalo!"},{"a":"tavern","t":"Gorza, deja la silla, por favor."},{"a":"wood","t":"¿Qué tal esto, cabeza hueca? ¿Quieres más?"},{"a":"rudo","t":"¡¡¡Aaah!!!"},{"a":"wood","t":"¡Vaya!"},{"a":"wood","t":"... Y nos casamos a la semana siguiente; la boda más sangrienta que he visto nunca."},{"a":"herbs","t":"..."},{"a":"gems","t":"..."},{"a":"herbs","t":"A lo mejor deberíamos preguntar a otra persona."}]},{"id":"rudo_05","i":5,"title":"Maldiciones y estallidos","req":"rudo:5","reward":{"k":"gems","id":"gems","q":10,"n":"Joyas"},"side":false,"lines":[{"a":"rudo","t":"¡¿Cómo que no puedes romperla?!"},{"a":"master","t":"Pues lo que te he dicho, mi violento amigo: esta reliquia no se puede romper."},{"a":"rudo","t":"¿Para qué tengo un martillo de adamantino si no puedo romper esta birria de bastón?"},{"a":"master","t":"Pues a mí no me parece que sea una birria... ¡Tiene un aspecto bastante malvado!"},{"a":"master","t":"En ese caso, aquí hay alguna cosa más. Seguramente magia..."},{"a":"rudo","t":"Es magia, evidentemente."},{"a":"rudo","t":"Siempre es una maldición mágica."},{"a":"master","t":"Me parece que ya lo sabías, ¿no? ¿Por qué no acudiste a alguien que supiera de estas cosas en vez de a mí?"},{"a":"rudo","t":"No me fío ni un pelo de los magos."},{"a":"master","t":"Hijo, no creo que tengas elección en este caso."},{"a":"master","t":"Además, ¿cómo no vas a confiar en Lilu? ¡Si es adorable!"},{"a":"rudo","t":"¿Es una maga o no? Eso significa que es igual que los demás."},{"a":"rudo","t":"Son peligrosos, malvados, retorcidos..."},{"a":"master","t":"Pues me parece que es la única que puede ayudarte si quieres librarte de este bastón."},{"a":"rudo","t":"Mecachis..."}]},{"id":"rudo_06","i":6,"title":"Mago involuntario","req":"rudo:6","reward":{"k":"gems","id":"gems","q":10,"n":"Joyas"},"side":false,"lines":[{"a":"rudo","t":"Lo de siempre, Naya."},{"a":"tavern","t":"Lo siento, Rudo. Las armas no están permitidas. Ya conoces las reglas."},{"a":"rudo","t":"¿Esto? Es un bastón para caminar."},{"a":"tavern","t":"¡A mí no me engañas, eso es un bastón mágico!"},{"a":"rudo","t":"Bah... Está bien. ¿Ves esto? Tiene una maldición, no me lo puedo quitar."},{"a":"tavern","t":"¡Madre mía! En ese caso, supongo que podríamos hacer una pequeña excepción. ¡Porque eres tú!"},{"a":"rudo","t":"Pfff... Gracias."},{"a":"tavern","t":"Bueno, ¿y qué vas a hacer con eso?"},{"a":"rudo","t":"Pasar, tendré que vivir con ello."},{"a":"tavern","t":"¿De verdad? A mí me parece que te está agriando más el carácter, y mira que es difícil."},{"a":"tavern","t":"Además, cualquiera podría pensar que eres un nigromante o algo así."},{"a":"rudo","t":"¿En serio? ¿Uno de esos condenados nigromantes?"},{"a":"tavern","t":"¡Solo te falta un gorro ridículo de esos! Bueno, y mejor humor."},{"a":"rudo","t":"Creo que tienes razón. Debo hacer algo al respecto. Nos vemos."},{"a":"tavern","t":"Venga, buen día. ¡Te lo apunto en la cuenta!"}]},{"id":"rudo_07","i":7,"title":"Atisbo de trauma","req":"rudo:7","reward":{"k":"gems","id":"gems","q":10,"n":"Joyas"},"side":false,"lines":[{"a":"rudo","t":"Perdona por lo de antes. Me han dicho que podrías ayudarme con esta maldición."},{"a":"lilu","t":"Es por ese bastón, ¿eh? ¡Tiene mala pinta!"},{"a":"lilu","t":"Nunca he intentado neutralizar una maldición, pero, en teoría, debería poder hacerlo."},{"a":"lilu","t":"¿Seguro que estás preparado? Te veo muy tenso."},{"a":"rudo","t":"Sí..."},{"a":"lilu","t":"¡Vale! Primero, voy a concentrarme..."},{"a":"lilu","t":"Veo la maldición envolviéndote..."},{"a":"lilu","t":"Espera, tendré que profundizar más..."},{"a":"rudo","t":"¡Buff!"},{"a":"lilu","t":"¡Vaya!"},{"a":"lilu","t":"¡Parecía que ibas a meterme un puñetazo!"},{"a":"rudo","t":"Perdona, no era mi intención."},{"a":"lilu","t":"No creo que vaya a funcionar. Tengo que concentrarme, ¿sabes?"},{"a":"rudo","t":"Sí, es culpa mía. Buscaré otra solución."},{"a":"lilu","t":"¿Y si le preguntas a Malady? Tal vez ella pueda ver algo que yo no."},{"a":"rudo","t":"Malady... Voy a probar."},{"a":"lilu","t":"Sé amable con ella, ¿eh? Tiene unas... circunstancias especiales que deberías conocer..."}]},{"id":"rudo_08","i":8,"title":"Maldición para dos","req":"rudo:8","reward":{"k":"gems","id":"gems","q":10,"n":"Joyas"},"side":false,"lines":[{"a":"rudo","t":"Malady, ¿tienes un momento?"},{"a":"malady","t":"(Oh, no, Lilu me advirtió sobre él...)"},{"a":"malady","t":"Mm... lo siento. No creo que..."},{"a":"rudo","t":"Perdona, no pretendía asustarte. Pensé que podrías saber algo sobre este bastón."},{"a":"malady","t":"¿No era que odiabas la magia?"},{"a":"rudo","t":"Más que nada en el mundo."},{"a":"rudo","t":"Pero tú estás maldita, ¿no? Igual que yo."},{"a":"rudo","t":"Tú no elegiste la magia. No es culpa tuya."},{"a":"malady","t":"En ese caso, puedo intentar... hablar con el bastón."},{"a":"malady","t":"..."},{"a":"malady","t":"Parece que es parasitario. Se alimenta de tu chispa."},{"a":"rudo","t":"¿Esa cosa es inteligente?"},{"a":"malady","t":"Sí... en cierto modo."},{"a":"malady","t":"Tu chispa parece enormemente fuerte. Puede que tardes décadas, pero..."},{"a":"malady","t":"Tal vez podría librarte de tu magia."},{"a":"rudo","t":"Bah. Yo no contaría con ello."},{"a":"rudo","t":"Entonces lo que quiere es a alguien a quien chuparle la magia, ¿sí?"},{"a":"malady","t":"Mm... sí. Más o menos."},{"a":"malady","t":"Por favor... Yo ya estoy maldita, así que..."},{"a":"rudo","t":"¡Ja! Ni lo pienses."},{"a":"rudo","t":"Gracias por la ayuda. Creo que tengo una idea..."}]},{"id":"rudo_09","i":9,"title":"El pasado de un soldado","req":"rudo:9","reward":{"k":"gems","id":"gems","q":10,"n":"Joyas"},"side":false,"lines":[{"a":"malady","t":"Mm... ¿Puedo pasar?"},{"a":"veteran","t":"Ah, la Medusa de la que tanto he oído hablar."},{"a":"veteran","t":"Pasa, principiante. Me temo que no tengo sillas de tu tamaño."},{"a":"malady","t":"No pasa nada, y gracias. Quería preguntarte sobre ese tal Rudo."},{"a":"veteran","t":"¿Ese gran zoquete? No se habrá metido contigo, ¿verdad?"},{"a":"malady","t":"No, ha sido... especialmente amable conmigo."},{"a":"veteran","t":"¿No me digas? Qué raro, porque odia la magia con todas sus fuerzas."},{"a":"malady","t":"Por eso he venido. Quería preguntarte por qué."},{"a":"veteran","t":"Antes servíamos en el ejército del imperio. Antiguos camaradas de guerra."},{"a":"veteran","t":"Rudo se ofreció «voluntario» para ser parte de un experimento. Uno que buscaba implantar artificialmente la chispa en los soldados."},{"a":"veteran","t":"Una idea espantosa. Jamás volvió a ser el mismo."},{"a":"malady","t":"Es horrible... "},{"a":"veteran","t":"Es mucho peor de lo que parece. Nos largaremos de allí en cuanto tuvimos la oportunidad."},{"a":"malady","t":"¿Funcionó, al menos? He sentido una chispa extremadamente poderosa en su interior..."},{"a":"veteran","t":"No sabría decirte. Ya has visto cómo se las gasta. Ni siquiera el emperador ha podido hacer que lance el conjuro más simple."},{"a":"malady","t":"Y ahora, por culpa de esto, sufre una maldición terrible... ¿Cómo podemos ayudar?"},{"a":"veteran","t":"Él vino a ti, ¿verdad? ¡Que te haya pedido ayuda es buena señal! "},{"a":"veteran","t":"No es el más avispado, pero es persistente. Seguro que se le ocurrirá algo."}]},{"id":"rudo_10","i":10,"title":"Transferencia de propiedad","req":"rudo:10","reward":{"k":"gems","id":"gems","q":10,"n":"Joyas"},"side":false,"lines":[{"a":"rudo","t":"Está bien, palillo pesado. Te propongo un trato."},{"a":"rudo","t":"Yo te entrego a ese trasco de allí."},{"a":"monster_Forest_Blacksmith","t":"¡Ay! ¡Suéltame!"},{"a":"rudo","t":"Entablas amistad con él y nos olvidamos de todo esto."},{"a":"rudo","t":"Si no quieres..."},{"a":"rudo","t":"Me tiro a la lava a ver cuál de los dos dura más."},{"a":"rudo","t":"¿Qué va a ser? ¡Para mí que el \"agua\" tiene buena pinta!"},{"a":"monster_Forest_Blacksmith","t":"..."},{"a":"rudo","t":"Buena elección. Que te diviertas, trasco."},{"a":"monster_Forest_Blacksmith","t":"¡Uff! Está... ¡encajado!"},{"a":"rudo","t":"¡Ja, ja, ja! ¡Hasta pronto!"}]},{"id":"rudo_epilogue","i":11,"title":"Epílogo","req":"rudo:11","reward":{"k":"gems","id":"gems","q":10,"n":"Joyas"},"side":false,"lines":[{"a":"lilu","t":"¡Rudo! Sobre la última vez..."},{"a":"rudo","t":"¿Mm?"},{"a":"lilu","t":"¡Oh! ¡Te has deshecho del bastón!"},{"a":"rudo","t":"Así es. Una carga menos de la que preocuparme."},{"a":"rudo","t":"Perdona por lo de la última vez. Estaba de los nervios."},{"a":"lilu","t":"Bueno, te perdono. ¡Pero tienes que mejorar esa actitud con los magos!"},{"a":"rudo","t":"¡Ja! La tal Malady fue sorprendentemente útil. Quién sabe, a lo mejor al final cambio de opinión."},{"a":"lilu","t":"¿Consiguió levantar la maldición?"},{"a":"rudo","t":"No exactamente. Pero, gracias a ella, encontré una... mano amiga inesperada."},{"a":"rudo","t":"Un poco de cooperación de vez en cuando no viene mal. ¡Bua, ja, ja!"},{"a":"argon","t":"¡Ashley, cuidado! ¡Se acerca algo más!"},{"a":"ashley","t":"¡Estoy lista para lo que sea! ¡Ven, bestia!"},{"a":"monster_Forest_Blacksmith","t":"Ayuda..."},{"a":"argon","t":"¿Eh?"},{"a":"ashley","t":"¿Eeeeeh?"}]}]},{"id":"sia","name":"Sia","chapters":[{"id":"sia_01","i":1,"title":"Primeros pasos reales","req":"sia:1","reward":{"k":"gems","id":"gems","q":10,"n":"Joyas"},"side":false,"lines":[{"a":"king","t":"Sia, ¡he tomado una decisión!"},{"a":"sia","t":"¿Sí, mi rey?"},{"a":"king","t":"¡Hoy me gustaría ir de compras!"},{"a":"sia","t":"Una idea excelente, majestad."},{"a":"sia","t":"Sin embargo, según vuestro horario, hoy tenéis que recibir a dignatarios extranjeros..."},{"a":"king","t":"Ay, ¡qué lata! ¿No podemos deshacernos de ellos?"},{"a":"sia","t":"Recordad, mi rey, que, aunque seáis joven, sois el rey. Vuestra palabra es sagrada."},{"a":"king","t":"¡Tienes toda la razón! Pues a comprar. ¡Que esperen esos dignatarios!"},{"a":"sia","t":"Vuestra decisión es admirable. ¿Queréis que os acompañe?"},{"a":"king","t":"¡Por supuesto! No confío en nadie más para proteger a mi regia persona."}]},{"id":"sia_02","i":2,"title":"Amigos en lugares sórdidos","req":"sia:2","reward":{"k":"gems","id":"gems","q":10,"n":"Joyas"},"side":false,"lines":[{"a":"sia","t":"... Así que tengo motivos para creer que la vida del rey corre peligro."},{"a":"elderowen","t":"Ya veo. La verdad es que varios reinos rivales se beneficiarían de que se atentara contra la vida del rey."},{"a":"elderowen","t":"No he visto a ningún sospechoso, pero seguro que Naya, de la taberna, sabe algo más."},{"a":"sia","t":"Gracias, anciano. Valoro tu sabiduría y patriotismo."},{"a":"elderowen","t":"No hay de qué. Es mi deber como ciudadano garantizar el bienestar del reino."},{"a":"elderowen","t":"Puede que sea joven e inconsciente, pero seguro que Reinhold será un buen rey... con el tiempo."},{"a":"sia","t":"¡Y es mi deber asegurarme de que viva hasta entonces!"},{"a":"tavern","t":"Vaya, vaya, ¡no todos los días se ve sangre azul por la taberna!"},{"a":"sia","t":"Déjalo, Naya, que ya sabes quién soy."},{"a":"tavern","t":"¡Claro! Sia Leonel, un obsequio del emperador de Kern para nuestro rey."},{"a":"tavern","t":"Para que actuaras de asesora, pero también para vigilarlo de cerca, ¿verdad?"},{"a":"sia","t":"¡...!"},{"a":"sia","t":"Qué indiscreta, ¿no?"},{"a":"sia","t":"Pues ya que eres tan indiscreta, dime, Naya..."},{"a":"sia","t":"¿Has visto caras extrañas por la taberna últimamente?"},{"a":"tavern","t":"Uy, por aquí pasan montones de caras extrañas: orcos achispados, comerciantes..."},{"a":"tavern","t":"Pero diría que la más extraña es esa chica de la esquina."},{"a":"yami","t":"¡...!"},{"a":"sia","t":"Ha huido..."},{"a":"sia","t":"¡Era una espía azumana! O una asesina..."},{"a":"sia","t":"Debo andarme con mucho ojo..."}]},{"id":"sia_03","i":3,"title":"Intruso","req":"sia:3","reward":{"k":"gems","id":"gems","q":10,"n":"Joyas"},"side":false,"lines":[{"a":"sia","t":"Os hemos convocado a todos aquí para celebrar la increíble generosidad del Rey."},{"a":"sia","t":"En los últimos meses ha donado varios millones en oro de sus propias arcas..."},{"a":"sia","t":"... a varios templos, escuelas y orfanatos locales."},{"a":"sia","t":"Todos son bienvenidos al banquete, así que, por favor, corred la voz entre amigos y familiares."},{"a":"sia","t":"¡Larga vida al rey Reinhold!"},{"a":"yami","t":"¡Tirano Reinhold, tu reinado acaba aquí mismo!"},{"a":"king","t":"Aaarg..."},{"a":"sia","t":"¡Una shuriken! ¡La espía azumana!"},{"a":"sia","t":"¡Guardias! Formen un perímetro alrededor del castillo. ¡Que nadie salga!"},{"a":"sia","t":"¡Argon! ¡Persigue a la asesina!"},{"a":"argon","t":"¡Ya!"},{"a":"sia","t":"¡Tú! ¡Idiota pordiosero! ¡El Rey está herido! Ve a buscar a un curandero de inmediato."},{"a":"leather","t":"Hala, qué borde."},{"a":"sia","t":"(Tenía cada entrada bajo máxima vigilancia)."},{"a":"sia","t":"(¿Quién es esta chica?)."}]},{"id":"sia_04","i":4,"title":"Correo carbonizado","req":"sia:4","reward":{"k":"gems","id":"gems","q":10,"n":"Joyas"},"side":false,"lines":[{"a":"sia","t":"Naya, pedazo de entrometida, creo que me debes algunas explicaciones."},{"a":"tavern","t":"Yo diría que eres tú la que me debe una explicación, Sra. Leonel."},{"a":"sia","t":"¿Disculpa?"},{"a":"tavern","t":"He interceptado unas cartas muy interesantes. Enviadas por ti si no me equivoco."},{"a":"tavern","t":"¿Las leemos juntas?"},{"a":"sia","t":"¡...!"},{"a":"tavern","t":"Veamos... ¿Un sello de Kern dirigido directamente al Emperador de Kern?"},{"a":"tavern","t":"Vaya, vaya. Me esperaba una escandalosa aventura amorosa, pero la traición tampoco está mal."},{"a":"sia","t":"¡Na-Naya! ¡Vale ya!"},{"a":"tavern","t":"¡Huy! Aquí viene lo mejor."},{"a":"tavern","t":"«El rey Reinhold es un tonto de remate. Su presencia en el trono te beneficia enormemente»."},{"a":"tavern","t":"«Mantenerlo vivo dañará su reino más que su propia muerte»."},{"a":"sia","t":"..."},{"a":"tavern","t":"Semejantes palabras son bastante impropias de una asesora, diría yo."},{"a":"sia","t":"Naya... ¡Me las pagarás!"},{"a":"tavern","t":"Tal vez algún día, pero, de momento, creo que serás tú la que pague. Y con creces, me temo."},{"a":"sia","t":"¿Vas a caer tan bajo como para hacerme chantaje?"},{"a":"tavern","t":"Un pecado sin importancia, comparado con la traición."},{"a":"tavern","t":"Sin embargo, si pensabas hacer daño a nuestro Rey..."},{"a":"sia","t":"¡Bah! Muy bien, dime cuál es tu precio, y reza por que mi red de espías no burle a la tuya, Naya."},{"a":"tavern","t":"¡Lo espero impaciente!"}]},{"id":"sia_a","i":4,"title":"El capricho del rey","req":"sia:3","reward":{"k":"tokens","id":"tokens","q":3,"n":"Fichas de la fortuna"},"side":true,"lines":[{"a":"sia","t":"Mi rey."},{"a":"king","t":"¡Mi querida Sia! ¿En qué puedo ayudarte?"},{"a":"sia","t":"¿Por algún casual no habréis tenido otro de vuestros «brotes caprichosos» recientemente?"},{"a":"king","t":"¡No, no! ¡Por supuesto que no! ¡Yo no soy así!"},{"a":"sia","t":"Qué extraño... Nuestros libros de contabilidad indican que la cámara acorazada 36 está repleta de <c1>kunai</c1>."},{"a":"sia","t":"No tengo que recordarle a su majestad que se trata de un objeto increíblemente inusual."},{"a":"king","t":"Yo... Seguro que hay una explicación lógi..."},{"a":"sia","t":"Además, muchas de las antigüedades más curiosas del reino se han visto en las manos de la gente de a pie."},{"a":"sia","t":"Admiro vuestra generosidad..."},{"a":"sia","t":"... Pero os ruego que no repartáis artefactos de tanto valor para financiar vuestros cambios de humor."},{"a":"king","t":"Pff... Está bien. A partir de hoy, seré un hombre nuevo."},{"a":"sia","t":"Gracias por vuestra comprensión. Ahora, he de irme."},{"a":"king","t":"¡Mi voluntad es férrea! ¡No necesito bienes materiales para nada!"},{"a":"king","t":"... Bueno, a esta sala le vendrían bien unas <c1>espadas reales</c1>, ¿no?"}]},{"id":"sia_05","i":5,"title":"Agente Cisne","req":"sia:5","reward":{"k":"gems","id":"gems","q":10,"n":"Joyas"},"side":false,"lines":[{"a":"sia","t":"«... Tras un inesperado giro de los acontecimientos, alguien ha atentado contra la vida del rey Reinhold»."},{"a":"sia","t":"«Azuma parece estar detrás de todo esto. La agente Cisne lo investigará más a fondo»."},{"a":"king","t":"¡Sia! ¿Qué haces?"},{"a":"sia","t":"Oh, solo escribo una carta, nada importante."},{"a":"sia","t":"(Nada menos que mi informe para el emperador Kern...)."},{"a":"king","t":"¡Muy bien! Me esperan unos dignatarios extranjeros."},{"a":"king","t":"Puede que estén un poco ofendidos tras el último viaje de compras."},{"a":"king","t":"Me gustaría contar con tu ayuda para calmar la situación."},{"a":"sia","t":"Claro. Llegaré enseguida, mi rey."},{"a":"sia","t":"Que el emperador Kern se entere del intento de asesinato podría desencadenar graves consecuencias."},{"a":"sia","t":"Necesito más tiempo para pensar. Este reino no está listo para enfrentarse a Kern."},{"a":"sia","t":"Supongo que no pasa nada por omitir este detalle... por la seguridad de todos."},{"a":"sia","t":"«Todo va según lo previsto. La agente Cisne no tiene nada que lo que informar este mes»."}]},{"id":"sia_06","i":6,"title":"Rosa y espina","req":"sia:6","reward":{"k":"gems","id":"gems","q":10,"n":"Joyas"},"side":false,"lines":[{"a":"king","t":"¡Sia! Alguien ha venido verte; un tipo muy principesco, por cierto."},{"a":"sia","t":"¿Principesco, mi rey? No puede ser..."},{"a":"donovan","t":"Señorita Sia."},{"a":"sia","t":"... Donovan."},{"a":"sia","t":"Mi rey, un asunto urgente requiere tu atención en la tesorería. Sería recomendable que acudas de inmediato."},{"a":"king","t":"¡Oh! ¿Ha llegado el último cargamento de oro puro? ¡Qué ganas!"},{"a":"donovan","t":"No espabila este rey, ¿eh?"},{"a":"sia","t":"¿Qué demonios te trae al reino de Reinhold, alquimista?"},{"a":"donovan","t":"Tan directa como siempre, agente Cisne."},{"a":"donovan","t":"Solo me he cogido unos días libres; con el permiso del emperador Kern, por supuesto."},{"a":"donovan","t":"Para oler las flores, saborear las pociones... Las típicas vacaciones de un alquimista, vamos."},{"a":"sia","t":"¿Y tenías que venir aquí? ¿De todos los lugares?"},{"a":"donovan","t":"A pesar de ser un reino retrógrado, aquí viven varios talentosos alquimistas."},{"a":"donovan","t":"Aunque si la lealtad de un cisne se vuelve vacilante..."},{"a":"sia","t":"Ya lo has dejado claro, Donovan. ¿Por qué no te vas a disfrutar de... tus vacaciones?"},{"a":"donovan","t":"Como desees, señorita Sia. Ha sido un placer, como siempre."},{"a":"sia","t":"Otra espina clavada en mi costado."}]},{"id":"sia_07","i":7,"title":"Forastera en la Ciudad de Oro","req":"sia:7","reward":{"k":"gems","id":"gems","q":10,"n":"Joyas"},"side":false,"lines":[{"a":"sia","t":"¿Donovan? Espero no estar interrumpiendo ningún... espionaje."},{"a":"donovan","t":"¡Ah! ¡Señorita Sia!"},{"a":"donovan","t":"No, no te preocupes. Solo estaba echando un vistazo."},{"a":"sia","t":"No hay motivos para andarse con secretos. Todo el mundo es bienvenido en la Ciudad de Oro perdida."},{"a":"sia","t":"No obstante, recuerda que, tal y como estipula la ley del rey, todo el <c1>oro puro</c1> que se halle en su interior pertenece al rey Reinhold."},{"a":"sia","t":"A cambio, los aventureros más osados son recompensados por sus esfuerzos."},{"a":"donovan","t":"Ya veo. Qué gobernante tan... generoso."},{"a":"donovan","t":"Ese <c1>oro puro</c1> se acuña y, como resultado, la inflación de la moneda es elevadísima..."},{"a":"sia","t":"Ajá, ya veo que has estado interceptando mi correo con el emperador."},{"a":"donovan","t":"Me gusta estar al tanto."},{"a":"sia","t":"Ya que estás aquí, haz algo útil y lleva <c1>oro puro</c1> al castillo."},{"a":"donovan","t":"Por supuesto. A tus pies."},{"a":"sia","t":"Intenta no romperte ninguna uña cuando vuelvas, Donovan."}]},{"id":"sia_08","i":8,"title":"Encrucijada del destino","req":"sia:8","reward":{"k":"gems","id":"gems","q":10,"n":"Joyas"},"side":false,"lines":[{"a":"tavern","t":"¡Ha vuelto mi pequeño cisne! Tan puntual como siempre, lo que se espera del mejor administrador que tenemos."},{"a":"sia","t":"He respondido a tu llamada, indiscreta Naya. Estoy de mal humor, así que date prisa."},{"a":"tavern","t":"¡Pues prepárate para estar de peor humor! He interceptado el correo de cierto alquimista..."},{"a":"tavern","t":"¡Magicorreo exprés, además! No tienes ni idea lo difícil que es echarle el guante."},{"a":"sia","t":"¿No te referirás a...?"},{"a":"tavern","t":"Me parece a mí que el tal Donovan ha descubierto tu jueguecito."},{"a":"sia","t":"Si lo has interceptado, entonces..."},{"a":"tavern","t":"¡Eso es, no irá a ninguna parte! Si pagas, claro."},{"a":"sia","t":"Yo... Está bien. Dime cuánto quieres y lo pagaré, Naya."},{"a":"tavern","t":"Mis tarifas habituales han subido de precio, y necesito algo especial por este premio."},{"a":"sia","t":"Muy bien, pues..."},{"a":"tavern","t":"Mi precio es que escojas un bando, Sia."},{"a":"sia","t":"..."},{"a":"tavern","t":"Jugar en ambos bandos es algo muy peligroso..., y parece que ya estás metida hasta el hoyo."},{"a":"tavern","t":"Naturalmente, podría ayudarte dependiendo de tu respuesta..."}]},{"id":"sia_09","i":9,"title":"Cadena de traiciones","req":"sia:9","reward":{"k":"gems","id":"gems","q":10,"n":"Joyas"},"side":false,"lines":[{"a":"sia","t":"Querido Donovan. Quiero pedirte algo, si no te importa."},{"a":"donovan","t":"¿Ah, sí? A ver, cuéntame."},{"a":"sia","t":"Ve a hablar con el emperador y dile que la agente Cisne ha muerto. Ha sufrido una muerte trágica y honorable sirviendo diligentemente al imperio."},{"a":"donovan","t":"¿C-cómo dices?"},{"a":"sia","t":"Lo dejo, Donovan. Me cambio de bando, por decirlo de algún modo."},{"a":"sia","t":"Y tú serás quien le dé la noticia y, de paso, respaldar mi historia."},{"a":"donovan","t":"¡Eso es ridículo! ¡Es alta traición! Yo jamás podría..."},{"a":"sia","t":"Estoy segura de que sí, Donovan. A no ser que quieras que el mundo conozca la fórmula de tu elixir de inmortalidad, claro está."},{"a":"donovan","t":"¿Hasta ahí eres capaz de llegar con tu engaño, Sia? Jamás le he hablado a nadie de esta fórmula, es imposible que..."},{"a":"sia","t":"¿Cómo dices? ¿Las alas de una efímera de un siglo? ¿Agua del río Estigia? ¿Qué más era?"},{"a":"donovan","t":"E-eso es..."},{"a":"sia","t":"Son muchos ingredientes... ¿No se añade también un poquito de vino para darle gusto?"},{"a":"donovan","t":"¡Silencio! ¡SILENCIO! No sé qué poderes oscuros habrás aprendido para conocer esto..."},{"a":"sia","t":"Parece que subestimas a mi red de espías."},{"a":"donovan","t":"... Pero bien, te seguiré el juego. Por esta vez."},{"a":"sia","t":"Qué mal perder tenemos, ¿eh? Creo que mis condiciones son más que generosas."},{"a":"sia","t":"¿Qué es una pequeña traición a cambio del trabajo de tu vida?"}]},{"id":"sia_10","i":10,"title":"Asistencia póstuma","req":"sia:10","reward":{"k":"gems","id":"gems","q":10,"n":"Joyas"},"side":false,"lines":[{"a":"sia","t":"Agente Susurros, soy yo."},{"a":"essence","t":"*Bostezo* ¿Tan pronto?"},{"a":"sia","t":"Tu información era precisa. Te felicito; has realizado un trabajo estelar."},{"a":"essence","t":"No es... nada..."},{"a":"sia","t":"Donovan siempre ha sido un hombre prudente, pero supongo que no hay muchas cosas que pueden impedirle cotillear a un fantasma."},{"a":"essence","t":"Total..."},{"a":"essence","t":"Parecía... muy enfadado..."},{"a":"sia","t":"Tal y como acordamos, enviaré el pago a tu tumba como ofrenda."},{"a":"sia","t":"He incluido una pequeña gratificación. Ve a atormentar a Donovan un rato más."},{"a":"essence","t":"Me pagan para que haga cosas de fantasma. Es genial."}]},{"id":"sia_11","i":11,"title":"Un cisne vuela libre","req":"sia:11","reward":{"k":"gems","id":"gems","q":10,"n":"Joyas"},"side":false,"lines":[{"a":"king","t":"¡Sia, apenas lo puedo contener! ¡¿Cuánto más tiempo debo esperar hasta que pueda desatar mis caprichos sobre el mundo?!"},{"a":"sia","t":"Apenas han pasado unos días, majestad. Te ruego que tengas un poco de paciencia."},{"a":"king","t":"¡Ah! ¿Qué son todos estos documentos?"},{"a":"sia","t":"Certificados de nacimiento y otro tipo de papeles administrativos importantes relacionados conmigo."},{"a":"sia","t":"Pura casualidad, pero parece que han desaparecido gran parte de los documentos que detallan mi vida en este reino."},{"a":"sia","t":"Desde entonces, he estado rellenando diligentemente estos formularios usando mi memoria."},{"a":"king","t":"¡Pues claro! ¡No estaría nada bien que mi mejor consejera no fuera una súbdita oficial de mi reino!"},{"a":"king","t":"¡Trae acá! ¡Les pondré mi sello real cuanto antes!"},{"a":"king","t":"¡Todo listo! Como siempre, no se te escapa ningún detalle."},{"a":"sia","t":"Gracias, excelente. Espero serviros muchas décadas más."},{"a":"king","t":"¡No espero menos de ti!"},{"a":"king","t":"Sia, ¿eso que veo en tu rostro... es una lágrima? ¿Tanto te gusta rellenar documentos?"},{"a":"sia","t":"Ah... No. De hecho, diría que todo este papeleo ha hecho que me den ganas de llorar del aburrimiento."},{"a":"sia","t":"¡Bueno, no importa! ¿Queréis que hable de vuestros caprichos?"},{"a":"king","t":"¡Adelante! Si quieres saber mi opinión, la situación actual del escudo..."}]}]},{"id":"atlab_sokka","name":"Sokka","chapters":[{"id":"atlab_sokka_01","i":1,"title":"Sokka, el maestro de la espada","req":"atlab_sokka:1","reward":{"k":"tokens","id":"tokens","q":5,"n":"Fichas de la fortuna"},"side":false,"lines":[{"a":"atlab_aang","t":"¿Y qué me dices de esto?"},{"a":"tavern","t":"Ay, ¡qué truco tan adorable!"},{"a":"atlab_sokka","t":"Bah, siempre hace lo mismo."},{"a":"argon","t":"¡Hola! Te llamas Sokka, ¿verdad? Soy Argon."},{"a":"atlab_sokka","t":"Ah, hola. Si te gustan los truquitos de dominar elementos, buscas a Aang."},{"a":"argon","t":"Ah, no. La magia y eso de dominar elementos no va conmigo."},{"a":"argon","t":"A juzgar por tu equipo, diría que eres un guerrero temible."},{"a":"atlab_sokka","t":"¿Eh? ¿Un guerrero te-temible?"},{"a":"atlab_sokka","t":"Pu-pues has acertado. Soy Sokka, ¡el gran guerrero del equipo Avatar!"},{"a":"argon","t":"¡Lo sabía! ¡Seguro que tienes un montón de historias superinteresantes!"},{"a":"atlab_sokka","t":"Desde luego. Por ejemplo, durante el asedio de Agna Quel'a..."},{"a":"atlab_sokka","t":"Y así fue cómo la chica que era mi novia se convirtió en la luna."},{"a":"argon","t":"¡¿En la luna?!"},{"a":"atlab_sokka","t":"Sí, pero luego la Nación del Fuego se desvaneció..."},{"a":"atlab_sokka","t":"... y ¡pam! Dejé inconsciente a aquella lechuza gigante de la biblioteca."},{"a":"argon","t":"¡Caray! ¿Y aquella lechuza no era un espíritu muy poderoso?"},{"a":"atlab_sokka","t":"Exacto. ¡Si Sokka anda cerca, el equipo Avatar siempre se hará con la victoria!"},{"a":"atlab_sokka","t":"Hablando del rey de Roma..., ¿dónde está Aang?"},{"a":"argon","t":"Ah, se fue hace una hora más o menos."},{"a":"atlab_sokka","t":"¡Mecachis! Se me ha ido el tiempo. Lo siento, Argon, he de irme."}]},{"id":"atlab_sokka_02","i":2,"title":"Sokka, el maestro herrero","req":"atlab_sokka:2","reward":{"k":"tokens","id":"tokens","q":5,"n":"Fichas de la fortuna"},"side":false,"lines":[{"a":"blacksmith","t":"¿Dándole al callo, Sokka?"},{"a":"atlab_sokka","t":"Hola, Wallace. Gracias por dejarme usar tus herramientas."},{"a":"blacksmith","t":"De nada, hombre. No pensaba que serías un artesano tan diestro a tu edad."},{"a":"atlab_sokka","t":"Cuando eres el único de tu grupo que no puede dominar ningún elemento, necesitas otras habilidades."},{"a":"atlab_sokka","t":"Y no todos los días tengo la oportunidad de usar herramientas de esta calidad..."},{"a":"atlab_sokka","t":"¡Terminaré con esto en un periquete!"},{"a":"blacksmith","t":"¿De dónde has sacado la espada que estás afilando?"},{"a":"atlab_sokka","t":"Ah, es mi espada espacial. Yo mismo la forjé."},{"a":"blacksmith","t":"¿Metal estelar? No está nada mal, chaval."},{"a":"blacksmith","t":"Debe ser... ¡de otro planeta!"},{"a":"atlab_sokka","t":"Y tanto que sí, no existe otra espada igual."},{"a":"polonia","t":"¡Arrr! Perdonad que os interrumpa, pero ¿alguno de estos mozalbetes quiere ayudarme a reparar el barco?"},{"a":"polonia","t":"Hoy está de mal humor. Le alcanzaron unas bolas de hierro muy raras y se me ha quedado encallado..."},{"a":"blacksmith","t":"¡Pues sí que es una faena!"},{"a":"atlab_sokka","t":"No hay problema, ¡soy de la Tribu del Agua! A ver qué podemos hacer... Perdona, Wallace, tengo que irme."},{"a":"blacksmith","t":"Mientras tanto arreglaré el resto de tu equipo. ¡Buena suerte!"}]},{"id":"atlab_sokka_03","i":3,"title":"Sokka, el maestro explorador","req":"atlab_sokka:3","reward":{"k":"tokens","id":"tokens","q":5,"n":"Fichas de la fortuna"},"side":false,"lines":[{"a":"atlab_sokka","t":"Listo. Por lo menos, ahora deberías llegar sin problemas al puerto."},{"a":"polonia","t":"¡Has hecho un trabajo de primera!"},{"a":"atlab_sokka","t":"He logrado mantener el timón con madera de deriva y trozos de mi camisa."},{"a":"atlab_sokka","t":"Tampoco es un trabajo «de primera». Dejémoslo en que tiene el «toque de Sokka»."},{"a":"polonia","t":"¿Y qué hace un marinero de agua dulce arreglando barcos? ¡Jo, jo, jo!"},{"a":"atlab_sokka","t":"En la Tribu del Agua estamos acostumbrados a movernos en barco y pescar. Aprendí a navegar antes que a andar."},{"a":"atlab_sokka","t":"De hecho, he trazado los planos para crear un submarino que funcione con el dominio del agua."},{"a":"polonia","t":"Hablas como los de agua dulce, no te entiendo."},{"a":"atlab_sokka","t":"A ver, es un barco de metal que va por debajo del agua."},{"a":"polonia","t":"Me parece que estás cavando una tumba marina para tus amigos, grumete."},{"a":"engineer","t":"¿Alguien ha dicho «prototipo altamente peligroso y experimental»?"},{"a":"atlab_sokka","t":"Ah, no es exactamente..."},{"a":"engineer","t":"Me gusta tu estilo. Acompáñame, chico."},{"a":"polonia","t":"¡Jo, jo, jo! ¡De vuelta al mar! Voy a levar anclas antes de que lleguen los ladrones de tesoros."},{"a":"polonia","t":"Arrr, será mejor que mi chica de hierro y yo nos pongamos en marcha."}]},{"id":"atlab_sokka_04","i":4,"title":"Sokka, el maestro inventor","req":"atlab_sokka:4","reward":{"k":"tokens","id":"tokens","q":5,"n":"Fichas de la fortuna"},"side":false,"lines":[{"a":"engineer","t":"¡Fascinante! No te voy a mentir, los planos son un poco chapuceros..."},{"a":"engineer","t":"Pero, con un poquito de esfuerzo, creo que tu submarino podría funcionar."},{"a":"atlab_sokka","t":"Está chulo, ¿eh? ¡Lo sabía!"},{"a":"atlab_sokka","t":"Eso sí, recuerda que está creado para que lo manejen los maestros del Agua."},{"a":"engineer","t":"Un detallito sin importancia. Ya lo solucionaremos."},{"a":"engineer","t":"¡Párate y piensa! Con algo así, podríamos explorar el templo hundido."},{"a":"atlab_sokka","t":"Por cierto, no tiene capacidad para mucho oxígeno, así que los viajes tienen que ser cortos."},{"a":"atlab_sokka","t":"Oye, ¿me estás escuchando?"},{"a":"engineer","t":"No te apoyes en esa bola de hierro."},{"a":"atlab_sokka","t":"¿Eh? ¡Ostras! ¿Por qué no?"},{"a":"engineer","t":"Es el prototipo de mi bomba marina. No la toques, le gusta explotar."},{"a":"atlab_sokka","t":"... Ah."},{"a":"atlab_sokka","t":"Bueno, ya me dirás cómo avanza el prototipo."},{"a":"atlab_sokka","t":"Si funciona, tal vez podamos usarlo en el futuro."}]}]},{"id":"leather","name":"Tamas","chapters":[{"id":"leather_farewell","i":0,"title":null,"req":null,"reward":null,"side":false,"lines":[{"a":"leather","t":"Hola, colega. Creo que me he cansado de ser un campeón."},{"a":"leather","t":"Son más responsabilidades de las que me imaginaba... ¡Apenas me queda tiempo para mi cuero!"},{"a":"leather","t":"A lo mejor lo intento el año que viene, colega. ¡Venga, nos vemos por la ciudad!"}]},{"id":"leather_01","i":1,"title":"Cuero y árbol","req":"leather:1","reward":{"k":"tokens","id":"tokens","q":5,"n":"Fichas de la fortuna"},"side":false,"lines":[{"a":"leather","t":"Gracias por la ayuda, colega."},{"a":"argon","t":"De nada, Tamas. ¡Cuánto cuero!"},{"a":"leather","t":"Hoy he traído una buena cantidad. Por cierto, cuidado por dónde pisas."},{"a":"argon","t":"Sí, el terreno es irregular por aquí... ¡Hala!"},{"a":"leather","t":"¡Hala! ¡Vaya!"},{"a":"argon","t":"¡Perdona, Tamas! ¿Estás bien?"},{"a":"leather","t":"Me he dado en la cabeza, pero no es nada grave."},{"a":"leather","t":"Me acaba de venir una idea de esas que tienen los genios."},{"a":"leather","t":"Me tengo que ir, colega. Esto es algo gordo."},{"a":"argon","t":"¡Eh, claro! ¡Encantado de ayudarte!"},{"a":"argon","t":"¿Y qué hago con todo el cuero que está por ahí tirado?"}]},{"id":"leather_02","i":2,"title":"Vaticinado por la profecía","req":"leather:2","reward":{"k":"tokens","id":"tokens","q":5,"n":"Fichas de la fortuna"},"side":false,"lines":[{"a":"leather","t":"... y así es cómo me di en la cabeza, colega. Me ha salido un chichoncito aquí."},{"a":"mana","t":"Escucho, pero ayudar no puedo."},{"a":"mana","t":"Las corrientes del éter divino revelan, pero no curan."},{"a":"leather","t":"Sigue siendo magia, ¿no? Venga, colega. Tócalo con esas manos mágicas que tienes."},{"a":"mana","t":"No hay..."},{"a":"mana","t":"¡...!"},{"a":"mana","t":"Este... destino... es... ¡abrumador!"},{"a":"leather","t":"¿Seguro que ha funcionado, colega? Sigo un poco mareado."},{"a":"mana","t":"Lo siento... Ha surgido una nueva visión que precisa de meditación."},{"a":"mana","t":"Busca el favor de la Diosa por tus... heridas. Debo marcharme de inmediato."},{"a":"leather","t":"Pues vale. Bueno, me daré un paseíto para que se me pase. Últimamente me noto bastante fuerte."}]},{"id":"leather_03","i":3,"title":"Sindicato de campeones","req":"leather:3","reward":{"k":"tokens","id":"tokens","q":5,"n":"Fichas de la fortuna"},"side":false,"lines":[{"a":"argon","t":"Esto... Tenemos un nuevo campeón en la ciudad."},{"a":"polonia","t":"¡Jo, jo, jo! ¡Espero que sea guapo!"},{"a":"leather","t":"Hola, gente."},{"a":"polonia","t":"Por todos los percebes del mar... ¿Es una broma?"},{"a":"lilu","t":"¡¿Tamas?! Pero ¿cuándo...?"},{"a":"leather","t":"Colega, quería probar todo este rollo de los campeones. No parece muy difícil, ¿eh?"},{"a":"argon","t":"¿Cuál es tu especialidad, Tamas?"},{"a":"leather","t":"Les meto porrazos a los monstruos, y también rastreo objetos de cuero a larga distancia."},{"a":"polonia","t":"¡Eh, lo de robar es mi especialidad! ¡No te copies!"},{"a":"leather","t":"Eso no es robar, colega. La gente lo deja por ahí tirado."},{"a":"lilu","t":"Me parece que la cosa se va a poner interesante..."},{"a":"polonia","t":"¡Arr! Tal vez tengas razón..."}]},{"id":"leather_04","i":4,"title":"Héroe ignorado","req":"leather:4","reward":{"k":"tokens","id":"tokens","q":5,"n":"Fichas de la fortuna"},"side":false,"lines":[{"a":"sia","t":"Mi rey, traigo un informe un tanto inusual."},{"a":"king","t":"Como siempre, soy todo oídos. Cuenta, cuenta."},{"a":"sia","t":"Los héroes y las caravanas nos dicen que los caminos nunca habían sido tan seguros."},{"a":"sia","t":"Apenas se ven monstruos, e incluso parecen tener miedo de atacar a la gente."},{"a":"king","t":"¡Es una noticia fantástica!"},{"a":"sia","t":"Sí, aunque no se nos ocurre el motivo de esta extraña actitud."},{"a":"sia","t":"También es raro que los artículos de cuero hayan sufrido una caída en el mercado..."},{"a":"king","t":"Seguro que es una casualidad. ¡Venga, vamos a celebrar esta buena noticia!"},{"a":"sia","t":"Quizá tengáis razón, mi rey... Quizá."}]}]},{"id":"yami","name":"Yami","chapters":[{"id":"yami_01","i":1,"title":"La azumana errante","req":"yami:1","reward":{"k":"gems","id":"gems","q":10,"n":"Joyas"},"side":false,"lines":[{"a":"monster_forest_Boss","t":"¡Ji, ji, ji! ¿A quién tenemos aquí?"},{"a":"yami","t":"Pff. Largo, alimaña."},{"a":"monster_forest_Boss","t":"¡Vaya modales, señorita! Y qué ropa más rara."},{"a":"yami","t":"..."},{"a":"monster_forest_Boss","t":"¡Ajá! Hueles a Azuma, el reino oriental de los humanos."},{"a":"monster_forest_Boss","t":"¿Para qué has venido hasta aquí, chica?"},{"a":"monster_forest_Boss","t":"Armada hasta los dientes y sin soltar prenda... Debes de ser una asesina, ¿no?"},{"a":"yami","t":"..."},{"a":"monster_forest_Boss","t":"Je, je, ¡lo sabía! Estúpidos humanos, siempre matándoos unos a otros..."},{"a":"yami","t":"Tienes razón; he venido para matar a un rey tirano."},{"a":"monster_forest_Boss","t":"Pues mala asesina eres si lo vas diciendo por ahí... ¿Por qué me lo cuentas?"},{"a":"yami","t":"Porque no vivirás para contárselo a nadie. Adiós."},{"a":"monster_forest_Boss","t":"¡Ahh!"},{"a":"yami","t":"Rey Reinhold, eres el siguiente."}]},{"id":"yami_02","i":2,"title":"Cazador o cazado","req":"yami:2","reward":{"k":"gems","id":"gems","q":10,"n":"Joyas"},"side":false,"lines":[{"a":"yami","t":"La seguridad del castillo es abrumadora."},{"a":"yami","t":"Un sistema de contraseña que cambia a diario..."},{"a":"yami","t":"Patrullas de guardias sin horarios..."},{"a":"yami","t":"Tendré que ir..."},{"a":"argon","t":"¡Hola! ¡Tú, el de los arbustos!"},{"a":"yami","t":"¡...!"},{"a":"argon","t":"¿También vienes para convertirte en caballero?"},{"a":"argon","t":"Sia vendrá en breve. No hay por qué esconderse, ¡es muy agradable!"},{"a":"yami","t":"¡Sia...!"},{"a":"yami","t":"Tengo que irme. Adiós."},{"a":"argon","t":"¡U-un momento!"},{"a":"argon","t":"¡Hala! ¡¿Una bomba de humo?!"},{"a":"yami","t":"He perdido a ese necio..."},{"a":"yami","t":"Con Sia aquí, mi tarea resultará difícil..."},{"a":"yami","t":"Pero tengo que hacerlo. No puedo fallar."},{"a":"yami","t":"Por la orden, y por el bien de mi hermana."}]},{"id":"yami_03","i":3,"title":"Punto de inflexión","req":"yami:3","reward":{"k":"gems","id":"gems","q":10,"n":"Joyas"},"side":false,"lines":[{"a":"king","t":"¡Mi estimado pueblo! Gracias por acudir a mi lujoso banquete."},{"a":"king","t":"También os da la oportunidad de deleitaros con mi hermosa presencia. ¡No os perdáis semejante ocasión!"},{"a":"yami","t":"(Un tirano pretencioso. Típico)."},{"a":"sia","t":"Mm, sí. Gracias por un discurso tan edificante, su majestad."},{"a":"sia","t":"Os hemos convocado a todos aquí para celebrar la increíble generosidad del Rey."},{"a":"sia","t":"En los últimos meses ha donado varios millones en oro de sus propias arcas..."},{"a":"sia","t":"... a varios templos, escuelas y orfanatos locales."},{"a":"sia","t":"Estáis todos invitados. Que corra la voz entre vuestros amigos y familiares."},{"a":"sia","t":"¡Larga vida al rey Reinhold!"},{"a":"yami","t":"(No es la forma de actuar de un tirano)."},{"a":"yami","t":"(No, la orden no nos mentiría. Tiene que ser un truco)."},{"a":"yami","t":"¡Tirano Reinhold, tu reinado acaba aquí mismo!"},{"a":"sia","t":"¡Una shuriken! ¡La asesina azumana!"},{"a":"yami","t":"¿He fallado? ¡Imposible!"},{"a":"sia","t":"¡Guardias, bloquead todas las salidas! ¡Capturad a esa mujer inmediatamente!"}]},{"id":"yami_04","i":4,"title":"Reflexión","req":"yami:4","reward":{"k":"gems","id":"gems","q":10,"n":"Joyas"},"side":false,"lines":[{"a":"yami","t":"(Dudé... Y fallé)."},{"a":"yami","t":"(¿Será mentira lo que dijo la orden?)."},{"a":"yami","t":"(No importa. Ahora estoy sola)."},{"a":"argon","t":"¡Por fin te encuentro!"},{"a":"yami","t":"¡El caballero bobo!"},{"a":"argon","t":"¡Oye, que no he venido a pelear!"},{"a":"yami","t":"No caeré en tus trucos, perro faldero."},{"a":"argon","t":"Fallaste a posta, ¿verdad?"},{"a":"yami","t":"¡...!"},{"a":"argon","t":"Te vi en el banquete. Hasta parecía que te arrepentías de haber lanzado la shuriken."},{"a":"argon","t":"El Rey no es mala persona, ¿sabes? Es un poco rarito a veces, pero lo hace lo mejor que puede."},{"a":"argon","t":"No sé quién te ha pagado para hacer esto, pero seguro que no son buena gente."},{"a":"argon","t":"¿Por qué no vuelves al castillo y te disculpas? Estoy seguro de que Reinhold..."},{"a":"yami","t":"¿Disculparme? Vaya idea."},{"a":"yami","t":"Tengo muchas cosas en las que pensar. Si aprecias tu vida, será mejor que no me sigas."},{"a":"argon","t":"Estoy seguro de que no es mala persona."},{"a":"argon","t":"Ahora tengo que dar parte a Sia."},{"a":"argon","t":"Buf, me va a caer una buena bronca."}]},{"id":"yami_05","i":5,"title":"A la luz de la luna","req":"yami:5","reward":{"k":"gems","id":"gems","q":10,"n":"Joyas"},"side":false,"lines":[{"a":"fabric","t":"<sprite tint=1 name=Note1>Los rayos de sol se cuelan entre los sauces, con el brillo de tiempos pasados<sprite tint=1 name=Note2>..."},{"a":"fabric","t":"<sprite tint=1 name=Note2>En el claro del bosque... ¡Ah!"},{"a":"yami","t":"La punta fría que sientes es mi espada en tu cuello."},{"a":"yami","t":"Tengo unas preguntas. Si respondes con sinceridad, puede que te perdone la vida."},{"a":"fabric","t":"¡Aaah! ¡Ss... sí! Lo que... ¡Ay!"},{"a":"yami","t":"Silencio."},{"a":"yami","t":"Ese idiota al que llamas rey... Háblame de él."},{"a":"fabric","t":"¿El rey Reinhold? Es el gobernante de esta tierra..."},{"a":"fabric","t":"Es bastante excéntrico, pero sus virtudes y su generosidad saltan a la vista."},{"a":"fabric","t":"Aunque le falta experiencia, lo compensa gracias a su consejera más reciente, Sia."},{"a":"yami","t":"¡No puede ser! Tus palabras están impregnadas de cobardía, pero parecen sinceras."},{"a":"yami","t":"¿Hay un oráculo en esta ciudad?"},{"a":"fabric","t":"¡Sí! La elfa, Serene. Está en lo alto de la colina."},{"a":"fabric","t":"Forastera misteriosa... ¿Serías tan amable de decirme tu nom...? ¡Ah!"},{"a":"yami","t":"Hace unos días no hubiera dudado un momento en matarte, así que no abuses de tu suerte."},{"a":"yami","t":"Retoma tu insulsa vida insulsa y borra de tu memoria lo que ha pasado aquí."},{"a":"fabric","t":"¡Uf! ¡Qué encuentro tan emocionante!"},{"a":"fabric","t":"Dama de negro... Me pregunto si volveremos a vernos."}]},{"id":"yami_06","i":6,"title":"Peón roto","req":"yami:6","reward":{"k":"gems","id":"gems","q":10,"n":"Joyas"},"side":false,"lines":[{"a":"mana","t":"Una brisa oscura delata una presencia acechante."},{"a":"yami","t":"¡¿Cómo...?!"},{"a":"mana","t":"La que acecha camina ligera como una pluma, pero el peso de su corazón la delata ante el tercer ojo."},{"a":"yami","t":"Basta de payasadas, oráculo. Necesito respuestas."},{"a":"yami","t":"Sobre la orden..., mi familia."},{"a":"mana","t":"Una mercader de la muerte que solicita orientación... ¿Y qué ofrece a cambio?"},{"a":"yami","t":"Tu vida."},{"a":"mana","t":"Que así sea."},{"a":"mana","t":"<c1>La orden azumana, que antes buscaba remediar injusticias...</c1>"},{"a":"mana","t":"<c1>Defensores del orden que se convirtieron en esclavos del mejor postor...</c1>"},{"a":"mana","t":"<c1>Ante una tarea imposible, se sacrifica a un peón...</c1>"},{"a":"mana","t":"<c1>Ya sea que lo consiga o no, la orden sale victoriosa.</c1>"},{"a":"yami","t":"Imposible."},{"a":"mana","t":"La mensajera ha hablado."},{"a":"yami","t":"¡Imposible!"},{"a":"mana","t":"..."},{"a":"mana","t":"Con el tiempo, la que acecha entre las sombras tendrá que hacer las paces con la luz."}]},{"id":"yami_07","i":7,"title":"Peón roto","req":"yami:7","reward":{"k":"gems","id":"gems","q":10,"n":"Joyas"},"side":false,"lines":[{"a":"yami","t":"Tengo que recoger mis cosas y marcharme de aquí cuanto antes."},{"a":"inn","t":"Hola, forastera misteriosa."},{"a":"yami","t":"Posadero, he pagado dinero de más para que te calles."},{"a":"inn","t":"Tranquila, en la Posada de la Esmeralda no somos unos chismosos."},{"a":"inn","t":"Aun así, quiero que sepas que han venido clientes con cara de pocos amigos buscándote."},{"a":"yami","t":"(¿Los sicarios de la orden ya se han puesto en marcha?)."},{"a":"inn","t":"No dijeron ningún nombre. Tenían pinta sospechosa... ¿Son tus amigos?"},{"a":"yami","t":"Ya no. Diles que estoy muerta. Seguramente no tarde en hacerse realidad."},{"a":"inn","t":"Tienes prisa, ¿eh? Me lo imaginé, así que te he preparado unas provisiones."},{"a":"yami","t":"Gracias, posadero, pero no serán necesarias en el lugar al que voy."}]},{"id":"yami_08","i":8,"title":"Viaje sin retorno","req":"yami:8","reward":{"k":"gems","id":"gems","q":10,"n":"Joyas"},"side":false,"lines":[{"a":"sia","t":"Así que a Chapitel Lóbrego..."},{"a":"wood","t":"Sí, vi a una chica con aspecto de ninja que coincidía con la descripción. Parecía tener prisa."},{"a":"sia","t":"Excelente. Hemos encontrado a nuestra asesina."},{"a":"sia","t":"Voy a organizar una patrulla para que..."},{"a":"wood","t":"¿Estás segura? No creo que sea necesario."},{"a":"sia","t":"¿Por qué no, Gorza?"},{"a":"wood","t":"Una expedición a Chapitel Lóbrego en solitario es una muerte segura. La chica no lleva ningún tipo de provisiones."},{"a":"wood","t":"Es imposible que no fuera consciente de ello. Ni siquiera Rudo es tan idiota como para ir allí solo."},{"a":"sia","t":"Ya veo... Lo tendré en cuenta. Gracias, Gorza."},{"a":"sia","t":"Supongo que este problema se resuelve solo, pero..."},{"a":"sia","t":"... tengo un mal presentimiento. ¿Qué tramas, asesina?"}]},{"id":"yami_09","i":9,"title":"Enfrentamiento en Chapitel Lóbrego (Yami)","req":"yami:9","reward":{"k":"gems","id":"gems","q":10,"n":"Joyas"},"side":false,"lines":[{"a":"argon","t":"Esto debe ser cosa del destino. ¡Mucho mejor que una arpía!"},{"a":"yami","t":"Adelante. Acabaré contigo aquí y ahora."},{"a":"argon","t":"Dices eso, pero no pareces convencida de ello."},{"a":"yami","t":"Tienes razón... Ya nada me importa."},{"a":"yami","t":"Si quieres acabar con mi vida, solo tienes que dejarme morir aquí."},{"a":"argon","t":"¡Jamás permitiría una cosa así! Te llevaré ante el rey Reinhold."},{"a":"argon","t":"Sé que él entenderá tu situación. No me importa tener que cargarte a la espalda."},{"a":"yami","t":"..."},{"a":"argon","t":"¡Vamos, sube!"},{"a":"argon","t":"Estás en los huesos... ¿Cuándo has comido por última vez?"},{"a":"yami","t":"..."},{"a":"argon","t":"Come algo durante el camino, porque va a ser escabroso."}]},{"id":"yami_10","i":10,"title":"Tras las líneas enemigas","req":"argon:10","reward":{"k":"gems","id":"gems","q":10,"n":"Joyas"},"side":false,"lines":[{"a":"sia","t":"Guardias, traed refuerzos y no la perdáis de vista ni un segundo."},{"a":"sia","t":"Argon, espera fuera mientras hablamos con la intrusa."},{"a":"argon","t":"¡Ya!"},{"a":"sia","t":"Habla, asesina."},{"a":"yami","t":"En efecto, me contrataron para que asesinara a un tirano."},{"a":"yami","t":"O eso pensaba yo... Parece que no es más que un bufón benevolente."},{"a":"king","t":"¡¿Bufón?!"},{"a":"sia","t":"¿Qué problema tiene tu gente con nuestro rey?"},{"a":"yami","t":"Mi orden solo ataca en nombre de la justicia..."},{"a":"yami","t":"Sin embargo, parece que todo era mentira. A causa de mi fracaso, también vendrán a por mí."},{"a":"yami","t":"Yo... lo siento. Aceptaré cualquier castigo que me impongáis..."},{"a":"yami","t":"Ah..."},{"a":"king","t":"¡Se ha desmayado!"},{"a":"sia","t":"Está agotada y desnutrida..."},{"a":"sia","t":"¡Guardias! Llevad a nuestros mejores médicos a su cama."},{"a":"sia","t":"Tratadla con el respeto que se merecería una invitada de la realeza."}]},{"id":"yami_epilogue","i":11,"title":"Epílogo","req":"yami:10","reward":{"k":"gems","id":"gems","q":10,"n":"Joyas"},"side":false,"lines":[{"a":"sia","t":"Uff... Uff... Qué complicado es llegar..."},{"a":"yami","t":"Este es mi hogar ahora."},{"a":"sia","t":"¿Por qué no quieres vivir dentro de los muros de la ciudad? Has recibido el perdón."},{"a":"yami","t":"Seguramente mi clan piense que estoy muerta, y prefiero mantener esa mentira."},{"a":"sia","t":"Lo comprendo. Me aseguraré de que recibas provisiones frecuentemente."},{"a":"sia","t":"En cuanto a tu próxima tarea..."},{"a":"yami","t":"¿Más matones del Imperio?"},{"a":"sia","t":"Así es. Como ya sabrás, el rey despierta mucha envidia."},{"a":"sia","t":"Consulta este documento para obtener más información sobre tus objetivos."},{"a":"yami","t":"Yo me ocupo."},{"a":"sia","t":"Me fastidia decirlo, pero te creo."},{"a":"sia","t":"Bueno, debo regresar, aunque no me agrada la idea de realizar el viaje de vuelta..."},{"a":"yami","t":"Sia... Reinhold..."},{"a":"yami","t":"Gracias, de corazón."}]}]}];
